  Stage_118133_Desc = {
    Text = "在漫长调查的尾声，为抚慰调查员疲惫的灵魂，弥萨格大学有一项传统：为他们奉上一段由海风与阳光款待的悠闲假日。\n\n而今天，这份来自守密人的赠礼，专为神母而备。"
  },
  Stage_118133_Name = {
    Text = "神母假日"
  },
  Stage_118134_Desc = {
    Text = "在漫长调查的尾声，为抚慰调查员疲惫的灵魂，弥萨格大学有一项传统：为他们奉上一段由海风与阳光款待的悠闲假日。\n\n而今天，这份来自守密人的赠礼，专为神母而备。"
