  Stage_118134_Name = {
    Text = "神母假日"
  },
  Stage_118135_Desc = {
    Text = "自如游走于漩涡临界，只是脆弱船只的幻觉。\n在肉眼不可见的涡流之中，蕴藏着足以吞噬和绞杀所有心怀侥幸者的庞大吸力。"
  },
  Stage_118135_Name = {Text = "漩涡"},
  Stage_118136_Desc = {
    Text = "跳吧，跳下去吧，亲爱的长发公主。\n在那坠落之地，定会有骑士温暖坚毅的怀抱。"
  },
  Stage_118136_Name = {
    Text = "高塔公主"
  },
  Stage_118137_Desc = {
    Text = "此处名为「乐园号」，是蹈海者教会永恒而唯一的海上据地。\n是她的灵魂寄托之地，触手可及的理想乡。"
  },
  Stage_118137_Name = {
    Text = "「乐园号」"
  },
  Stage_118138_Desc = {
    Text = "「我不说我的爱如何高尚，我只说想到你的夜晚我能安然入睡。」"
  },
  Stage_118138_Name = {Text = "局外人"},
  Stage_118139_Desc = {
    Text = "圣女高高地站上祭坛，俯瞰着熊熊燃烧的火焰。\n那跃动的火舌在她眼中映照出的，不是恐惧，而是终于到来的宿命。\n她能听见柴薪爆裂的噼啪声，和体内神谕渐逝的回响。\n这一刻，她不再是被缚的囚徒。"
  },
  Stage_118139_Name = {
    Text = "引航典仪"
  },
  Stage_118140_Desc = {
    Text = "骑士厉兵秣马、披坚执锐，斩向飞驰而来的风车。"
  },
  Stage_118140_Name = {
    Text = "风车骑士"
  },
  Stage_118141_Desc = {
