  },
  Stage_118141_Name = {Text = "诞妄"},
  Stage_118142_Desc = {
    Text = "她被什么束缚？\n职责、命运与爱。"
  },
  Stage_118142_Name = {Text = "枷锁"},
  Stage_118143_Desc = {
