  Stage_119838_Desc = {
    Text = "你听到了群星的歌谣，在这无垠的宇宙里。\n但真空无法传声，因此无论是你的呐喊，还是他们的狂啸，都寂静无音。"
  },
  Stage_119838_Name = {
    Text = "死寂韵律"
  },
  Stage_119839_Desc = {
    Text = "群星在聚焦它们的视线，而你，也在校准自己的仪器。\n一首关于死亡与杀戮的音乐，即将奏起。"
  },
  Stage_119839_Name = {
    Text = "失谐序曲"
  },
  Stage_119840_Desc = {
