  Stage_122140_Name = {
    Text = "支配四肢·之二"
  },
  Stage_122141_Desc = {
    Text = "在这宏大而混沌的宇宙里，一个小小的、随波逐流于某个星球的生命，已不再燃烧。\n这微弱的光，永远不被看见，也永远不会再被点燃。"
  },
  Stage_122141_Name = {
    Text = "熄灭的群星"
