  },
  Stage_122177_Desc = {
    Text = "神啊，请告诉我正确的道路，让我不至于迷途，能够坚定无畏的走向那被引导的正路。"
  },
  Stage_122177_Name = {
    Text = "迷途羔羊"
  },
  Stage_122178_Desc = {
    Text = "哦，我看到了，真正有趣的世界。"
  },
  Stage_122178_Name = {
    Text = "蒙蔽双眼·癫狂"
  },
  Stage_122179_Desc = {
    Text = "永远追求理想，追求光明，追求希望。\n哪怕这代价是献祭自己。\n神啊，我只希望我正坚定无畏走向的那条路，是你引导的正路。"
  },
  Stage_122179_Name = {
    Text = "以自身为献祭"
  },
