  },
  Stage_122185_Name = {
    Text = "切割阑尾·之六"
  },
  Stage_122186_Desc = {
    Text = "平凡的日常就如无用的阑尾，是时候切割掉了~"
  },
  Stage_122186_Name = {
    Text = "切割阑尾·之一"
  },
  Stage_122601_Name = {
    Text = "茉夏试玩关卡"
  },
  Stage_123112_Desc = {
    Text = "迷雾遮住了我的眼睛，令我失去了与自己世界的联系，但透过你的双眸，我看见了那些再回不去的过往，再无法见到的人。\n我们是相似的。"
  },
  Stage_123112_Name = {
    Text = "透过你的双眸"
  },
  Stage_123113_Desc = {
    Text = "迷雾遮住了我的眼睛，令我失去了与自己世界的联系，但透过你的双眸，我看见了那些再回不去的过往，再无法见到的人。\n我们是相似的。"
  },
  Stage_123113_Name = {
    Text = "透过你的双眸"
  },
  Stage_125199_Desc = {
    Text = "唯有耽于爱的虫豸，才如此脆弱，如此坚韧，如此可笑，又如此非凡。\n哎呀，与妾身去看看更美妙的东西吧， 你们将彼此照应，你们将从此紧密相连。"
  },
  Stage_125199_Name = {
    Text = "罗织·之三"
  },
  Stage_125200_Desc = {
    Text = "情热总有归处，不总是归于偕老，归于枉死的时候或许更多。\n有时枉死的是爱，有时枉死的是你。"
  },
  Stage_125200_Name = {
    Text = "枉死·癫狂"
  },
  Stage_125201_Desc = {
    Text = "旧爱已离你而去，你为何此时才开始痛悔？\n嘻嘻，不迟，不急，看呀——郎君。只要日头落下，每一盏灯，每一根红烛， 都会在窗后映出她的形，她的影。"
  },
  Stage_125201_Name = {
    Text = "窗后影·之二"
  },
  Stage_125202_Desc = {
    Text = "「……如蝉留皮换骨，谓之尸解而登仙……」\n哦，其实不是， 那是一段荒唐谬闻，但有什么关系呢？她们以血泪祈愿，于是令人战栗的美与恐惧从中苏生。"
  },
  Stage_125202_Name = {
    Text = "尸解·之六"
  },
  Stage_125203_Desc = {
    Text = "旧爱已离你而去，你为何此时才开始痛悔？\n嘻嘻，不迟，不急，看呀——郎君。只要日头落下，每一盏灯，每一根红烛， 都会在窗后映出她的形，她的影。"
  },
  Stage_125203_Name = {
    Text = "窗后影·之一"
  },
  Stage_125204_Desc = {
    Text = "祂们共同跪伏于香案供桌之下，那无相的玄女无可探知，无从界定，无法违逆。\n献上所有，依从所有，登临唯一的极乐，永远的混乱。"
  },
  Stage_125204_Name = {
    Text = "极乐·癫狂"
  },
  Stage_125205_Desc = {
    Text = "妾身喜欢你的气味，妾身会替你尝一尝你的仇人。"
  },
  Stage_125205_Name = {
    Text = "循香·之二"
  },
  Stage_125206_Desc = {
    Text = "那神秘的结社游离于东方古国的史书之外，它无法被探知，无法被界定，唯有极少数迄今仍未消亡，永居在无梦乡的个体，曾经获知过它所祭拜的神明的名讳。\n她被唤作——「@4」"
  },
  Stage_125206_Name = {
    Text = "臃容众·之一"
  },
  Stage_125207_Desc = {
    Text = "祂们共同跪伏于香案供桌之下，那无相的玄女无可探知，无从界定，无法违逆。\n献上所有，依从所有，登临唯一的极乐，永远的混乱。"
  },
  Stage_125207_Name = {
    Text = "极乐·之六"
  },
  Stage_125208_Desc = {
    Text = "喀啦——吸溜——咕啾——唔——\n我们会永远厮守，我们会永远厮守。\n我们会永远永远永远厮守厮守厮守厮守厮守守守守守守守@4"
  },
