  Stage_125638_Name = {
    Text = "雾都未醒"
  },
  Stage_125639_Desc = {
    Text = "卡德林庄园热衷于看到辉煌与衰落的戏码。只有懂得取悦庄园的人，才能得到请柬。"
  },
  Stage_125639_Name = {
    Text = "庄园的请柬"
  },
  Stage_125640_Desc = {
    Text = "除了记忆，我们一无所有。"
