  },
  Stage_125647_Name = {Text = "重圆"},
  Stage_125648_Desc = {
    Text = "亲爱的囚徒，与一切告别吧。命运的判决从不需要律法。"
  },
  Stage_125648_Name = {Text = "判决"},
  Stage_125649_Desc = {
