  },
  Stage_125663_Name = {Text = "茧"},
  Stage_126202_Desc = {
    Text = "鲜花，欢呼，掌声。世界重新回到它身边。\n叙事的魔术师完成了它的表演，观众的记忆在优雅的谢幕中消散。\n没有任何的秘密，能从舞台的废墟上离开。"
