  Stage_129163_Name = {
    Text = "疾驰的欢愉专列·普通"
  },
  Stage_129164_Name = {
    Text = "疾驰的欢愉专列·困难"
  },
  Stage_129165_Name = {
    Text = "疾驰的欢愉专列·癫狂"
  },
  Stage_129500_Desc = {
    Text = "磐龙古国的每个祈岁节，无论天南海北，家家户户都要团圆。\n他们在祈岁节将至时登上通往远方的列车，怀抱着憧憬的心期盼着久别重逢的时刻。"
  },
  Stage_129500_Name = {
    Text = "祈岁列车"
  },
  Stage_129501_Desc = {
    Text = "别害怕，这只是一场游戏。\n一场残忍的、恶劣的游戏。"
  },
  Stage_129501_Name = {
    Text = "游戏开始"
  },
  Stage_129502_Desc = {
    Text = "别停下，别退让。\n如果善意的人放下了手中的枪，那么邪恶便会乘胜追击。"
  },
  Stage_129502_Name = {
    Text = "第二名死者"
  },
  Stage_129503_Desc = {
    Text = "这是属于正义的绝地反击……吗？"
  },
  Stage_129503_Name = {
    Text = "隐藏的杀招"
  },
  Stage_129504_Desc = {
    Text = "那支拉杆经常在你梦里出现。\n推动它，还是拉下它，这是一个问题。"
  },
  Stage_129504_Name = {
    Text = "常暗之厢"
  },
  Stage_129505_Desc = {
    Text = "焰火连天辞旧岁，往日湮灰不可追。"
  },
  Stage_129505_Name = {
    Text = "往日焰火"
  },
  Stage_130109_Desc = {
    Text = "人要上学，唤醒体也要上学。\n现在她是唤醒体了，她当然也要上学。\n请务必注意安全。"
  },
  Stage_130109_Name = {
    Text = "学校·之二"
  },
  Stage_130110_Desc = {
    Text = "如何成为传奇调查员？首先，每一口深井都藏着许许多多的秘密。\n其次，闯进井底之前，记得散弹枪并不一定非得合法持有。"
  },
  Stage_130110_Name = {
    Text = "水井·之六"
  },
  Stage_130111_Desc = {
    Text = "如何成为传奇调查员？首先，每一口深井都藏着许许多多的秘密。\n其次，闯进井底之前，记得散弹枪并不一定非得合法持有。"
  },
  Stage_130111_Name = {
    Text = "水井·之二"
  },
  Stage_130112_Desc = {
    Text = "没错，即便是传奇调查员，也未必每次都能获得胜利。\n……但没关系，伏特加还剩最后一滴。"
  },
  Stage_130112_Name = {
    Text = "最后的小酌·之四"
  },
  Stage_130113_Desc = {
    Text = "相爱的人们共进晚餐，倾诉彼此的心声。\n食物听到了许多秘密，但理所当然，祂们从不说话。"
  },
