  },
  Stage_130144_Name = {
    Text = "餐桌·之五"
  },
  Stage_130145_Desc = {
    Text = "没错，即便是传奇调查员，也未必每次都能获得胜利。\n……但没关系，伏特加还剩最后一滴。"
  },
  Stage_130145_Name = {
    Text = "最后的小酌·之六"
  },
  Stage_130146_Desc = {
    Text = "人要上学，唤醒体也要上学。\n现在她是唤醒体了，她当然也要上学。\n请务必注意安全。"
  },
  Stage_130146_Name = {
    Text = "学校·之一"
  },
  Stage_130147_Desc = {
    Text = "如何成为传奇调查员？首先，每一口深井都藏着许许多多的秘密。\n其次，闯进井底之前，记得散弹枪并不一定非得合法持有。"
  },
  Stage_130147_Name = {
    Text = "水井·之一"
  },
  Stage_130148_Desc = {
    Text = "每一场雨都会停歇，每一场梦都会终结。\n请再呼吸一口潮湿的空气，让雨的余韵晚一点离开。"
  },
  Stage_130148_Name = {Text = "雨霁时"},
  Stage_130149_Desc = {
    Text = "没错，即便是传奇调查员，也未必每次都能获得胜利。\n……但没关系，伏特加还剩最后一滴。"
  },
  Stage_130149_Name = {
    Text = "最后的小酌·之一"
  },
  Stage_130150_Desc = {
