  },
  Stage_130152_Desc = {
    Text = "相爱的人们共进晚餐，倾诉彼此的心声。\n食物听到了许多秘密，但理所当然，祂们从不说话。"
  },
  Stage_130152_Name = {
    Text = "餐桌·之一"
  },
  Stage_130153_Desc = {
    Text = "种子从文本中探寻爱的定义。\n但谁也说不清爱究竟是什么，只能否认那些并非爱的情感。\n直到被它轰然击中的刹那。"
  },
  Stage_130153_Name = {Text = "「爱」"},
  Stage_130154_Desc = {
    Text = "世界会在顷刻之间变成炼狱——果真如此吗？\n有没有可能它从来没有过任何变化，只不过在此之前，你一直在忍耐。"
  },
  Stage_130154_Name = {
    Text = "脑损伤·癫狂"
  },
  Stage_130155_Desc = {
    Text = "如歌，如诗，如梦。"
  },
  Stage_130155_Name = {
    Text = "心象风景"
  },
  Stage_130156_Desc = {
    Text = "把天花板涂成喜欢的颜色，把墙壁涂成喜欢的颜色。\n把冰箱装满喜欢的食物，养我们都喜欢的宠物。\n这是只属于你和我的家。"
  },
  Stage_130156_Name = {
    Text = "家·之三"
  },
  Stage_130157_Desc = {
    Text = "把天花板涂成喜欢的颜色，把墙壁涂成喜欢的颜色。\n把冰箱装满喜欢的食物，养我们都喜欢的宠物。\n这是只属于你和我的家。"
  },
  Stage_130157_Name = {
    Text = "家·之五"
  },
  Stage_130158_Desc = {
    Text = "医院是一个不可思议的地方，同时汇聚了新生、离世、重生、世间最大的痛苦，和世间最大的喜悦。\n然而，人们的喜悦、悲伤，以及所有的情感，却彼此之间完全无法相通。"
  },
  Stage_130158_Name = {
    Text = "医院·之六"
  },
  Stage_130159_Desc = {
