  },
  Stage_130160_Name = {
    Text = "医院·之三"
  },
  Stage_130161_Desc = {
    Text = "在一千一万个梦境中，你牵起她的手。\n隐秘的电流从你们的链接中穿行而过，形成永不消逝的循环。\n聆听它的呼唤，寻找她，找到她。\n即使被血肉吞没。"
  },
