  Stage_130819_Desc = {
    Text = "阳光穿过窗户，洒向散发橡木香气的课桌。\n书本散落一旁，莫丝懒洋洋地趴在桌上。\n「诺缔拉Zzz……小煤球Zzz……开心~」\n长久的冰冷和孤独已经结束。\n接下来是更更好的明天。"
  },
