  },
  Stage_139577_Desc = {
    Text = "太好了，这些……不不不，我是说这些黑猫太坏了！"
  },
  Stage_139577_Name = {Text = "黑金潮"},
  Stage_139578_Desc = {
    Text = "银芯和金券装满口袋，得胜的将军满载而归。"
