  Stage_139580_Desc = {
    Text = "不过猫还有很多，让我们再来……最后一次？"
  },
  Stage_139580_Name = {
    Text = "再来一次"
  },
  Stage_139581_Desc = {
    Text = "当第一缕银色闪耀在漆黑的海洋里时，你手上的捕猫网挥得更有力气了。"
  },
  Stage_139581_Name = {
    Text = "第一桶银芯"
  },
  Stage_139582_Desc = {
