  Stage_141235_Desc = {
    Text = "你喜欢玩游戏，你把一切都视为闹剧。所以我们会割开那些信徒的喉管，踩碎他们的脊梁，让他们知道自己在信仰多么愚蠢可笑的脏东西。\n一直逃吧，否则，你就会发现连湮灭都只是美妙的妄想。"
  },
  Stage_141235_Name = {
    Text = "追逃游戏·之一"
  },
  Stage_141236_Desc = {
    Text = "易于取得的、美味的、坚固的、紧密的、令人窒息的。\n脆弱的。\n它就存在于此。"
  },
  Stage_141236_Name = {
    Text = "肋软骨·之六"
  },
  Stage_141237_Desc = {
    Text = "是的，我当然知道。\n自始至终，都只有「我」，没有「我们」。"
  },
  Stage_141237_Name = {
    Text = "剖白·癫狂"
  },
  Stage_141238_Desc = {
    Text = "猎手与猎物的立场时常在一瞬间转换，万千年来，循环往复，直到一方学会了使用工具，直到一方掌握了真正的力量。"
  },
  Stage_141238_Name = {
    Text = "森林法典·之五"
  },
  Stage_141239_Desc = {
    Text = "他被比海洋更古老的存在选中了，他留在了那个他回不去的地方。"
  },
  Stage_141239_Name = {
    Text = "哨音·之六"
  },
  Stage_141240_Desc = {
    Text = "最热闹的食物，最适合庆祝的食物，我们举杯，我们相聚。\n没有人在意一具具躯壳下是不是同一个意志，没有人在意一具具空壳下还有没有灵魂。"
  },
  Stage_141240_Name = {
    Text = "麦酒与香料·之四"
  },
  Stage_141241_Desc = {
    Text = "最热闹的食物，最适合庆祝的食物，我们举杯，我们相聚。\n没有人在意一具具躯壳下是不是同一个意志，没有人在意一具具空壳下还有没有灵魂。"
