  Stage_141286_Desc = {
    Text = "他被比海洋更古老的存在选中了，他留在了那个他回不去的地方。"
  },
  Stage_141286_Name = {
    Text = "哨音·之二"
  },
  Stage_141287_Desc = {
    Text = "是的，我当然知道。\n自始至终，都只有「我」，没有「我们」。"
  },
  Stage_141287_Name = {
    Text = "剖白·之四"
  },
  Stage_141288_Desc = {
    Text = "他被比海洋更古老的存在选中了，他留在了那个他回不去的地方。"
  },
  Stage_141288_Name = {
    Text = "哨音·之三"
  },
  Stage_141289_Desc = {
    Text = "祂不易察觉，祂悄无声息，祂突如其来。\n人们在蓬勃的日子里事不关己地提起祂的名字，直到人们察觉，祂已成为如影随形的朋友。\n"
  },
  Stage_141289_Name = {Text = "原因"},
  Stage_141290_Desc = {
    Text = "最热闹的食物，最适合庆祝的食物，我们举杯，我们相聚。\n没有人在意一具具躯壳下是不是同一个意志，没有人在意一具具空壳下还有没有灵魂."
  },
  Stage_141290_Name = {
    Text = "麦酒与香料·之一"
  },
  Stage_141291_Desc = {
    Text = "猎手与猎物的立场时常在一瞬间转换，万千年来，循环往复，直到一方学会了使用工具，直到一方掌握了真正的力量。"
  },
  Stage_141291_Name = {
    Text = "森林法典·之四"
  },
  Stage_141742_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n有一只寻找同伴的孤号鸟，他的同伴失去了翅膀，他的同伴被拔光了羽毛。\n他试图实现实现不了的愿望，他的同伴连与他的回忆都忘掉。\n ♬~~♫~~♪~~♫~~♪~~♫~~\n没关系，没关系。他们还有甜美的、甜美的、共同的归宿。他们会进入安宁的、安宁的、永不被打扰的梦乡。"
  },
  Stage_141742_Name = {
    Text = "羽毛·之三"
  },
  Stage_141743_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n有一只寻找同伴的孤号鸟，他的同伴失去了翅膀，他的同伴被拔光了羽毛。\n他试图实现实现不了的愿望，他的同伴连与他的回忆都忘掉。\n ♬~~♫~~♪~~♫~~♪~~♫~~\n没关系，没关系。他们还有甜美的、甜美的、共同的归宿。他们会进入安宁的、安宁的、永不被打扰的梦乡。"
  },
  Stage_141743_Name = {
    Text = "羽毛·之六"
  },
  Stage_141744_Desc = {
    Text = "喜欢我的故事吗？不喜欢？诶？！到底要怎么说你才会相信嘛，好啦，不要再追根究底啦，那样会很让人伤心的哦？\n来咬一口这个苹果吧，超级甜，我保证是真的！\n就和这个故事里的每一个字一样真！"
  },
  Stage_141744_Name = {
    Text = "苹果·癫狂"
  },
  Stage_141745_Desc = {
    Text = "喜欢我的故事吗？不喜欢？诶？！到底要怎么说你才会相信嘛，好啦，不要再追根究底啦，那样会很让人伤心的哦？\n来咬一口这个苹果吧，超级甜，我保证是真的！\n就和这个故事里的每一个字一样真！"
