  Stage_141746_Desc = {
    Text = "喜欢我的故事吗？不喜欢？诶？！到底要怎么说你才会相信嘛，好啦，不要再追根究底啦，那样会很让人伤心的哦？\n来咬一口这个苹果吧，超级甜，我保证是真的！\n就和这个故事里的每一个字一样真！"
  },
  Stage_141746_Name = {
    Text = "苹果·之一"
  },
  Stage_141747_Desc = {
    Text = "是的，是的，人是可以倒霉到这个地步的。\n她的一生除了谎言什么都没有，她这一次相信，下一次依旧，她就因为一点点希望，吞下了所有谎言的苦果。\n所以在这场谎言的尽头，在她一生的尽头……\n我们在她的眼睛里，除了仇恨，什么都找不到。"
  },
  Stage_141747_Name = {
    Text = "眼睛·癫狂"
  },
  Stage_141748_Desc = {
    Text = "故事进行到这里，你开始有一些踌躇。\n线索明明在一开始已经出现，命运牵引你来见证什么呢？丝线的彼端，连接着什么样的真相呢？\n雪下面埋藏着什么，到底有几个人能够所愿得偿？\n你不知道，旅途还未过半，你只能继续顺应它的指引。"
  },
  Stage_141748_Name = {
    Text = "丝线·之六"
  },
