    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n有一只寻找同伴的孤号鸟，他的同伴失去了翅膀，他的同伴被拔光了羽毛。\n他试图实现实现不了的愿望，他的同伴连与他的回忆都忘掉。\n ♬~~♫~~♪~~♫~~♪~~♫~~\n没关系，没关系。他们还有甜美的、甜美的、共同的归宿。他们会进入安宁的、安宁的、永不被打扰的梦乡。"
  },
  Stage_141749_Name = {
    Text = "羽毛·之四"
  },
  Stage_141750_Desc = {
    Text = "哦，小小的神明的碎片，卡达斯的救世主，一切毁灭的希望，一切绝境中的新生，弥萨格唯一的守密人。\n你紧紧握住了陪你走到至今的钥匙，你的内心充满了决心。\n好的，那句话怎么说来着……？愿银钥指引我们！"
  },
  Stage_141750_Name = {
    Text = "钥匙·之三"
  },
  Stage_141751_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n小小的女孩在路上太久太久啦，孤独压在她的肩膀上，思念蚕食着她的心。\n她在哪里都找不到，每一个办法都不奏效。\n♬~~♫~~♪~~♫~~♪~~♫~~\n没关系，没关系，女孩想找的一切都在镜子里，镜子映照着天上的月亮，月亮落入了镜中的涟漪。"
  },
  Stage_141751_Name = {
    Text = "镜子·之一"
  },
