    Text = "故事进行到这里，你开始有一些踌躇。\n线索明明在一开始已经出现，命运牵引你来见证什么呢？丝线的彼端，连接着什么样的真相呢？\n雪下面埋藏着什么，到底有几个人能够所愿得偿？\n你不知道，旅途还未过半，你只能继续顺应它的指引。"
  },
  Stage_141780_Name = {
    Text = "丝线·之五"
  },
  Stage_141781_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n小小的女孩在路上太久太久啦，孤独压在她的肩膀上，思念蚕食着她的心。\n她在哪里都找不到，每一个办法都不奏效。\n♬~~♫~~♪~~♫~~♪~~♫~~\n没关系，没关系，女孩想找的一切都在镜子里，镜子映照着天上的月亮，月亮落入了镜中的涟漪。"
  },
  Stage_141781_Name = {
    Text = "镜子·癫狂"
  },
  Stage_141782_Desc = {
    Text = "喜欢我的故事吗？不喜欢？诶？！到底要怎么说你才会相信嘛，好啦，不要再追根究底啦，那样会很让人伤心的哦？\n来咬一口这个苹果吧，超级甜，我保证是真的！\n就和这个故事里的每一个字一样真！"
  },
  Stage_141782_Name = {
    Text = "苹果·之四"
  },
  Stage_141783_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n有一只寻找同伴的孤号鸟，他的同伴失去了翅膀，他的同伴被拔光了羽毛。\n他试图实现实现不了的愿望，他的同伴连与他的回忆都忘掉。\n ♬~~♫~~♪~~♫~~♪~~♫~~\n没关系，没关系。他们还有甜美的、甜美的、共同的归宿。他们会进入安宁的、安宁的、永不被打扰的梦乡。"
  },
  Stage_141783_Name = {
    Text = "羽毛·癫狂"
  },
  Stage_141784_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n有一只寻找同伴的孤号鸟，他的同伴失去了翅膀，他的同伴被拔光了羽毛。\n他试图实现实现不了的愿望，他的同伴连与他的回忆都忘掉。\n ♬~~♫~~♪~~♫~~♪~~♫~~\n没关系，没关系。他们还有甜美的、甜美的、共同的归宿。他们会进入安宁的、安宁的、永不被打扰的梦乡。"
  },
  Stage_141784_Name = {
    Text = "羽毛·之二"
  },
  Stage_141785_Desc = {
    Text = "哦，小小的神明的碎片，卡达斯的救世主，一切毁灭的希望，一切绝境中的新生，弥萨格唯一的守密人。\n你紧紧握住了陪你走到至今的钥匙，你的内心充满了决心。\n好的，那句话怎么说来着……？愿银钥指引我们！"
  },
  Stage_141785_Name = {
    Text = "钥匙·之四"
  },
  Stage_141786_Desc = {
    Text = "哦，小小的神明的碎片，卡达斯的救世主，一切毁灭的希望，一切绝境中的新生，弥萨格唯一的守密人。\n你紧紧握住了陪你走到至今的钥匙，你的内心充满了决心。\n好的，那句话怎么说来着……？愿银钥指引我们！"
  },
  Stage_141786_Name = {
    Text = "钥匙·之二"
  },
  Stage_141787_Desc = {
    Text = "其他的事情我们都清楚，但王冠为什么会在这个地方出现？？是谁这么不小心，着了骗子的道？\n这显然不是这部分我们要考虑的内容，欲知后事如何……\n下一个故事的时候再解释吧！"
  },
  Stage_141787_Name = {
    Text = "王冠·之六"
  },
  Stage_141788_Desc = {
    Text = "是的，是的，人是可以倒霉到这个地步的。\n她的一生除了谎言什么都没有，她这一次相信，下一次依旧，她就因为一点点希望，吞下了所有谎言的苦果。\n所以在这场谎言的尽头，在她一生的尽头……\n我们在她的眼睛里，除了仇恨，什么都找不到。"
  },
  Stage_141788_Name = {
    Text = "眼睛·之一"
  },
  Stage_141789_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n小小的女孩在路上太久太久啦，孤独压在她的肩膀上，思念蚕食着她的心。\n她在哪里都找不到，每一个办法都不奏效。\n♬~~♫~~♪~~♫~~♪~~♫~~\n没关系，没关系，女孩想找的一切都在镜子里，镜子映照着天上的月亮，月亮落入了镜中的涟漪。"
  },
  Stage_141789_Name = {
    Text = "镜子·之四"
  },
  Stage_141790_Desc = {
    Text = "♬~~♫~~♪~~♫~~♪~~♫~~\n有一只寻找同伴的孤号鸟，他的同伴失去了翅膀，他的同伴被拔光了羽毛。\n他试图实现实现不了的愿望，他的同伴连与他的回忆都忘掉。\n ♬~~♫~~♪~~♫~~♪~~♫~~\n没关系，没关系。他们还有甜美的、甜美的、共同的归宿。他们会进入安宁的、安宁的、永不被打扰的梦乡。"
  },
  Stage_141790_Name = {
    Text = "羽毛·之一"
  },
  Stage_142924_Desc = {
    Text = "模拟战斗"
  },
  Stage_142924_Name = {
    Text = "模拟战测试"
  },
  Stage_143314_Desc = {
    Text = "他在她身上犯了一个错误。\n他在他身上绝不会犯同样的错误。"
  },
  Stage_143314_Name = {Text = "她和他"},
  Stage_143315_Desc = {
    Text = "他在她身上犯了一个错误。\n他在他身上绝不会犯同样的错误。"
  },
  Stage_143315_Name = {Text = "她和他"},
  Stage_143876_Desc = {
    Text = "如何成为传奇调查员？首先，每一口深井都藏着许许多多的秘密。\n其次，闯进井底之前，记得散弹枪并不一定非得合法持有。"
  },
  Stage_143876_Name = {
    Text = "水井·之六"
  },
  Stage_143877_Desc = {
    Text = "人要上学，唤醒体也要上学。\n现在她是唤醒体了，她当然也要上学。\n请务必注意安全。"
  },
  Stage_143877_Name = {
