    Text = "把天花板涂成喜欢的颜色，把墙壁涂成喜欢的颜色。\n把冰箱装满喜欢的食物，养我们都喜欢的宠物。\n这是只属于你和我的家。"
  },
  Stage_143924_Name = {
    Text = "家·之五"
  },
