  },
  Stage_144353_Name = {
    Text = "临时文本"
  },
  Stage_145312_Desc = {
    Text = "欢迎！欢迎来到星天之鲸的斗兽场！欢迎来到这座杀戮的殿堂！\n将军，刺客，赏金猎人，角斗士……所有活着的传奇都在此相聚。\n厮杀，结盟，背叛，用尽你所有的手段吧，幸存者。\n规则只有一条： 只有最后站着的那个人，才能推开那扇门。"
  },
  Stage_145312_Name = {
    Text = "杀戮殿堂·之四"
  },
  Stage_145313_Desc = {
    Text = "荣誉、公正、尊严……这些都是弱者为自己编织的锁链。\n她只对更强的东西感兴趣。在这座血色的斗兽场里，值得她庄重以待的，或许尚有一个。"
  },
  Stage_145313_Name = {Text = "征伐"},
  Stage_145314_Desc = {
    Text = "取悦星天之鲸的方法非常简单：足够多的血，足够强大的力量，足够强烈的欲望……\n当你踏过千万人的尸骨，恭喜你，你获得了资格，来参与这场角逐。"
  },
  Stage_145314_Name = {
    Text = "觐献·之三"
  },
  Stage_145315_Desc = {
    Text = "欢迎！欢迎来到星天之鲸的斗兽场！欢迎来到这座杀戮的殿堂！\n将军，刺客，赏金猎人，角斗士……所有活着的传奇都在此相聚。\n厮杀，结盟，背叛，用尽你所有的手段吧，幸存者。\n规则只有一条： 只有最后站着的那个人，才能推开那扇门。"
  },
  Stage_145315_Name = {
    Text = "杀戮殿堂·之三"
  },
  Stage_145316_Desc = {
    Text = "取悦星天之鲸的方法非常简单：足够多的血，足够强大的力量，足够强烈的欲望……\n当你踏过千万人的尸骨，恭喜你，你获得了资格，来参与这场角逐。"
  },
  Stage_145316_Name = {
    Text = "觐献·之一"
  },
  Stage_145317_Desc = {
    Text = "在所有的危险里，猛兽是最温柔的一环。"
  },
  Stage_145317_Name = {
    Text = "困兽·之五"
  },
  Stage_145318_Desc = {
    Text = "终于，你得到了你想要的一切。力量，财富，荣耀，永不枯竭的权力。\n鲜血自王冠落下，染红你的双眼。痛快地欢笑吧，伟大的新王。在这权欲的鲜血里，等待你注定到来的腐烂。"
  },
  Stage_145318_Name = {
    Text = "权欲王冠·之一"
  },
  Stage_145319_Desc = {
    Text = "终于，你得到了你想要的一切。力量，财富，荣耀，永不枯竭的权力。\n鲜血自王冠落下，染红你的双眼。痛快地欢笑吧，伟大的新王。在这权欲的鲜血里，等待你注定到来的腐烂。"
