  },
  Stage_145322_Name = {
    Text = "权欲王冠·之五"
  },
  Stage_145323_Desc = {
    Text = "匐下你的身躯，低下你的头颅。\n那是蝼蚁面对神明时，唯一得体的姿势。"
  },
  Stage_145323_Name = {Text = "蝼蚁"},
  Stage_145324_Desc = {
    Text = "她的身后一无所有，她的前方永无尽头。她庆幸如此。"
  },
  Stage_145324_Name = {
    Text = "王冠之轻"
  },
  Stage_145325_Desc = {
    Text = "你站在镜子面前，看到你最深爱的那个人。父母，孩子，挚友，或是自己……\n爱，利维坦憎恶这个词。代行者的灵魂不容一丝累赘。\n举起刀，杀了它。 \n从此你将再无软肋。\n从此你将再无归途。"
  },
