  },
  Stage_145354_Name = {
    Text = "觐献·之六"
  },
  Stage_146229_Desc = {
    Text = "入席者已齐，沉睡的神明终于发出笑声。\n你们从来不是赴宴的宾客。"
  },
  Stage_146229_Name = {Text = "宴中人"},
  Stage_146230_Desc = {
    Text = "雪山只有一条规矩：无论你听见什么，不要回答。"
  },
  Stage_146230_Name = {
    Text = "不要回答"
  },
  Stage_146231_Desc = {
    Text = "七枚祭品，七座基座，一扇通往世界原点的门。\n愿望从来不是免费的馈赠。"
  },
  Stage_146231_Name = {
    Text = "无愿的尖峰"
  },
  Stage_146232_Desc = {
    Text = "飞鸟终于寻回另一只飞鸟。\n今日远行，不问归期。"
  },
  Stage_146232_Name = {
    Text = "飞鸟今日远行"
  },
  Stage_146233_Desc = {
    Text = "澄澈的湖面倒映星空，也倒映那些不愿被承认的渴望。\n谎言被投入火中，留下的未必就是真相。"
  },
  Stage_146233_Name = {
    Text = "未冻的月亮"
  },
  Stage_146234_Desc = {
    Text = "传说中，冥王叮嘱俄耳普斯，万勿回头，回头则永失爱妻。\n但他若忍心无视爱人的呼唤，又怎么会为了苦苦寻她，抱着琴渡过死河、穿越幽谷，走入黑暗的冥府？"
  },
  Stage_146234_Name = {Text = "逆向"},
  Stage_146235_Desc = {
    Text = "风雪封住了来路，也送来一位陌生的旅伴。\n黑暗深处窸窣作响，仿佛整座雪山正在窥视误入其中的人们。"
  },
  Stage_146235_Name = {
    Text = "第七名旅客"
  },
  Stage_146236_Desc = {
    Text = "随行者亦是先行者，她比你们更早抵达雪线之上。\n直面吧，从最开始，那就是无法逃离的存在。"
  },
  Stage_146236_Name = {Text = "先行者"},
  Stage_146237_Desc = {
    Text = "斗篷被风雪掀开，藏匿已久的秘密终于振翅。\n有些羽翼生来并非为了飞翔。"
  },
  Stage_146237_Name = {Text = "离巢日"},
  Stage_146238_Desc = {
    Text = "风雪封住了来路，也送来一位陌生的旅伴。\n黑暗深处窸窣作响，仿佛整座雪山正在窥视误入其中的人们。"
  },
  Stage_146238_Name = {
    Text = "第七名旅客"
  },
  Stage_146239_Desc = {
    Text = "人们清点食物、燃料、绳索与氧气，却没有人称量过藏在行囊里的愿望。"
  },
  Stage_146239_Name = {Text = "行囊"},
  Stage_146240_Desc = {
    Text = "火光照亮众人的面孔，也照亮他们各自怀藏的愿望。\n长夜未尽之时，就让我们再享一寝安歇。"
  },
  Stage_146240_Name = {
    Text = "围炉夜话"
  },
  Stage_146241_Desc = {
    Text = "不要温和地走入那个良夜。"
  },
  Stage_146241_Name = {Text = "良夜"},
  Stage_146242_Desc = {
    Text = "随行者亦是先行者，她比你们更早抵达雪线之上。\n直面吧，从最开始，那就是无法逃离的存在。"
  },
  Stage_146242_Name = {Text = "先行者"},
  Stage_146243_Desc = {
    Text = "真话不能剖开神明的腹腔。\n于是骗子与受骗者围坐在黑暗里，共同编织一个撕裂归途的谎言。"
  },
  Stage_146243_Name = {
    Text = "谎言同盟"
  },
  Stage_146244_Desc = {
    Text = "斗篷被风雪掀开，藏匿已久的秘密终于振翅。\n有些羽翼生来并非为了飞翔。"
  },
  Stage_146244_Name = {Text = "离巢日"},
  Stage_146245_Desc = {
    Text = "那是她再也无从寻觅的、本应是属于她的春天。"
  },
  Stage_146245_Name = {
    Text = "另一种春天"
  },
  Stage_146246_Desc = {
    Text = "真话不能剖开神明的腹腔。\n于是骗子与受骗者围坐在黑暗里，共同编织一个撕裂归途的谎言。"
  },
  Stage_146246_Name = {
    Text = "谎言同盟"
  },
  Stage_146247_Desc = {
    Text = "不要温和地走入那个良夜。"
  },
  Stage_146247_Name = {Text = "良夜"},
  Stage_146248_Desc = {
    Text = "入席者已齐，沉睡的神明终于发出笑声。\n你们从来不是赴宴的宾客。"
  },
  Stage_146248_Name = {Text = "宴中人"},
  Stage_146249_Desc = {
    Text = "七件宝物各归其位，七节命运也终于抵达同一个终点。"
  },
  Stage_146249_Name = {
    Text = "七节命运"
  },
  Stage_146250_Desc = {
    Text = "雪山只有一条规矩：无论你听见什么，不要回答。"
  },
  Stage_146250_Name = {
    Text = "不要回答"
  },
  Stage_146251_Desc = {
    Text = "离天空最远之地，却是近在脚下的诗与远方。\n渴望奇迹之人，是否也有余暇仰望天空？"
  },
  Stage_146251_Name = {Text = "雪域"},
  Stage_146253_Desc = {
    Text = "飞鸟终于寻回另一只飞鸟。\n今日远行，不问归期。"
  },
  Stage_146253_Name = {
    Text = "飞鸟今日远行"
  },
  Stage_146254_Desc = {
    Text = "七件宝物各归其位，七节命运也终于抵达同一个终点。"
  },
  Stage_146254_Name = {
    Text = "七节命运"
  },
  Stage_146255_Desc = {
    Text = "七枚祭品，七座基座，一扇通往世界原点的门。\n愿望从来不是免费的馈赠。"
  },
  Stage_146255_Name = {
    Text = "无愿的尖峰"
  },
  Stage_146355_Desc = {
    Text = "一场大梦终将消散。\n所有人曾向往的，所有人曾渴望的，所有人曾仰望的，所有人曾伫立的……\n在梦的尽头，都将散作万古的灰烬。"
  },
  Stage_146355_Name = {Text = "大梦"},
