  Stage_146928_Desc = {
    Text = "落难公主被骑士拯救，这是一个家喻户晓的传统故事。"
  },
  Stage_146928_Name = {Text = "公主"},
  Stage_146929_Desc = {
    Text = "巨龙苏醒，仇恨再度激起。野兽的气息从岩石中喷涌而出，战争的毒液熊熊燃烧，至今未熄。\n大地轰然雷鸣。"
  },
  Stage_146929_Name = {Text = "龙巢"},
  Stage_146930_Desc = {
    Text = "骑士走上了陌生的道路， 行过荒芜的原野与山丘，唯有影子相随。\n或许他早已死去，然而无人作证，便也忘记。\n世界是如此悄无声息。"
  },
  Stage_146930_Name = {Text = "墓冢"},
  Stage_146931_Desc = {
    Text = "四十昼夜的大雨降在地上，我们无法继续，我们仍将继续。"
  },
  Stage_146931_Name = {Text = "苹果岛"},
  Stage_146932_Desc = {
    Text = "巨龙苏醒，仇恨再度激起。野兽的气息从岩石中喷涌而出，战争的毒液熊熊燃烧，至今未熄。\n大地轰然雷鸣。"
  },
  Stage_146932_Name = {Text = "龙巢"},
  Stage_146933_Desc = {
    Text = "那是天堂花园的根与花，是世间一切愿望的冠冕，永不枯竭的丰足。\n饮下杯中酒吧，你会看见你最渴望的东西。"
  },
  Stage_146933_Name = {Text = "圣杯"},
  Stage_146934_Desc = {
    Text = "巨龙苏醒，仇恨再度激起。野兽的气息从岩石中喷涌而出，战争的毒液熊熊燃烧，至今未熄。\n大地轰然雷鸣。"
  },
  Stage_146934_Name = {Text = "龙巢"},
