  },
  Stage_148732_Name = {
    Text = "负誓·奥吉尔试玩关卡"
  },
  Stage_20089_Desc = {
    Text = "她履行了自己的诺言，你们终于可以一起回家了。"
  },
  Stage_20089_Name = {Text = "黄金头"},
  Stage_20090_Desc = {
    Text = "沙龙展是西岱最重要的艺术盛会。\n在这里，籍籍无名者渴望成功，功成名就者渴望永恒。"
  },
  Stage_20090_Name = {
    Text = "珊瑚女之死"
  },
  Stage_20091_Desc = {
    Text = "答案就在海水的中央。"
  },
  Stage_20091_Name = {
    Text = "在海中央"
  },
  Stage_20092_Desc = {
    Text = "恩斯特·克劳岱尔曾是贝桑松的领主。\n直到今天，这个家族依旧在当地富有名望。"
  },
  Stage_20092_Name = {
    Text = "见信如唔"
  },
  Stage_20426_Desc = {
    Text = "结局终究已经注定，无论你如何尝试，她如何挣扎，过去都无法改变。"
  },
  Stage_20426_Name = {
    Text = "绚烂的终局"
  },
  Stage_20427_Desc = {
    Text = "梦境不会永远美满，正如美妙的歌谣不会永远奏响。"
  },
  Stage_20427_Name = {
    Text = "曲终人散"
  },
  Stage_20428_Desc = {
    Text = "国王被禁锢在高高的王座里。\n世界在变，唯有他的悲伤始终如一。"
  },
  Stage_20428_Name = {Text = "她的国"},
  Stage_20429_Desc = {
    Text = "她漫无目的地行走在记忆的切片里。\n无所知，无所感，周而复始……"
  },
  Stage_20429_Name = {
    Text = "记忆屏障"
  },
  Stage_20430_Desc = {
    Text = "迷宫的尽头是什么？白昼、黑夜，还是无边无际的虚无？\n她需要自己找到答案。"
  },
  Stage_20430_Name = {
    Text = "迷宫的尽头"
  },
  Stage_20431_Desc = {
    Text = "子嗣，更多的子嗣，源源不断的子嗣……\n它们是她唯一的爱人。"
  },
  Stage_20431_Name = {
    Text = "意识集群"
  },
  Stage_20432_Desc = {
    Text = "永远不要打开不属于你的那扇门……"
  },
  Stage_20432_Name = {Text = "门"},
  Stage_20433_Desc = {
    Text = "梦境不会永远美满，正如美妙的歌谣不会永远奏响。"
  },
  Stage_20433_Name = {
    Text = "曲终人散"
  },
  Stage_20434_Desc = {
    Text = "恩斯特·克劳岱尔曾是贝桑松的领主。\n直到今天，这个家族依旧在当地富有名望。"
  },
  Stage_20434_Name = {
    Text = "见信如唔"
  },
  Stage_20435_Desc = {
    Text = "他已经做了所有能做的，接下来，就让时间去谱写新的歌谣。"
  },
  Stage_20435_Name = {
    Text = "新的歌谣"
  },
  Stage_20436_Desc = {
    Text = "一段令人怀念的记忆，还是一场无法遗忘的梦境？"
  },
  Stage_20436_Name = {
    Text = "过往的丝线"
  },
  Stage_20437_Desc = {
    Text = "子嗣，更多的子嗣，源源不断的子嗣……\n它们是她唯一的爱人。"
  },
  Stage_20437_Name = {
    Text = "意识集群"
  },
  Stage_20438_Desc = {
    Text = "梦境不会永远美满，正如美妙的歌谣不会永远奏响。"
  },
  Stage_20438_Name = {
    Text = "曲终人散"
  },
  Stage_20439_Desc = {
    Text = "这是你们之间的秘密，它将烙印在灵魂上，伴随永世。"
  },
  Stage_20439_Name = {
    Text = "梦，或理想"
  },
  Stage_20440_Desc = {
    Text = "爆炸后的世界一片黑暗，你在精神世界中徘徊，不知道等着你和艾瑞卡的究竟是什么。"
  },
  Stage_20440_Name = {
    Text = "声音如是说"
  },
  Stage_20441_Desc = {
    Text = "又一个梦境，又一段过去——这一次，你看到的是拥有血肉之躯的艾瑞卡。"
  },
  Stage_20441_Name = {
    Text = "启动测试"
  },
  Stage_20442_Desc = {
    Text = "爆炸后的世界一片黑暗，你在精神世界中徘徊，不知道等着你和艾瑞卡的究竟是什么。"
  },
  Stage_20442_Name = {
    Text = "声音如是说"
  },
  Stage_20443_Desc = {
    Text = "爆炸后的世界一片黑暗，你在精神世界中徘徊，不知道等着你和艾瑞卡的究竟是什么。"
  },
  Stage_20443_Name = {
    Text = "声音如是说"
  },
  Stage_20444_Desc = {
    Text = "恩斯特·克劳岱尔曾是贝桑松的领主。\n直到今天，这个家族依旧在当地富有名望。"
