  },
  Stage_20445_Desc = {
    Text = "子嗣，更多的子嗣，源源不断的子嗣……\n它们是她唯一的爱人。"
  },
  Stage_20445_Name = {
    Text = "意识集群"
  },
  Stage_20697_Desc = {
    Text = "每时每刻都有一个人死去，正如每时每刻都有一个人诞生。\n唯有影子是不同的。它被时间吞噬，被这片苦难的大地束缚。\n生生世世，不死，不生。"
  },
  Stage_20697_Name = {
    Text = "影子颂歌"
  },
  Stage_20698_Desc = {
    Text = "神说，他们生来便该历经苦难，流尽鲜血。\n就像太阳本该升起，雨水本该坠落。\n一切都是最好的安排。"
  },
  Stage_20698_Name = {Text = "苦雨地"},
  Stage_20699_Desc = {
    Text = "我们前进，是为了胜利的凯旋。\n我们活着，是为了完美的死去。"
  },
  Stage_20699_Name = {
    Text = "来自远方"
  },
  Stage_20700_Desc = {
    Text = "它是这里唯一的活物，它所见的一切由它统治。\n——它是至高无上的国王。"
  },
  Stage_20700_Name = {
    Text = "野兽王国"
  },
  Stage_20701_Desc = {
    Text = "他们跨越生死，隔着墓碑再度重逢。\n脸贴着脸，手握着手，呼吸间都是腐烂的味道。"
  },
  Stage_20701_Name = {
    Text = "孤独的重逢"
  },
  Stage_20702_Desc = {
    Text = "我们是虫豸、骨头与眼泪的集合。\n今夜我们在此相聚，只为一见那流淌着无数彩虹的河流。"
  },
  Stage_20702_Name = {
    Text = "猎颅集会"
  },
  Stage_20703_Desc = {
    Text = "当影子潜入黑夜，水滴汇入雨水。\n属于猎杀的时刻即将来临……"
  },
  Stage_20703_Name = {
    Text = "暴雨将至"
  },
  Stage_20704_Desc = {
    Text = "他们跨越生死，隔着墓碑再度重逢。\n脸贴着脸，手握着手，呼吸间都是腐烂的味道。"
