  Stage_22313_Desc = {
    Text = "潮水回流，记忆倒灌。\n满月升起前的一切，都睁开了眼。"
  },
  Stage_22313_Name = {Text = "睁开眼"},
  Stage_23624_Desc = {
    Text = "有些人生来便是冒险题材，有些人则把自己包装成了唯美的爱情。\n不过说到底，每个人都是自己的导演。"
  },
  Stage_23624_Name = {
    Text = "安迪·约翰逊之力"
  },
  Stage_23625_Desc = {
    Text = "每个人都藏着故事，但不是每个人都有讲述的欲望。"
  },
  Stage_23625_Name = {
    Text = "寻找故事"
  },
  Stage_23626_Desc = {
    Text = "以物易物，天经地义。"
  },
  Stage_23626_Name = {
    Text = "商人的慷慨"
  },
  Stage_23627_Desc = {
