    Text = "寻找故事"
  },
  Stage_23641_Desc = {
    Text = "最好的花，孕育出最美丽的诗。"
  },
  Stage_23641_Name = {
    Text = "最好的花"
  },
  Stage_23642_Desc = {
    Text = "最怀念的人，带来了最想说出口的愿望。"
  },
  Stage_23642_Name = {
    Text = "最怀念的人"
  },
  Stage_23643_Desc = {
    Text = "最盛大的幻景，承载最美好的愿望。"
  },
  Stage_23643_Name = {
    Text = "最盛大的幻景"
  },
  Stage_23644_Desc = {
    Text = "最圆满的结局…也许并不是那么圆满，但至少此刻，没有人不为结局欢笑。"
  },
  Stage_23644_Name = {
    Text = "最圆满的结局"
  },
  Stage_23647_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_23647_Name = {
    Text = "超维之旅·轮转间隙Ⅲ"
  },
  Stage_23648_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_23648_Name = {
    Text = "超维之旅·轮转间隙Ⅱ"
  },
