  },
  Stage_24183_Name = {
    Text = "红夫人试玩关卡"
  },
  Stage_24184_Name = {
    Text = "淤泥之花试玩关卡"
  },
  Stage_24423_Desc = {
    Text = "每个伦蒂尼恩人都不会拒绝一杯新鲜沏好的热茶。\n哪怕那是一杯七鳃鳗乌龙茶。"
  },
  Stage_24423_Name = {
    Text = "七鳃鳗特调"
  },
  Stage_24424_Desc = {
    Text = "每个被命运选中的人都认为自己是那个例外。\n命运嘲笑概率。"
  },
  Stage_24424_Name = {
    Text = "命运的囚者"
  },
  Stage_24425_Desc = {
    Text = "咔嚓。\n她发誓与过去的生活一刀两断。\n就像用剪子把一根饰带一刀剪成两截。"
  },
  Stage_24425_Name = {
    Text = "献给索蕾尔"
  },
  Stage_24426_Desc = {
    Text = "又一次，你成为同情的俘虏，狠狠堕入她的灵魂。"
  },
  Stage_24426_Name = {
    Text = "坠落的审判"
  },
  Stage_24427_Desc = {
    Text = "故事之初，你将见证一场华丽的死亡。\n它虽是开端，却远非结束。"
  },
  Stage_24427_Name = {Text = "饮酒歌"},
  Stage_24428_Desc = {
    Text = "女孩名为索蕾尔，是全村的骄傲。\n她很听话、爱干净，一身雪白色，迈着小步，活像那些真正的淑女。\n女孩和那些淑女不同——她从不做梦。"
  },
  Stage_24428_Name = {Text = "N"},
  Stage_24429_Desc = {
    Text = "逻辑就像威士忌，摄入太多就失去它的益处了。"
  },
  Stage_24429_Name = {
    Text = "假面和声"
  },
  Stage_24430_Desc = {
    Text = "在祂的悉心养护下，名为权欲的癌细胞终于像蔷薇开放一样扩散开来。"
  },
  Stage_24430_Name = {
    Text = "红色庆典"
  },
  Stage_24431_Desc = {
    Text = "吸溜。吸溜。\n我们阴暗蠕动，我们窃窃私语。\n肥胖的身躯在月光下拖出弯弯的泪痕——咸咸的哦。"
  },
  Stage_24431_Name = {Text = "卵"},
  Stage_24432_Desc = {
    Text = "司康饼、马卡龙，还有冒着热气的可可……\n侍女的心愿很简单：吃得好一点，再好一点。"
  },
  Stage_24432_Name = {
    Text = "侍女的心愿"
  },
  Stage_24433_Desc = {
    Text = "当心，当心。\n你们为之倾倒的那位夫人，可不是什么真正的淑女。\n不过，谁在乎呢？"
  },
  Stage_24433_Name = {
    Text = "淑女指南"
  },
  Stage_24434_Desc = {
    Text = "蔷薇在钟声里垂下纤瘦的头颅，秃鹫迷失在腥臭的花丛中。\n无人歌唱，无人诉说。世界因她的死而褪色。"
  },
  Stage_24434_Name = {
    Text = "蔷薇的葬礼"
  },
  Stage_24435_Desc = {
    Text = "她汲干泉水，扼杀纯真的鸟儿。\n她带来金色的风，它们像流星掠过原野。\n她将整个世界置于欲望的火焰上，又将它化为灰烬。"
  },
  Stage_24435_Name = {Text = "茶花女"},
  Stage_24439_Desc = {
    Text = "当心，当心。\n你们为之倾倒的那位夫人，可不是什么真正的淑女。\n不过，谁在乎呢？"
  },
  Stage_24439_Name = {
    Text = "淑女指南"
  },
