  },
  Stage_24456_Name = {
    Text = "假面和声"
  },
  Stage_24528_Desc = {
    Text = "不论发生什么，不论经过多少改变，你的呼唤总会被听见。"
  },
  Stage_24528_Name = {
    Text = "这不是永别"
  },
  Stage_24529_Desc = {
    Text = "一次，两次，三次……西西弗斯推着巨石，徒劳地攀登着不可能越过的高山。"
  },
  Stage_24529_Name = {
    Text = "西西弗斯"
  },
  Stage_24530_Desc = {
    Text = "熟悉的少女变得如此陌生，这个冷漠的人……真的是你认识的拉蒙娜吗？"
  },
  Stage_24530_Name = {
    Text = "孤注一掷"
  },
  Stage_24531_Desc = {
    Text = "寻常的一天，从不同寻常的梦境开始。"
  },
  Stage_24531_Name = {
    Text = "似雨之泪"
  },
  Stage_24532_Desc = {
    Text = "熟悉的少女变得如此陌生，这个冷漠的人……真的是你认识的拉蒙娜吗？"
  },
  Stage_24532_Name = {
    Text = "孤注一掷"
  },
  Stage_24533_Desc = {
    Text = "熟悉的少女变得如此陌生，这个冷漠的人……真的是你认识的拉蒙娜吗？"
  },
  Stage_24533_Name = {
    Text = "孤注一掷"
  },
  Stage_34716_Desc = {
    Text = "急转直下，突发情节，故事突变——守密人感觉，这似乎在描述有时的自己。"
  },
  Stage_34716_Name = {
    Text = "Ⅲ·情节轮转"
  },
  Stage_34717_Desc = {
    Text = "这是一个连拉蒙娜都没有听过的词，在某些年迈唤醒体的帮助下，大家才终于明白：有时候，大哭一场才是处理坏情绪的唯一方法。"
  },
  Stage_34717_Name = {
    Text = "Ⅱ·卡塔西斯"
  },
  Stage_34718_Desc = {
    Text = "卡茜亚找到的理论书中如此写道：故事发生的时间不能超过一天，舞台也不能超过一处……\n守密人听到这里时，就放弃了继续读下去。毕竟，一天的时间，有时还不够守密人完成一次「融蚀与灾厄处理」的课后作业论文。"
  },
  Stage_34718_Name = {
    Text = "Ⅰ·三一律"
  },
  Stage_34719_Desc = {
    Text = "在卡茜亚找到的理论书中写道：金字塔模型往往着眼于一场危机的解决。\n但是很可惜，不是每场危机都能在现实中得到解决。它们被和平假象所隐瞒、掩盖，在暗中滋生，最后爆发为新的「金字塔」。"
  },
  Stage_34719_Name = {
    Text = "Ⅶ·剧作金字塔"
  },
  Stage_34720_Desc = {
    Text = "在故事的结尾，需要体现角色的发展或者变化。可是在生活中，弧光往往会连成一个圆。"
  },
  Stage_34720_Name = {
    Text = "Ⅵ·弧光理论"
  },
  Stage_34721_Desc = {
    Text = "一个提前设定好的场景，几个互相熟识的演员。剩下的，就交给灵感与碰撞。"
  },
  Stage_34721_Name = {
    Text = "Ⅴ·假面喜剧"
  },
  Stage_34722_Desc = {
    Text = "不要每时每刻都用内容轰炸观众的脑子，要给他们留下思考空间，最好是完全静止的——真希望朵尔在上课时能熟练运用这种技巧，守密人这么呢喃着，得到了所有人的认同。"
  },
  Stage_34722_Name = {
    Text = "Ⅳ·静场时刻"
  },
  Stage_34912_Desc = {
    Text = "旧日灾厄于此刻苏生，跨越现世的界碑，引燃堕落的汪洋。"
  },
  Stage_34912_Name = {
    Text = "融灾禁区·第1波·Ⅲ级警报"
  },
  Stage_34913_Desc = {
    Text = "旧日灾厄于此刻苏生，跨越现世的界碑，引燃堕落的汪洋。"
  },
