  },
  Stage_35099_Desc = {
    Text = "「嘘……你猜，我透过你的眼睛看见了什么？」\n在奥瑞塔被守密人吓哭以后，守密人房间的第四面墙差点被萝坦推倒，因为奥瑞塔哭得实在是太让人心慌了。"
  },
  Stage_35099_Name = {
    Text = "Ⅸ·戏剧的第四壁"
  },
  Stage_35100_Desc = {
    Text = "「不要让观众全身心沉浸在剧情中，要让他们分析、批判舞台上正在发生的事情。」\n对这条理论，奥瑞塔如此评价：奥瑞塔不想要被任何人骂！奥瑞塔只想和大家成为好朋友！"
  },
  Stage_35100_Name = {
    Text = "Ⅷ·陌生化效果"
  },
  Stage_35129_Desc = {
    Text = "她是梦境与现实交错的界限，是每个仰望夜空的灵魂内心深处的反射。"
  },
  Stage_35129_Name = {
    Text = "倒错的群星"
  },
  Stage_35129_StageInitStateText = {Text = "海魇"},
  Stage_35130_Desc = {
    Text = "她准备好了。"
  },
  Stage_35130_Name = {
    Text = "内化的火苗"
  },
  Stage_35571_Desc = {
    Text = "因为你是奥瑞塔的朋友，所以她要带你认识她所有的朋友。"
  },
  Stage_35571_Name = {
    Text = "朋友大收集"
  },
  Stage_35572_Desc = {
    Text = "因为你是奥瑞塔的朋友，所以她要带你认识她所有的朋友。"
  },
  Stage_35572_Name = {
    Text = "朋友大收集"
  },
  Stage_35573_Desc = {
    Text = "因为你是奥瑞塔的朋友，所以她要带你认识她所有的朋友。"
  },
  Stage_35573_Name = {
    Text = "朋友大收集"
  },
  Stage_35574_Desc = {
    Text = "奥瑞塔喜欢你，所以要你成为能够加入她平凡一天的朋友。"
  },
  Stage_35574_Name = {
    Text = "寂静的白日"
  },
  Stage_35575_Desc = {
    Text = "因为大家都陪在奥瑞塔身边，所以奥瑞塔一点都不害怕睡着。"
  },
  Stage_35575_Name = {
    Text = "水里的宫殿"
  },
  Stage_35843_Name = {
    Text = "深海淑女试玩关卡"
  },
  Stage_35857_Desc = {
    Text = "群星去向了它们应去之处，相互间以一种超脱于人类理解的方式交流，编织出一张看不见的网，捕捉着流动的时间和逝去的光年。"
  },
  Stage_35857_Name = {
    Text = "未知的星轨"
  },
  Stage_36125_Desc = {
    Text = "不被祝福的孩子在海中吟咏圣歌。\n嘘……请保持安静，切勿惊扰祂的长眠。"
  },
  Stage_36125_Name = {
    Text = "圣胎之咏Ⅲ"
