  Stage_36614_Desc = {
    Text = "一味行淫，随情纵欲……\n——然后呢？\n当受永火刑罚，作为鉴戒。\n——哦。"
  },
  Stage_36614_Name = {
    Text = "死亡、蜜酒与歌之夜"
