  Stage_36619_Name = {
    Text = "死亡、蜜酒与歌之夜"
  },
  Stage_36620_Desc = {
    Text = "女王坐在高高的王座里。\n陪伴她的有无尽的珍宝、财富，以及一点点沉没的宇宙废墟。"
  },
  Stage_36620_Name = {
    Text = "离群的女王"
  },
  Stage_36621_Desc = {
    Text = "灾厄前，都城是她野心与欲望的延伸。\n灾厄后，都城是黑夜与孤独的囚笼。"
  },
  Stage_36621_Name = {Text = "吹笛人"},
  Stage_36887_Name = {
    Text = "荆棘女王试玩关卡"
  },
  Stage_38756_Desc = {
    Text = "她闭上双眼，漫无目的地漂浮在宇宙的虚空里。\n一年，一百年……终于有一天，她告诉自己：「没关系。就由我来定义真假。」\n女王和她不朽的城池——伊萨拉乌，就这样停留在宇宙的茫茫星河中。\n她将伊萨拉乌的故事告诉我，以便它被永远铭记。"
  },
  Stage_38756_Name = {
    Text = "一段记忆·追忆之六"
  },
