  Stage_38762_Name = {
    Text = "一段记忆·追忆之一"
  },
  Stage_38763_Desc = {
    Text = "伊萨拉乌就这样消失了，仿佛它从未诞生。\n所有的街道、子民都是虚幻。它们从她的梦中诞生，在日复一日的勾勒中不断具象，然后：\n「砰——」\n梦醒了。她从未睁眼看过伊萨拉乌，正如她从未睁眼看过自己。"
  },
