  },
  Stage_38769_Name = {
    Text = "海市蜃楼·追忆之四"
  },
  Stage_38770_Desc = {
    Text = "夜晚，女王站在宫殿露台上，凝望着数千英尺下的城池。\n日复一日，每当她想跨出宫殿一步，便会引来眩晕、眼泪、以及大片的记忆空白。\n「准备好了吗？迎接这个世界的真实。」\n她深吸一口气，从露台上跳了下去。"
  },
  Stage_38770_Name = {
    Text = "真实·追忆之一"
  },
  Stage_38771_Desc = {
    Text = "夜晚，女王站在宫殿露台上，凝望着数千英尺下的城池。\n日复一日，每当她想跨出宫殿一步，便会引来眩晕、眼泪、以及大片的记忆空白。\n「准备好了吗？迎接这个世界的真实。」\n她深吸一口气，从露台上跳了下去。"
  },
  Stage_38771_Name = {
    Text = "真实·追忆之三"
  },
  Stage_38772_Desc = {
    Text = "当她睁开双眼的时候，世界正在因此而毁灭。\n所有的建筑都坍塌了，黑色的粘液舔舐天空，白色的小苍兰消散在永恒的虚空里。\n一切都很安静。一切都像睡着了。\n只有眼泪是冰凉的，冷冷地贴在她的脸上，浸湿了她的发梢。"
  },
  Stage_38772_Name = {
    Text = "井·追忆之四"
  },
