    Text = "「我什么都没有了。」瞎了一只眼的流浪儿说，「只有这支花能献给您，伟大的女王。」\n她接过白色的小苍兰，却感到困惑。似乎这一幕曾无数次在她的记忆深处轮回。\n循环往复，就像困住米洛陶洛斯的迷宫。"
  },
  Stage_38784_Name = {
    Text = "小苍兰·追忆之五"
  },
  Stage_38785_Desc = {
    Text = "黄金之城——伊萨拉乌。\n它的财富取之不竭，它的欲望无边无界。\n它就像一块海绵，吸汲着不断涌流的黄金潮水，并随之膨胀。\n这是我的都城，女王说。她为此而自豪。"
  },
