  },
  Stage_38791_Name = {
    Text = "黄金之城·追忆之一"
  },
  Stage_38792_Desc = {
    Text = "当她睁开双眼的时候，世界正在因此而毁灭。\n所有的建筑都坍塌了，黑色的粘液舔舐天空，白色的小苍兰消散在永恒的虚空里。\n一切都很安静。一切都像睡着了。\n只有眼泪是冰凉的，冷冷地贴在她的脸上，浸湿了她的发梢。"
  },
  Stage_38792_Name = {
    Text = "井·追忆之五"
  },
  Stage_38793_Desc = {
    Text = "女王和她不朽的城池——伊萨拉乌。\n宇宙眷顾的双生子啊，你们被命运的脐带轻轻缠绕。\n有人说，智慧的女王率领民众来到伊萨拉乌，就像《启示录》里所描绘的。\n也有人说，伊萨拉乌的河床终年涌动，直到将女王孕育而出。"
  },
  Stage_38793_Name = {
    Text = "启示录·追忆之一"
