  Stage_43506_Desc = {
    Text = "永别了。巨人说。\n我要回到历史里，在那里我战无不胜、无坚不摧。\n我是不朽。"
  },
  Stage_43506_Name = {
    Text = "沉没号角"
  },
  Stage_43508_Desc = {
    Text = "被时间遗忘的人啊，你要驶向何方？\n——去到那遥远的无依之地。那里星月静寂，海洋无声。\n世界只剩你和我。"
  },
  Stage_43508_Name = {
    Text = "无依之海"
  },
  Stage_43509_Desc = {
    Text = "永别了。巨人说。\n我要回到历史里，在那里我战无不胜、无坚不摧。\n我是不朽。"
  },
  Stage_43509_Name = {
    Text = "沉没号角"
  },
  Stage_43510_Desc = {
    Text = "英雄和他的随从航行在金色的海洋中。\n他们带着同样的伤疤，唱着同一段旋律，一起迎接死亡与新生。"
  },
  Stage_43510_Name = {
    Text = "金色的旋律"
  },
  Stage_43512_Desc = {
    Text = "永别了。巨人说。\n我要回到历史里，在那里我战无不胜、无坚不摧。\n我是不朽。"
  },
  Stage_43512_Name = {
    Text = "沉没号角"
  },
  Stage_44196_Desc = {
    Text = "愚昧的人啊，你们点燃了火焰，将希望与救赎付之一炬。\n当你们在漆黑的死亡中挣扎时，这自诩的正义滋味又如何？"
  },
  Stage_44196_Name = {
