  },
  Stage_44201_Desc = {
    Text = "愚昧的人啊，你们点燃了火焰，将希望与救赎付之一炬。\n当你们在漆黑的死亡中挣扎时，这自诩的正义滋味又如何？"
  },
  Stage_44201_Name = {
    Text = "忏悔·滋长之三"
  },
  Stage_44202_Desc = {
    Text = "对病痛的恐慌让他们心有不甘。\n「凭什么只给他赐福？我也生病了！」\n「我才是最严重的，我才应该第一个受祝！」"
  },
  Stage_44202_Name = {
    Text = "争夺·滋长之四"
  },
  Stage_44203_Desc = {
    Text = "那些让他们受益的才是好的，所有未能落在他们身上的祝福都是诅咒。\n「什么赐福，分明是邪恶的血魔法！」\n「这一定是巫术，他是恶魔！」"
  },
  Stage_44203_Name = {
    Text = "指责·滋长之二"
  },
  Stage_44204_Desc = {
    Text = "他们拒绝理解，拒绝包容。\n他们的世界只有黑与白，尽管他们自己都无法掌控其定义。\n「烧死他，烧死他！」\n「烧死这个异端主教！让邪恶死亡！」"
  },
