  Stage_44495_Desc = {
    Text = "漆黑的潮水漫过警戒界限，轻微的波动亦昭示着足以吞噬掉以轻心者的险恶。"
  },
  Stage_44495_Name = {
    Text = "融灾禁区·第3波·Ⅰ级警报"
  },
  Stage_44496_Desc = {
    Text = "旧日灾厄于此刻苏生，跨越现世的界碑，引燃堕落的汪洋。"
