  Stage_44509_Desc = {
    Text = "漆黑的潮水漫过警戒界限，轻微的波动亦昭示着足以吞噬掉以轻心者的险恶。"
  },
  Stage_44509_Name = {
    Text = "融灾禁区·第4波·Ⅰ级警报"
  },
  Stage_44551_Desc = {
    Text = "仁慈的父神，请宽恕我，让我得以改过，让我得以弥补我的过错。"
  },
  Stage_44551_Name = {
    Text = "我们的过错"
  },
  Stage_44552_Desc = {
    Text = "尘埃落定，那些有罪的将得到判决，那些前行的将继续向前。\n明天又是新的一天。"
  },
  Stage_44552_Name = {
    Text = "燃起白色的希望"
  },
  Stage_44553_Desc = {
    Text = "这本该是个寻常的下午，但对弥萨格的守密人来说，普通的日常显然是个奢望。"
  },
  Stage_44553_Name = {Text = "悔过"},
  Stage_44554_Desc = {
    Text = "净化、净化……这究竟是一个疯人的呓语，还是某种错乱的信仰？"
  },
  Stage_44554_Name = {
    Text = "血腥的符号"
  },
  Stage_44555_Desc = {
    Text = "他们已经被火焰吞没，失去理智。"
  },
  Stage_44555_Name = {
    Text = "因暴怒疯狂"
  },
  Stage_44556_Desc = {
    Text = "旁人有的他们也要有，旁人没有的他们更要有——不管多么无谓，不管多么荒唐。"
  },
  Stage_44556_Name = {
    Text = "为嫉妒杀戮"
  },
  Stage_44557_Desc = {
    Text = "停下吧，放松吧，你已经足够操劳；躺下吧，安睡吧，没有人忍心责怪。"
  },
  Stage_44557_Name = {
    Text = "向倦怠妥协"
  },
  Stage_44558_Desc = {
    Text = "你架着疲惫踏上来时的路，却撞上饥饿的獠牙。"
  },
  Stage_44558_Name = {
    Text = "把饥肠填满"
  },
  Stage_44559_Desc = {
    Text = "从镜子里看向你的，究竟是一个虚幻的影子，还是真实的欲望？"
  },
  Stage_44559_Name = {
    Text = "将罪恶净化"
  },
  Stage_44560_Desc = {
    Text = "仁慈的父神，请宽恕我，让我得以改过，让我得以弥补我的过错。"
  },
  Stage_44560_Name = {
    Text = "我们的过错"
  },
  Stage_44561_Desc = {
    Text = "仁慈的父神，请宽恕我，让我得以改过，让我得以弥补我的过错。"
  },
  Stage_44561_Name = {
    Text = "我们的过错"
  },
  Stage_44715_Name = {
    Text = "仁爱主祭试玩关卡"
  },
  Stage_45411_Desc = {
    Text = "Kiss me good-bye."
  },
  Stage_45411_Name = {Text = "吻别"},
  Stage_46169_Desc = {
    Text = "她将所有概率铭记于心，却和经院的神学生一样困惑。\n因为疯狂无法预测，并且很不幸，它才是世界的常态。"
  },
  Stage_46169_Name = {
    Text = "满贯定约"
  },
  Stage_46170_Desc = {
    Text = "她将所有概率铭记于心，却和经院的神学生一样困惑。\n因为疯狂无法预测，并且很不幸，它才是世界的常态。"
  },
  Stage_46170_Name = {
    Text = "满贯定约"
  },
  Stage_46171_Desc = {
    Text = "咒缚将你变成陷入永久冬眠的蛇类。\n它和你的脐带一样古老。"
  },
  Stage_46171_Name = {Text = "苦咒缚"},
  Stage_46172_Desc = {
    Text = "女孩曾是梅森。\n不久之后，她将像尤利西斯一样，谁都不是。\n不久之后，她将是众生。"
  },
  Stage_46172_Name = {Text = "「源」"},
  Stage_46173_Desc = {
    Text = "咒缚将你变成陷入永久冬眠的蛇类。\n它和你的脐带一样古老。"
  },
  Stage_46173_Name = {Text = "苦咒缚"},
  Stage_46174_Desc = {
    Text = "止于此，止于我。\n不可试探你的主。"
  },
  Stage_46174_Name = {Text = "止于此"},
  Stage_46175_Desc = {
    Text = "多年来，朝圣者们在雪山里刻凿出一条道路，拖拽住现实。\n他们静止不动，张大着嘴，仿佛发出连绵的吼声——"
  },
  Stage_46175_Name = {
    Text = "朝圣者之歌"
  },
  Stage_46176_Desc = {
    Text = "咒缚将你变成陷入永久冬眠的蛇类。\n它和你的脐带一样古老。"
  },
  Stage_46176_Name = {Text = "苦咒缚"},
  Stage_46177_Desc = {
    Text = "她将所有概率铭记于心，却和经院的神学生一样困惑。\n因为疯狂无法预测。很不幸，它才是世界的常态。"
  },
  Stage_46177_Name = {
    Text = "满贯定约"
  },
  Stage_46178_Desc = {
    Text = "她目睹着自己即将占领世界。\n她注视着那道狭长的阴影，不发一言。"
  },
  Stage_46178_Name = {
    Text = "影子童话"
  },
  Stage_46179_Desc = {
    Text = "她的喜剧独一无二。它们由无边寂寥的黑夜、月亮和眼泪组成。"
  },
  Stage_46179_Name = {
    Text = "等待喜剧"
  },
  Stage_46180_Desc = {
    Text = "当万物沉睡时，蛇会醒来。\n当一切都倒塌时，蛇将恢复原状。"
  },
  Stage_46180_Name = {Text = "失眠蛇"},
  Stage_46181_Desc = {
    Text = "猫咪将自己的情绪切割成一十八块，并为它们发明了音调不同的「喵呜」声。\n这样，它就能说「我饿了」「快陪我玩」「别打扰我」。\n也能说「我想你了」。"
  },
  Stage_46181_Name = {
    Text = "猫知晓一切"
  },
  Stage_46182_Desc = {
    Text = "伴随老旧钟声响起的，是气息微弱、不断消弭的祝福。\n节日快乐。节日快乐。节日快乐。"
  },
  Stage_46182_Name = {
    Text = "金色赋格"
  },
  Stage_46259_Name = {
    Text = "渴血患者试玩关卡"
  },
  Stage_46260_Name = {
    Text = "沉渊者试玩关卡"
  },
  Stage_46261_Name = {
    Text = "迷宫蛛试玩关卡"
  },
