  },
  Stage_46271_Name = {
    Text = "雕砌者试玩关卡"
  },
  Stage_46272_Name = {
    Text = "睡莲试玩关卡"
  },
  Stage_46273_Name = {
    Text = "奇术师试玩关卡"
  },
  Stage_46274_Name = {
    Text = "窜行者试玩关卡"
  },
  Stage_46275_Name = {
    Text = "原初信徒试玩关卡"
  },
  Stage_46276_Name = {
    Text = "青炎舞者试玩关卡"
  },
  Stage_46277_Name = {
    Text = "空想利刃试玩关卡"
  },
  Stage_46278_Name = {
    Text = "凸月侍女试玩关卡"
  },
  Stage_46540_Desc = {
    Text = "她觉得有无数条蛇像网一样缠住了自己。\n醒来后，一个影子站在她的床前。它说：\n「无论你到什么地方，我都要抹掉你，正如你现在抹掉我的脸一样。」"
  },
  Stage_46540_Name = {
    Text = "无意识记·涌现之五"
  },
  Stage_46541_Desc = {
    Text = "她觉得有无数条蛇像网一样缠住了自己。\n醒来后，一个影子站在她的床前。它说：\n「无论你到什么地方，我都要抹掉你，正如你现在抹掉我的脸一样。」"
