  },
  Stage_46545_Name = {
    Text = "无意识记·涌现之三"
  },
  Stage_46546_Desc = {
    Text = "她觉得有无数条蛇像网一样缠住了自己。\n醒来后，一个影子站在她的床前。它说：\n「无论你到什么地方，我都要抹掉你，正如你现在抹掉我的脸一样。」"
  },
  Stage_46546_Name = {
    Text = "无意识记·涌现之二"
  },
  Stage_46547_Desc = {
    Text = "不知从何时起，她成为了这里的法官。\n她审理一个隐掉名字的人，判了那人死刑。\n然后她才听到揭示：「你就是那个人。」\n是的，这里所有的犯人、法官和祭司都长着同一张脸。"
  },
  Stage_46547_Name = {
    Text = "杏仁体·涌现之四"
  },
  Stage_46548_Desc = {
    Text = "地狱是一个空房间，里面摆放着无数镜子。\n她不敢睁开双眼，因为俯仰皆是她那张苍白惊惧的脸。\n冥冥中，有个声音在说：\n这是报应。你生前只有一具皮囊；死后遭报应时有无数具。"
  },
  Stage_46548_Name = {
    Text = "镜子·涌现之六"
  },
  Stage_46549_Desc = {
    Text = "不知从何时起，她成为了这里的法官。\n她审理一个隐掉名字的人，判了那人死刑。\n然后她才听到揭示：「你就是那个人。」\n是的，这里所有的犯人、法官和祭司都长着同一张脸。"
  },
  Stage_46549_Name = {
    Text = "杏仁体·涌现之二"
  },
  Stage_46550_Desc = {
    Text = "不知从何时起，她成为了这里的法官。\n她审理一个隐掉名字的人，判了那人死刑。\n然后她才听到揭示：「你就是那个人。」\n是的，这里所有的犯人、法官和祭司都长着同一张脸。"
  },
  Stage_46550_Name = {
    Text = "杏仁体·涌现之三"
  },
  Stage_46551_Desc = {
    Text = "洪积315年12月@2日，她被宣布为无形。\n她大声呼喊，却无人理睬；她偷面包，却不被抓住监禁。\n名为忘却的疾病感染了所有人，唯独将她遗漏。"
  },
  Stage_46551_Name = {
    Text = "遗忘曲线·涌现之七"
  },
  Stage_46552_Desc = {
    Text = "地狱是一个空房间，里面摆放着无数镜子。\n她不敢睁开双眼，因为俯仰皆是她那张苍白惊惧的脸。\n冥冥中，有个声音在说：\n这是报应。你生前只有一具皮囊；死后遭报应时有无数具。"
  },
  Stage_46552_Name = {
