  Stage_48034_Desc = {
    Text = "水源是沙漠的血脉，绿洲是心脏泵出的河床。"
  },
  Stage_48034_Name = {Text = "绿洲"},
  Stage_48035_Desc = {
    Text = "母树赐予亚兰人生命，却又吞噬亚兰人的灵魂。"
  },
  Stage_48035_Name = {Text = "繁衍"},
  Stage_48036_Desc = {
    Text = "黄沙隔绝了外界讯息的传播，古老的文明得以在此流传。\n亚兰人世代生于此。"
  },
  Stage_48036_Name = {Text = "聚落"},
  Stage_48037_Desc = {
    Text = "亚兰文明中，项链是恋人间定情的重要信物。"
  },
  Stage_48037_Name = {Text = "项链"},
  Stage_48038_Desc = {
    Text = "自树而来，自源头而来。"
  },
  Stage_48038_Name = {Text = "源流"},
  Stage_48039_Desc = {
    Text = "注意留心棋盘对面的阴影。\n真正的对手，向来不在棋局之内。"
  },
  Stage_48039_Name = {Text = "对手"},
  Stage_48040_Desc = {
    Text = "旷古的遗骸，藏匿于文明的废墟。"
  },
  Stage_48040_Name = {Text = "遗骸"},
  Stage_48041_Desc = {
    Text = "风暴如千古的野兽咆哮。"
  },
  Stage_48041_Name = {
    Text = "风暴之壁"
  },
  Stage_48042_Desc = {
