    Text = "蜜腺是甜美的诱惑。\n它分泌蜜汁，散发甘香，引诱彩蝶与蜂群，将沉醉的迷失者转化为繁衍的工具。"
  },
  Stage_49360_Name = {
    Text = "蜜腺·呓语之五"
  },
  Stage_49361_Desc = {
