  Stage_49361_Name = {
    Text = "蜜腺·呓语之四"
  },
  Stage_49362_Desc = {
    Text = "落果是残酷的预兆。\n越极端恶劣的环境，生存竞争到来得越早。在新的幼苗触达大地之前，死亡已经如影随形。"
  },
  Stage_49362_Name = {
    Text = "落果·呓语之三"
  },
  Stage_49363_Desc = {
    Text = "授粉是遥远的邂逅。\n花枝摇曳邀约共舞的使者，邀约它撷取花粉，流连花丛，在自然的律动中将新生命的源泉送入另一个等待的怀抱。"
  },
