  Stage_49368_Name = {
    Text = "授粉·呓语之三"
  },
  Stage_49369_Desc = {
    Text = "幼根是莽撞的冒险。\n种子不知晓下一寸天地是丰沃的黑土，还是冰冷的荒沙，种子只是无垠无畏地伸出迈向大地的根梢。"
  },
  Stage_49369_Name = {
    Text = "幼根·呓语之一"
  },
  Stage_50345_Desc = {
    Text = "泰旖丝。\n如蛇般幽魅，如树般古老，如沙般苍茫。"
  },
  Stage_50345_Name = {Text = "泰旖丝"},
