  Stage_51057_Desc = {
    Text = "在卡茜亚找到的理论书中写道：金字塔模型往往着眼于一场危机的解决。\n但是很可惜，不是每场危机都能在现实中得到解决。它们被和平假象所隐瞒、掩盖，在暗中滋生，最后爆发为新的「金字塔」。"
