  Stage_51646_Name = {
    Text = "融灾禁区·第1波·Ⅳ级警报"
  },
  Stage_51761_Desc = {
    Text = "最后一次，她凝视王的雕像曾经矗立的地方。\n那里没有雕像，也没有王。"
  },
  Stage_51761_Name = {
    Text = "梦归利莫里亚"
  },
  Stage_51762_Desc = {
    Text = "雕像与她遥遥相望。他们之间隔着的，是漫长的时光，和未曾醒来的梦。"
  },
  Stage_51762_Name = {
    Text = "暗色雕像"
  },
  Stage_51763_Desc = {
    Text = "希望，是利莫里亚最为珍贵的毒药。\n他们狂歌痛饮，他们甘之如饴。"
  },
  Stage_51763_Name = {
    Text = "祭司之仪"
  },
  Stage_51764_Desc = {
    Text = "群星、命运、神明……在祂们面前，公平二字，不值一提。"
  },
  Stage_51764_Name = {
    Text = "谎言的美德"
  },
  Stage_51765_Desc = {
    Text = "在雨中挣扎。在雨中告别。"
  },
  Stage_51765_Name = {Text = "在雨中"},
  Stage_51766_Desc = {
    Text = "回应我吧，吾主。我将为您，奉上最珍贵的献礼。"
  },
  Stage_51766_Name = {
    Text = "王的献礼"
  },
  Stage_51767_Desc = {
    Text = "享用吧，祂说。享用那些低贱的温情，享用那被烹制好的命运。"
  },
  Stage_51767_Name = {Text = "鱼肉"},
  Stage_51768_Desc = {
    Text = "祂的意志如星辰之网交织，祂在永恒的虚无中候汝入梦。"
  },
  Stage_51768_Name = {
    Text = "于深海祷告"
  },
  Stage_51769_Desc = {
    Text = "祈祷，是利莫里亚人学会的第一件事。"
  },
  Stage_51769_Name = {Text = "预言"},
  Stage_51770_Desc = {
    Text = "在那安宁极乐之地，昔日的挚友们互相凝望。\n他们将携起对方的手，一同踏上通往神国的阶梯。"
  },
  Stage_51770_Name = {Text = "挚友"},
  Stage_51771_Desc = {
    Text = "鲜血。眼泪。祭祀。狂欢。杀戮。\n又一段关于群星的故事开始了，而群星并不关心。\n它们闪耀着，亘古至今。"
  },
  Stage_51771_Name = {
    Text = "聆听吧，群星"
  },
  Stage_51772_Desc = {
    Text = "她是她最好的朋友。一直都是。"
  },
  Stage_51772_Name = {Text = "故人"},
  Stage_51773_Desc = {
    Text = "喝吧，这甘美的酒。跳吧，这热烈的舞。\n故国的主祭步入殿堂，抚摸她新的信徒。"
  },
  Stage_51773_Name = {Text = "血宴"},
  Stage_51774_Desc = {
    Text = "迷雾遮挡着求道者的面孔。迷雾遮挡着拥王者的心。"
  },
  Stage_51774_Name = {Text = "雾中人"},
  Stage_51775_Desc = {
    Text = "旧日的宫殿已成泡影，旧日的残梦空留余音。枯萎的王座上，只剩王的尸骸，仍在讲述着古老的寓言。"
  },
  Stage_51775_Name = {
    Text = "旧日泡影"
  },
  Stage_51785_Desc = {
    Text = "不可见的灾难复苏，物理世界的历史与存在正在坠入深渊。"
  },
