  },
  Stage_53775_Desc = {
    Text = "临行前，传记作家回望这栋蔷薇盛开的美丽宅邸，它远抵不上主人光芒的万分之一。\n有关索蕾尔夫人的传说还在继续，就在此刻的当下发生，我们都将成为见证。"
  },
  Stage_53775_Name = {
    Text = "终曲·之二"
  },
  Stage_53776_Desc = {
    Text = "她有很多身份：名媛、商人、掮客、收藏家……\n唯独没有她自己——很遗憾，蔷薇夫人从不为此失落。\n对她而言，原始的、未经雕琢的事物不值一提，复杂与浑浊才是最顶级的审美。"
  },
