  Stage_55139_Desc = {
    Text = "两只小小的手紧握在一起，许愿要一起前往美好的明天。"
  },
  Stage_55139_Name = {
    Text = "执手·之三"
  },
  Stage_55140_Desc = {
    Text = "大火清空了一切，所有艳红的花朵变成了纷飞在空中的灰屑。\n在土地的掩埋下，一卷诗稿静静旁观着一切。\n它曾被怎样的目光一遍遍翻阅呢？而如今落得蒙尘的境地。\n春天已逝，玫瑰亦被粗暴地抛弃了。\n玫瑰啊，可怜的玫瑰。"
  },
  Stage_55140_Name = {
    Text = "灰烬·之四"
  },
  Stage_55141_Desc = {
    Text = "大火清空了一切，所有艳红的花朵变成了纷飞在空中的灰屑。\n在土地的掩埋下，一卷诗稿静静旁观着一切。\n它曾被怎样的目光一遍遍翻阅呢？而如今落得蒙尘的境地。\n春天已逝，玫瑰亦被粗暴地抛弃了。\n玫瑰啊，可怜的玫瑰。"
  },
  Stage_55141_Name = {
    Text = "灰烬·之三"
  },
  Stage_55142_Desc = {
    Text = "大火清空了一切，所有艳红的花朵变成了纷飞在空中的灰屑。\n在土地的掩埋下，一卷诗稿静静旁观着一切。\n它曾被怎样的目光一遍遍翻阅呢？而如今落得蒙尘的境地。\n春天已逝，玫瑰亦被粗暴地抛弃了。\n玫瑰啊，可怜的玫瑰。"
  },
  Stage_55142_Name = {
    Text = "灰烬·癫狂"
  },
  Stage_55142_StageInitStateText = {Text = "终末"},
  Stage_55143_Desc = {
    Text = "小小的花房是属于她们的小小王国。\n在这渺小的王国里，她们一无所有，她们甘之如饴。"
  },
  Stage_55143_Name = {
    Text = "渺小王国·之四"
  },
  Stage_55144_Desc = {
    Text = "风靡的诗篇带来了一切，在好友的赞美中她羞红了脸。自己的诗，终于能够让好友不再为自己受苦了。她这样想着。\n然而她没有听到的是，恶毒的种子早已播种，只待将玫瑰紧紧缠绕、摧毁。"
  },
