  Stage_55167_Desc = {
    Text = "西岱是花与诗的城市，一首好诗能换一束鲜花。\n那是她的第一首诗，那是她种出的第一朵玫瑰。\n当手与手相碰之时，少女明媚的面庞比花与诗更加娇艳。"
