  Stage_55167_Name = {
    Text = "第一朵玫瑰·之一"
  },
  Stage_55391_Desc = {
    Text = "「让我用第一朵玫瑰，换你的第一首诗吧。」"
  },
  Stage_55391_Name = {Text = "诗篇1843"},
  Stage_55392_Desc = {
    Text = "花园是一道谜题，玫瑰是她的答案。"
  },
  Stage_55392_Name = {Text = "余香"},
  Stage_55393_Desc = {
    Text = "「让我用第一朵玫瑰，换你的第一首诗吧。」"
  },
  Stage_55393_Name = {Text = "诗篇1843"},
  Stage_55394_Desc = {
    Text = "没有哀悼，也没有风。\n只有诗人的余墨，为花园敲响的丧钟。"
  },
  Stage_55394_Name = {
    Text = "花园挽歌"
  },
  Stage_55395_Desc = {
    Text = "雕像是国王的修辞，沉默是雕像的修辞。"
  },
  Stage_55395_Name = {
    Text = "雕像修辞学"
  },
  Stage_55396_Desc = {
    Text = "她们隔着花园对视。\n花园中有无数条属于她们各自的路，每一条路都背道而驰。"
  },
  Stage_55396_Name = {
    Text = "小径分叉的花园"
  },
  Stage_55397_Desc = {
    Text = "用第一场葬礼告别骸骨，用第二场葬礼告别岁月。"
  },
  Stage_55397_Name = {
    Text = "迟来的葬礼"
  },
  Stage_55398_Desc = {
    Text = "优秀的诗歌，会让人身临其境。\n古典的美学理论这样介绍道。"
  },
  Stage_55398_Name = {Text = "诗中人"},
  Stage_55399_Desc = {
    Text = "西岱的繁花向您发来邀请，邀请您与它们一同走入这场梦境。"
  },
  Stage_55399_Name = {Text = "花之都"},
  Stage_55400_Desc = {
    Text = "所谓故乡，不过是一段旷日持久的谎言。"
  },
  Stage_55400_Name = {Text = "故乡"},
  Stage_55401_Desc = {
    Text = "「让我用第一朵玫瑰，换你的第一首诗吧。」"
  },
  Stage_55401_Name = {Text = "诗篇1843"},
  Stage_55551_Desc = {
    Text = "这座雪山拥有生命，山间回荡着声声呼啸，那是它在呼唤它的女儿。\n快来吧，快来吧。\n是女儿走向母亲，还是母亲走向女儿？\n雪山峰顶，两幅空落落的胃袋终于相见。"
  },
  Stage_55551_Name = {
    Text = "见山·之三"
  },
  Stage_55552_Desc = {
    Text = "这座雪山拥有生命，山间回荡着声声呼啸，那是它在呼唤它的女儿。\n快来吧，快来吧。\n是女儿走向母亲，还是母亲走向女儿？\n雪山峰顶，两幅空落落的胃袋终于相见。"
  },
  Stage_55552_Name = {
    Text = "见山·之二"
  },
  Stage_55553_Desc = {
    Text = "这座雪山拥有生命，山间回荡着声声呼啸，那是它在呼唤它的女儿。\n快来吧，快来吧。\n是女儿走向母亲，还是母亲走向女儿？\n雪山峰顶，两幅空落落的胃袋终于相见。"
  },
  Stage_55553_Name = {
    Text = "见山·之一"
  },
  Stage_55554_Desc = {
    Text = "雪山的冻土干枯暗淡，灭绝一切生机。\n但生命的意志永远顽强。\n只等雪山融化之时，冰凉的水滴落入土壤。\n一颗不屈的种子，立刻在山顶发芽。"
  },
  Stage_55554_Name = {
    Text = "破土·之五"
  },
  Stage_55555_Desc = {
    Text = "这座雪山拥有生命，山间回荡着声声呼啸，那是它在呼唤它的女儿。\n快来吧，快来吧。\n是女儿走向母亲，还是母亲走向女儿？\n雪山峰顶，两幅空落落的胃袋终于相见。"
  },
  Stage_55555_Name = {
    Text = "见山·癫狂"
  },
  Stage_55555_StageInitStateText = {Text = "繁育"},
  Stage_55556_Desc = {
    Text = "这座雪山拥有生命，山间回荡着声声呼啸，那是它在呼唤它的女儿。\n快来吧，快来吧。\n是女儿走向母亲，还是母亲走向女儿？\n雪山峰顶，两幅空落落的胃袋终于相见。"
  },
  Stage_55556_Name = {
    Text = "见山·之六"
  },
  Stage_55557_Desc = {
    Text = "这座雪山拥有生命，山间回荡着声声呼啸，那是它在呼唤它的女儿。\n快来吧，快来吧。\n是女儿走向母亲，还是母亲走向女儿？\n雪山峰顶，两幅空落落的胃袋终于相见。"
  },
  Stage_55557_Name = {
    Text = "见山·之五"
  },
  Stage_55558_Desc = {
    Text = "这座雪山拥有生命，山间回荡着声声呼啸，那是它在呼唤它的女儿。\n快来吧，快来吧。\n是女儿走向母亲，还是母亲走向女儿？\n雪山峰顶，两幅空落落的胃袋终于相见。"
  },
  Stage_55558_Name = {
    Text = "见山·之四"
  },
  Stage_55559_Desc = {
    Text = "镜中的两头野兽相遇，它们互相露出獠牙。\n它们额头相撞，谁都不肯认输。\n狂妄的你，软弱的我。\n双手交叠那一刻，镜子被打破。\n野兽发出低吼，露出猩红双眸。"
  },
  Stage_55559_Name = {
    Text = "斗兽·之四"
  },
  Stage_55560_Desc = {
    Text = "雪山的冻土干枯暗淡，灭绝一切生机。\n但生命的意志永远顽强。\n只等雪山融化之时，冰凉的水滴落入土壤。\n一颗不屈的种子，立刻在山顶发芽。"
  },
  Stage_55560_Name = {
    Text = "破土·之三"
  },
