  Stage_55584_StageInitStateText = {Text = "繁育"},
  Stage_55585_Desc = {
    Text = "雪山的冻土干枯暗淡，灭绝一切生机。\n但生命的意志永远顽强。\n只等雪山融化之时，冰凉的水滴落入土壤。\n一颗不屈的种子，立刻在山顶发芽。"
  },
  Stage_55585_Name = {
    Text = "破土·之四"
  },
  Stage_56404_Desc = {
    Text = "墨菲听说自己并非第一位圣女，在数千年的悠久时光中，无数位少女的躯壳内曾经鼓噪过近似的心跳。\n万千时空中，万千枚心脏交叠鼓动。"
  },
  Stage_56404_Name = {
    Text = "时空沟壑·癫狂"
  },
  Stage_56404_StageInitStateText = {Text = "海魇"},
  Stage_56405_Desc = {
    Text = "这是所有生命最后的体面归宿。\n以深海为棺，以天地为席，伟大的神明葬身于洋流。"
  },
  Stage_56405_Name = {
    Text = "裹尸布·癫狂"
  },
  Stage_56405_StageInitStateText = {Text = "海魇"},
  Stage_56407_Desc = {
    Text = "祂无声亦无心地降临。\n祂的心脏在她的血脉中，以并不渴求的姿态延续生存的搏动。"
  },
  Stage_56407_Name = {
    Text = "祂的降临·癫狂"
  },
  Stage_56407_StageInitStateText = {Text = "海魇"},
  Stage_56408_Desc = {
    Text = "她数着高空中的星辰，等待她并不期待的时刻。\n「星辰正位之刻」，群星在海面上升起之时，她将化为群星中的一颗。"
  },
  Stage_56408_Name = {
    Text = "黄色星辰·癫狂"
  },
  Stage_56408_StageInitStateText = {Text = "海魇"},
  Stage_56409_Desc = {
    Text = "她无权决定自己胸腔中被植入的胚胎的归属。\n她无权决定向哪里逃亡，无权决定牵住谁的手，无权决定和谁一起颠沛流离。\n在海上幻境浮浮沉沉的命运面前，谁都只是待宰的羔羊。"
  },
  Stage_56409_Name = {
    Text = "屠戮羔羊·癫狂"
  },
  Stage_56409_StageInitStateText = {Text = "海魇"},
  Stage_56410_Desc = {
    Text = "不必非得断头台来为她处刑。\n手刃她的是她的母亲。"
  },
  Stage_56410_Name = {
    Text = "行刑者·癫狂"
  },
  Stage_56410_StageInitStateText = {Text = "海魇"},
  Stage_56411_Desc = {
    Text = "安静。安静。安静。\n冰层之下万物永恒，连呼吸都被封冻。生存和死亡是同义词，正如蛰伏与复苏疏无区别。\n艾尔沃斯永远不会有属于她的春天。"
  },
  Stage_56411_Name = {
    Text = "蛰伏·癫狂"
  },
  Stage_56411_StageInitStateText = {Text = "海魇"},
  Stage_56843_Desc = {
    Text = "余音绕梁。\n以生命为代偿，他的乐章在祂的殿堂永恒回响。"
  },
  Stage_56843_Name = {
    Text = "余音·之六"
