    Text = "本性之门·之五"
  },
  Stage_56997_Desc = {
    Text = "此为「第一门」。\n入第一门者，需挣脱枷锁，舍弃本性，遗忘自身。\n囿于个体的视野无力承载荒诞的真实。"
  },
  Stage_56997_Name = {
    Text = "本性之门·之四"
  },
  Stage_56998_Desc = {
    Text = "他循声而来，踏上指挥台。\n他步伐稳健，胸有成竹。\n无人知晓他因梦而来，而梦的主人早已陷入迷失。"
  },
  Stage_56998_Name = {
    Text = "迷途梦引·之五"
  },
  Stage_56999_Desc = {
    Text = "此为「第一门」。\n入第一门者，需挣脱枷锁，舍弃本性，遗忘自身。\n囿于个体的视野无力承载荒诞的真实。"
  },
  Stage_56999_Name = {
    Text = "本性之门·之六"
  },
