  },
  Stage_57002_Name = {
    Text = "本性之门·之三"
  },
  Stage_57003_Desc = {
    Text = "此为「第一门」。\n入第一门者，需挣脱枷锁，舍弃本性，遗忘自身。\n囿于个体的视野无力承载荒诞的真实。"
  },
  Stage_57003_Name = {
    Text = "本性之门·之二"
  },
  Stage_57004_Desc = {
    Text = "启程吧。\n此行是通往「智慧」还是「愚昧」，只有踏上旅程才能知晓。"
  },
  Stage_57004_Name = {
    Text = "启程·之四"
  },
  Stage_57395_Desc = {
    Text = "与常识相反：在现实世界中，没有不在场证明反而会更安全。\n只要没有确凿的证据，警察就不能逮捕凶手。\n因此，请凶手们停止你们那些无谓的行径吧！"
  },
  Stage_57395_Name = {
    Text = "不在场供述·癫狂"
  },
  Stage_57395_StageInitStateText = {Text = "原初"},
  Stage_57396_Desc = {
    Text = "「作为叙述者的我就是凶手」——真是老套的伎俩，毫无美感与技巧。\n很不幸，这次还是被我给撞见了。"
  },
  Stage_57396_Name = {
    Text = "翻转诡计·癫狂"
  },
  Stage_57396_StageInitStateText = {Text = "原初"},
  Stage_57397_Desc = {
    Text = "侦探守则第一条：看上去越是平凡懦弱的委托人，背后的案子越大。\n以貌取人在这里可行不通。"
  },
  Stage_57397_Name = {
    Text = "不速之客·癫狂"
  },
  Stage_57397_StageInitStateText = {Text = "原初"},
  Stage_57398_Desc = {
    Text = "若是在案发现场发现了无头尸、无脸尸，不用怀疑——\n他的身份一定被掉包了。"
  },
  Stage_57398_Name = {
    Text = "无头尸·癫狂"
  },
  Stage_57398_StageInitStateText = {Text = "原初"},
  Stage_57399_Desc = {
    Text = "平凡的相貌、经历和姓名……\n当这些要素都集中在一个人身上，请放心大胆地将他排除在凶手行列吧。\n别问我原因。"
  },
  Stage_57399_Name = {
    Text = "幸运庸众·癫狂"
  },
  Stage_57399_StageInitStateText = {Text = "原初"},
  Stage_57400_Desc = {
    Text = "1,2,3……\n直到第5个人被杀害的时候，聪明如我也没能破案。\n为什么？因为这首歌谣一共有10句。"
  },
  Stage_57400_Name = {
    Text = "衔树枝·癫狂"
  },
  Stage_57400_StageInitStateText = {Text = "原初"},
  Stage_57401_Desc = {
    Text = "机械装置、凶手在室内、伪装他杀的自杀……\n说真的，花那么多功夫来制造密室，不如干脆雇一个杀手，不是更快吗？"
  },
  Stage_57401_Name = {
    Text = "密室迷思·癫狂"
  },
  Stage_57401_StageInitStateText = {Text = "原初"},
  Stage_57402_Desc = {
    Text = "不要排斥你的警察朋友。\n在推理的世界里，他们通常扮演被凶手耍得团团转的角色。\n最大的用处：在第一时间为你排除错误凶手。"
  },
  Stage_57402_Name = {
    Text = "侦探之友·癫狂"
  },
  Stage_57402_StageInitStateText = {Text = "原初"},
  Stage_57403_Desc = {
    Text = "如果阅读了以上推理准则，你成为一名侦探的热情依旧不减。\n那么祝你好运，你这个无可救药的傻蛋。"
  },
  Stage_57403_Name = {
    Text = "后记·癫狂"
  },
  Stage_57403_StageInitStateText = {Text = "原初"},
  Stage_57673_Desc = {
    Text = "挚友反目、手足相残、因爱生恨……\n祂以吸食人类的扭曲情感为乐，并自诩为自然主义者。\n「这是最纯粹、真实的情感。纯天然无加工，口感质朴清爽。」"
  },
  Stage_57673_Name = {Text = "悲剧秀"},
  Stage_57674_Desc = {
    Text = "刨除掉所有的不可能，剩下的只有真相。\n当然，量子物理学家对此持异议态度。"
  },
  Stage_57674_Name = {
    Text = "真相一种"
  },
  Stage_57675_Desc = {
    Text = "「如果……就……」是侦探最讨厌的句式。\n它意味着失败、悔恨与苦涩的松子酒，而他已经戒酒很多年了。"
  },
  Stage_57675_Name = {
    Text = "现实以下"
  },
  Stage_57676_Desc = {
    Text = "被所有人喜欢是一项了不起的成就；被所有人讨厌同理。\n而他能毫不费力地做到以上两点。\n真有你的，下周一先生！"
  },
  Stage_57676_Name = {
    Text = "下周一先生"
  },
  Stage_57677_Desc = {
    Text = "他是昨日，却也通晓今日。\n他与众神共居，他的生命永无结期。"
  },
  Stage_57677_Name = {Text = "棺中墙"},
  Stage_57678_Desc = {
    Text = "人是迟钝的生物。\n只需要在他们之间竖起一块木板，他们便再也无法辨认彼此的气息。"
  },
  Stage_57678_Name = {
    Text = "初次会晤"
  },
  Stage_57679_Desc = {
    Text = "八个小士兵，秉烛到夜半；\n悬梁了此生，八个只剩七。"
  },
  Stage_57679_Name = {
    Text = "无人生还"
  },
  Stage_57681_Desc = {
    Text = "他们皆身处死地，又一并向往生。"
  },
  Stage_57681_Name = {
    Text = "最后的致意"
  },
  Stage_57682_Desc = {
    Text = "古宅和幽灵的关系，大概就像奶酪与培根。\n很难说究竟谁先谁后，总之当大家反应过来的时候，它们已经牢不可分了。"
  },
  Stage_57682_Name = {
    Text = "幽灵之家"
  },
  Stage_57683_Desc = {
    Text = "不过是从结果或立场倒推所谓的「原因」罢了。\n人类历史上到处都在发生这样的滑稽剧。"
  },
  Stage_57683_Name = {
    Text = "逆向推理"
  },
  Stage_57684_Desc = {
    Text = "他们皆身处死地，又一并向往生。"
  },
  Stage_57684_Name = {
    Text = "最后的致意"
  },
  Stage_57685_Desc = {
    Text = "愿好运伴你常在，侦探先生。\n后会有期。"
  },
  Stage_57685_Name = {
    Text = "祝你好运！"
  },
  Stage_57686_Desc = {
    Text = "每当考试来临，我都期待一场灾难。\n洪水、飓风、小行星撞击……什么都行，只要能将现实短暂地踢走一小会。\n就一小会。"
  },
  Stage_57686_Name = {
    Text = "不速之客"
  },
  Stage_57687_Desc = {
    Text = "他们皆身处死地，又一并向往生。"
  },
  Stage_57687_Name = {
    Text = "最后的致意"
  },
  Stage_58064_Desc = {
    Text = "愚昧的人啊，你们点燃了火焰，将希望与救赎付之一炬。\n当你们在漆黑的死亡中挣扎时，这自诩的正义滋味又如何？"
  },
  Stage_58064_Name = {
    Text = "忏悔·癫狂"
  },
  Stage_58064_StageInitStateText = {Text = "繁育"},
  Stage_58065_Desc = {
    Text = "愚昧的人啊，你们点燃了火焰，将希望与救赎付之一炬。\n当你们在漆黑的死亡中挣扎时，这自诩的正义滋味又如何？"
  },
  Stage_58065_Name = {
    Text = "忏悔·之六"
  },
  Stage_58066_Desc = {
    Text = "他们拒绝理解，拒绝包容。\n他们的世界只有黑与白，尽管他们自己都无法掌控其定义。\n「烧死他，烧死他！」\n「烧死这个异端主教！让邪恶死亡！」"
  },
  Stage_58066_Name = {
    Text = "偏执·之四"
  },
