  },
  Stage_58074_Name = {
    Text = "忏悔·之一"
  },
  Stage_58075_Desc = {
    Text = "对病痛的恐慌让他们心有不甘。\n「凭什么只给他赐福？我也生病了！」\n「我才是最严重的，我才应该第一个受祝！」"
  },
