  },
  Stage_58082_Desc = {
    Text = "那些让他们受益的才是好的，所有未能落在他们身上的祝福都是诅咒。\n「什么赐福，分明是邪恶的血魔法！」\n「这一定是巫术，他是恶魔！」"
  },
