  },
  Stage_58097_Desc = {
    Text = "愚昧的人啊，你们点燃了火焰，将希望与救赎付之一炬。\n当你们在漆黑的死亡中挣扎时，这自诩的正义滋味又如何？"
  },
  Stage_58097_Name = {
    Text = "忏悔·之二"
  },
  Stage_58098_Desc = {
    Text = "他们拒绝理解，拒绝包容。\n他们的世界只有黑与白，尽管他们自己都无法掌控其定义。\n「烧死他，烧死他！」\n「烧死这个异端主教！让邪恶死亡！」"
  },
  Stage_58098_Name = {
    Text = "偏执·之一"
  },
  Stage_58333_Desc = {
    Text = "夜晚，女王站在宫殿露台上，凝望着数千英尺下的城池。\n日复一日，每当她想跨出宫殿一步，便会引来眩晕、眼泪、以及大片的记忆空白。\n「准备好了吗？迎接这个世界的真实。」\n她深吸一口气，从露台上跳了下去。"
  },
