  Stage_58358_Desc = {
    Text = "洪积315年12月@2日，她被宣布为无形。\n她大声呼喊，却无人理睬；她偷面包，却不被抓住监禁。\n名为忘却的疾病感染了所有人，唯独将她遗漏。"
