  },
  Stage_58378_Desc = {
    Text = "女王和她不朽的城池——伊萨拉乌。\n宇宙眷顾的双生子啊，你们被命运的脐带轻轻缠绕。\n有人说，智慧的女王率领民众来到伊萨拉乌，就像《启示录》里所描绘的。\n也有人说，伊萨拉乌的河床终年涌动，直到将女王孕育而出。"
  },
  Stage_58378_Name = {
    Text = "启示录·之四"
  },
  Stage_58379_Desc = {
    Text = "伊萨拉乌就这样消失了，仿佛它从未诞生。\n所有的街道、子民都是虚幻。它们从她的梦中诞生，在日复一日的勾勒中不断具象，然后：\n「砰——」\n梦醒了。她从未睁眼看过伊萨拉乌，正如她从未睁眼看过自己。"
  },
