  Stage_58403_Name = {
    Text = "黄金之城·癫狂"
  },
  Stage_58403_StageInitStateText = {Text = "终末"},
  Stage_58404_Desc = {
    Text = "夜晚，女王站在宫殿露台上，凝望着数千英尺下的城池。\n日复一日，每当她想跨出宫殿一步，便会引来眩晕、眼泪、以及大片的记忆空白。\n「准备好了吗？迎接这个世界的真实。」\n她深吸一口气，从露台上跳了下去。"
  },
