  Stage_58407_Name = {
    Text = "黄金之城·之三"
  },
  Stage_58408_Desc = {
    Text = "地狱是一个空房间，里面摆放着无数镜子。\n她不敢睁开双眼，因为俯仰皆是她那张苍白惊惧的脸。\n冥冥中，有个声音在说：\n这是报应。你生前只有一具皮囊；死后遭报应时有无数具。"
  },
