  },
  Stage_58432_Desc = {
    Text = "祈祷是利莫里亚人学会的第一件事，可出现在她面前保护她的，从来不是她的王。"
  },
  Stage_58432_Name = {
    Text = "质疑·之二"
  },
  Stage_58433_Desc = {
    Text = "她觉得有无数条蛇像网一样缠住了自己。\n醒来后，一个影子站在她的床前。它说：\n「无论你到什么地方，我都要抹掉你，正如你现在抹掉我的脸一样。」"
  },
  Stage_58433_Name = {
    Text = "无意识记·之一"
  },
  Stage_58434_Desc = {
    Text = "她觉得有无数条蛇像网一样缠住了自己。\n醒来后，一个影子站在她的床前。它说：\n「无论你到什么地方，我都要抹掉你，正如你现在抹掉我的脸一样。」"
