  },
  Stage_58438_Name = {
    Text = "无意识记·癫狂"
  },
  Stage_58438_StageInitStateText = {Text = "原初"},
  Stage_58439_Desc = {
    Text = "她觉得有无数条蛇像网一样缠住了自己。\n醒来后，一个影子站在她的床前。它说：\n「无论你到什么地方，我都要抹掉你，正如你现在抹掉我的脸一样。」"
  },
  Stage_58439_Name = {
    Text = "无意识记·之六"
  },
  Stage_58440_Desc = {
    Text = "它已经成为她灵魂中那个可憎的区域的象征。\n她同它一起受苦，一起死去，在某种意义上同它一起消失。\n因此她心如铁石，毫不容情。"
  },
  Stage_58440_Name = {
    Text = "爬虫脑·之三"
  },
  Stage_58441_Desc = {
    Text = "它已经成为她灵魂中那个可憎的区域的象征。\n她同它一起受苦，一起死去，在某种意义上同它一起消失。\n因此她心如铁石，毫不容情。"
  },
  Stage_58441_Name = {
    Text = "爬虫脑·之二"
  },
  Stage_58442_Desc = {
    Text = "它已经成为她灵魂中那个可憎的区域的象征。\n她同它一起受苦，一起死去，在某种意义上同它一起消失。\n因此她心如铁石，毫不容情。"
  },
  Stage_58442_Name = {
    Text = "爬虫脑·之一"
  },
  Stage_58443_Desc = {
    Text = "它已经成为她灵魂中那个可憎的区域的象征。\n她同它一起受苦，一起死去，在某种意义上同它一起消失。\n因此她心如铁石，毫不容情。"
  },
  Stage_58443_Name = {
    Text = "爬虫脑·癫狂"
  },
  Stage_58443_StageInitStateText = {Text = "原初"},
  Stage_58444_Desc = {
    Text = "它已经成为她灵魂中那个可憎的区域的象征。\n她同它一起受苦，一起死去，在某种意义上同它一起消失。\n因此她心如铁石，毫不容情。"
  },
  Stage_58444_Name = {
    Text = "爬虫脑·之六"
  },
  Stage_58445_Desc = {
    Text = "它已经成为她灵魂中那个可憎的区域的象征。\n她同它一起受苦，一起死去，在某种意义上同它一起消失。\n因此她心如铁石，毫不容情。"
  },
  Stage_58445_Name = {
    Text = "爬虫脑·之五"
  },
  Stage_58446_Desc = {
    Text = "它已经成为她灵魂中那个可憎的区域的象征。\n她同它一起受苦，一起死去，在某种意义上同它一起消失。\n因此她心如铁石，毫不容情。"
  },
  Stage_58446_Name = {
    Text = "爬虫脑·之四"
  },
  Stage_58449_Desc = {
    Text = "余音绕梁。\n以生命为代偿，他的乐章在祂的殿堂永恒回响。"
  },
  Stage_58449_Name = {
    Text = "余音·癫狂"
  },
  Stage_58449_StageInitStateText = {Text = "原初"},
  Stage_58450_Desc = {
    Text = "大幕垂下。\n他以昂首之姿渐隐于逐步坠落的红丝绒幕布之后。"
  },
  Stage_58450_Name = {
    Text = "幕落·癫狂"
  },
  Stage_58450_StageInitStateText = {Text = "原初"},
  Stage_58451_Desc = {
    Text = "此为「第四门」。\n入第四门者，得见「祂」之真容。\n既见宇宙之博大，则了悟自身之渺小。不以蝼蚁撼树。"
  },
  Stage_58451_Name = {
    Text = "知行之门·癫狂"
  },
  Stage_58451_StageInitStateText = {Text = "原初"},
  Stage_58452_Desc = {
    Text = "欢迎来到人偶之屋，这里有一千个一模一样的笑容。\n嘻嘻，哪一个是你曾经的朋友？"
  },
  Stage_58452_Name = {
    Text = "人偶之屋·癫狂"
  },
  Stage_58453_Desc = {
    Text = "这世上本来没有门。\n想要门的人多了，世上便有了各种各样的门。\n人人都说自己的门背后才是天堂。\n然而啊，那古老的预言早已言明，这世上从来就没有门。\n想在人间建立天堂的，终会开启地狱的大门。"
  },
  Stage_58453_Name = {
    Text = "混沌预言·癫狂"
  },
  Stage_58454_Desc = {
    Text = "人偶的手中垂下丝线，勾连着世界的零件。\n咔哒、滋啦，动动手指，世界崩坏。\n又是什么垂在人偶头顶，使它不断为虚无献上舞蹈。"
  },
  Stage_58454_Name = {
    Text = "傀儡线·癫狂"
  },
  Stage_58455_Desc = {
    Text = "轻快乐章。\n他们活跃于整片大地，他们抗争的身姿如此美妙。"
  },
  Stage_58455_Name = {
    Text = "小步舞曲·癫狂"
  },
  Stage_58455_StageInitStateText = {Text = "原初"},
  Stage_58456_Desc = {
    Text = "此为「第三门」。\n入第三门者，不拘泥于粗浅的理智，得以知晓界限之外的知识。"
  },
  Stage_58456_Name = {
    Text = "理智之门·癫狂"
  },
  Stage_58456_StageInitStateText = {Text = "原初"},
  Stage_58457_Desc = {
    Text = "跳吧，跳吧，不要停下你的步伐。\n扬起裙摆，转开圆圈，因这世界早已在漩涡中不停旋转。 \n放下顾虑的一切，加入最后的狂欢。\n只要奋力舞蹈，就能看见永恒的夕阳。"
  },
  Stage_58457_Name = {
    Text = "狂欢舞会·癫狂"
  },
  Stage_58458_Desc = {
    Text = "奏鸣曲式。\n由一裂变为三，三角之中，圆睁的眼球俯瞰大地。"
  },
  Stage_58458_Name = {
    Text = "快板·癫狂"
  },
  Stage_58458_StageInitStateText = {Text = "原初"},
  Stage_58459_Desc = {
    Text = "她拥有了王所预言的一切——强大的力量，坚定的信仰。她背负曾质疑王的罪孽，踏上迎接神国的路。"
  },
  Stage_58459_Name = {
    Text = "笃信·癫狂"
  },
  Stage_58459_StageInitStateText = {Text = "海魇"},
  Stage_58460_Desc = {
    Text = "此为「第五门」。\n入第五门者，与寰宇同享无上秘密。\n万物均为「祂」的一呼一吸所化，亦将因「祂」的吐息而湮没。"
  },
  Stage_58460_Name = {
    Text = "归一之门·癫狂"
  },
  Stage_58460_StageInitStateText = {Text = "原初"},
  Stage_58461_Desc = {
    Text = "她伸出手，邀你做她的舞伴。\n前进，后退，这种默契只你二人独有。\n轻握她的手掌，跟上她的脚步，不要低下绅士的头颅。\n哪怕脚下早已是悬崖边缘。"
  },
  Stage_58461_Name = {
    Text = "邀请·癫狂"
  },
  Stage_58462_Desc = {
    Text = "此为「第六门」。\n入第六门者，贯联诸世，于万千维度中得求永恒的存续。"
  },
  Stage_58462_Name = {
    Text = "诸世之门·癫狂"
  },
  Stage_58462_StageInitStateText = {Text = "原初"},
  Stage_58463_Desc = {
    Text = "抒情乐章。\n哺育，繁衍，生生不息。"
  },
  Stage_58463_Name = {
    Text = "慢板·癫狂"
  },
  Stage_58463_StageInitStateText = {Text = "原初"},
  Stage_58464_Desc = {
    Text = "启程吧。\n此行是通往「智慧」还是「愚昧」，只有踏上旅程才能知晓。"
  },
  Stage_58464_Name = {
    Text = "启程·癫狂"
  },
  Stage_58464_StageInitStateText = {Text = "原初"},
  Stage_58465_Desc = {
    Text = "交响不是一个人的游戏。\n弦乐、木管乐、铜管乐、打击乐。\n编制规整的器乐组低垂着头颅，等待他给予的指引。"
  },
  Stage_58465_Name = {
    Text = "管弦编制·癫狂"
  },
  Stage_58465_StageInitStateText = {Text = "原初"},
  Stage_58466_Desc = {
    Text = "他循声而来，踏上指挥台。\n他步伐稳健，胸有成竹。\n无人知晓他因梦而来，而梦的主人早已陷入迷失。"
  },
  Stage_58466_Name = {
    Text = "迷途梦引·癫狂"
  },
  Stage_58466_StageInitStateText = {Text = "原初"},
  Stage_58467_Desc = {
    Text = "此为「第一门」。\n入第一门者，需挣脱枷锁，舍弃本性，遗忘自身。\n囿于个体的视野无力承载荒诞的真实。"
  },
  Stage_58467_Name = {
    Text = "本性之门·癫狂"
  },
  Stage_58467_StageInitStateText = {Text = "原初"},
  Stage_58468_Desc = {
    Text = "此为「第二门」。\n入第二门者，勿妄断是非。\n是非只是规则制定者的臆断，而真理的所在超越一切知识。"
  },
  Stage_58468_Name = {
    Text = "是非之门·癫狂"
  },
  Stage_58468_StageInitStateText = {Text = "原初"},
  Stage_58469_Desc = {
    Text = "回旋曲式。\n他将指引末路的方向，直面毁灭。"
  },
  Stage_58469_Name = {
    Text = "终曲·癫狂"
  },
  Stage_58469_StageInitStateText = {Text = "原初"},
  Stage_58470_Desc = {
    Text = "神国的轮廓在她眼前出现。神国的钟声在她耳中敲响。她将践行王的预言，永不停息。\n她以此言得度此生的茫茫黑夜。"
  },
  Stage_58470_Name = {
    Text = "降临·癫狂"
  },
  Stage_58470_StageInitStateText = {Text = "海魇"},
  Stage_58471_Desc = {
    Text = "末日到来，世界长满脓疮，衰亡的漩涡将席卷所有生灵。\n祈祷吧，寻找吧，那从不存在的求生之门。"
  },
  Stage_58471_Name = {
    Text = "狂灾·癫狂"
  },
  Stage_58472_Desc = {
    Text = "失去一切的那天，她终于明白，唯有王能拯救利莫里亚的子民。\n她等待着，在那遥远的神国，与自己所失去的一切重逢。"
  },
  Stage_58472_Name = {
    Text = "见证·癫狂"
  },
  Stage_58472_StageInitStateText = {Text = "海魇"},
  Stage_58473_Desc = {
    Text = "利莫里亚消亡了。神明从未在意这片土地。\n神国，从未存在过。"
  },
  Stage_58473_Name = {
    Text = "动摇·癫狂"
  },
  Stage_58473_StageInitStateText = {Text = "海魇"},
  Stage_58474_Desc = {
    Text = "为何你仍不肯舍弃？为何你仍愚钝如初？\n……守护他们吗。\n如果这便是你的答案，你终将献出你的骨，你的血，你的灵知，你的一切。"
  },
  Stage_58474_Name = {
    Text = "门扉之内·癫狂"
  },
  Stage_58474_StageInitStateText = {Text = "原初"},
  Stage_58475_Desc = {
    Text = "有一颗星星挂在黏稠的黑夜中。\n那星星膨胀，发光，变成了无限大的棉花糖。\n这是某人凝聚了一生的爱恨，尝一尝，是什么味道？"
  },
  Stage_58475_Name = {
    Text = "星星·癫狂"
  },
  Stage_58476_Desc = {
    Text = "祈祷是利莫里亚人学会的第一件事，可出现在她面前保护她的，从来不是她的王。"
  },
  Stage_58476_Name = {
    Text = "质疑·癫狂"
  },
  Stage_58476_StageInitStateText = {Text = "海魇"},
  Stage_58477_Desc = {
    Text = "无数人渴求真实，前仆后继。\n无数人捧着真实的碎片，以为盲眼获得了光明，便开始鼓吹天堂的美好。\n只有她找到了真实之酒， 将那琼浆一口饮下。\n咕咚。\n她颓然醉倒，她毒入膏肓。\n果然无数的傻子已然证明，真实只是一杯毒药。\n饮少者毒发，饮多者身亡。\n如今她已时日无多，只想与你共同品尝。"
  },
  Stage_58477_Name = {
    Text = "真实毒药·癫狂"
  },
  Stage_58478_Desc = {
    Text = "像烟花一样绽放吧，哪怕燃料是生命。\n既然终点相仿，何不省去漫长苦痛，换来璀璨光芒。"
  },
  Stage_58478_Name = {
    Text = "璀璨消亡·癫狂"
  },
  Stage_58479_Desc = {
    Text = "此为「第七门」。\n时间的洪流在此处暂停，永恒的智慧将引领彷徨的探求者走出最深的迷惘。"
  },
  Stage_58479_Name = {
    Text = "穷极之门·癫狂"
  },
  Stage_58479_StageInitStateText = {Text = "原初"},
  Stage_58480_Desc = {
    Text = "开场，辨明主题。\n他将叙述伊始和终末，吞吐与呼吸。"
  },
  Stage_58480_Name = {
    Text = "序曲·癫狂"
  },
  Stage_58480_StageInitStateText = {Text = "原初"},
  Stage_58691_Desc = {
    Text = "风销雪霁，万物生长。"
  },
  Stage_58691_Name = {
    Text = "一个春天"
  },
  Stage_58692_Desc = {
    Text = "哀悼，或者惊叹。这是一名战士，面向群山的宣战。"
  },
  Stage_58692_Name = {Text = "刺山"},
  Stage_58693_Desc = {
    Text = "她的衣衫随风舞动，她的迷茫轻声作响。她站在你的面前。"
  },
  Stage_58693_Name = {Text = "重逢"},
  Stage_58694_Desc = {
    Text = "你们没有找到敌人，但敌人找到了你们。"
  },
  Stage_58694_Name = {Text = "黑影"},
  Stage_58695_Desc = {
    Text = "回来吧，孩子。山呼唤道。\n回应母亲亲切的召唤，回归命运安宁的怀抱。"
  },
  Stage_58695_Name = {
    Text = "群山的呼唤"
  },
  Stage_58696_Desc = {
    Text = "他们的故事无人知晓。他们的名字无人悼念。"
  },
  Stage_58696_Name = {Text = "祭品"},
  Stage_58697_Desc = {
    Text = "对于你们的礼貌造访，艾尔沃斯似乎并不那么欢迎。"
  },
  Stage_58697_Name = {
    Text = "雪原来客"
  },
  Stage_58698_Desc = {
    Text = "在月色与雪色之间，血是第三种色彩。"
  },
  Stage_58698_Name = {
    Text = "漫漫寒夜"
  },
  Stage_58699_Desc = {
    Text = "很难判断，究竟是哪个更危险。"
  },
  Stage_58699_Name = {
    Text = "同伴或敌人"
  },
  Stage_58700_Desc = {
    Text = "哀悼，或者惊叹。这是一名战士，面向群山的宣战。"
  },
  Stage_58700_Name = {Text = "刺山"},
  Stage_58701_Desc = {
    Text = "哀悼，或者惊叹。这是一名战士，面向群山的宣战。"
  },
  Stage_58701_Name = {Text = "刺山"},
  Stage_58976_Desc = {
    Text = "「我会看着你，坚定不移地走上这条绝路……我会在你的葬礼上，为你哀悼。」"
  },
  Stage_58976_Name = {
    Text = "存续之道"
  },
  Stage_58977_Desc = {
    Text = "「我喜欢剧院里的很多桥段。但我最喜欢的，是他们将最美丽的瓷器扔下阁楼的时刻。」"
  },
  Stage_58977_Name = {Text = "父与女"},
  Stage_58978_Desc = {
    Text = "坎坷，漫长，虚无。每个人都有自己将要面对的道路。\n当你终于站在起点，你是否有足够的勇气，凝望你的远方？"
  },
  Stage_58978_Name = {Text = "路"},
  Stage_58979_Desc = {
    Text = "节拍。旋律。弦乐柔和的泛音充盈你们的脑海。\n观众沉默的目光里，指挥家站上属于他的舞台。"
  },
  Stage_58979_Name = {Text = "指挥家"},
  Stage_58980_Desc = {
    Text = "他虚弱的身体被淹没在沸腾的地底。\n在那虚幻的维度，他独自与黑池对决。"
  },
  Stage_58980_Name = {Text = "残躯"},
  Stage_58981_Desc = {
    Text = "走音，缺位……任何一个失误，都会让一场演出万劫不复。\n练习。在无数的练习中，等待属于你的掌声。"
  },
  Stage_58981_Name = {Text = "排练"},
  Stage_58982_Desc = {
    Text = "遗忘，是对这世界最终的净化？弥萨格从不认同。\n这座校园里的人们，将为铭记而战。"
  },
  Stage_58982_Name = {
    Text = "遗忘之理"
  },
  Stage_58982_StageInitStateText = {Text = "终末"},
  Stage_58983_Desc = {
    Text = "轻松的舞曲，愉悦的谐谑，缺乏变化的庸俗之作。\n没错，在第三乐章小憩吧。这里安全，平静，毫无意外。"
  },
  Stage_58983_Name = {
    Text = "第三乐章"
  },
  Stage_58984_Desc = {
    Text = "无从哀求。无从逃避。这是这个世界的命运。\n战胜祂们。杀死祂们。然后，拯救祂们。"
  },
  Stage_58984_Name = {Text = "宿命"},
  Stage_58985_Desc = {
    Text = "提前透露的转折便失去了力度，但他从不在乎。\n他所期待的欢愉，不在此处。"
  },
  Stage_58985_Name = {
    Text = "德克斯特式转折"
  },
  Stage_58986_Desc = {
    Text = "嘘。\n最后的听众已然落座，真正的演出，就要开始了。"
  },
  Stage_58986_Name = {Text = "入场"},
  Stage_58987_Desc = {
    Text = "当信息不对等的时候，越完美，便越错误。"
  },
  Stage_58987_Name = {
    Text = "好学生，坏学生"
  },
  Stage_58988_Desc = {
    Text = "「弥萨格独立于雷欧王国政府及密斯底亚协定审查会的管辖范围。凡未经授权擅入者，均视作非法入侵，弥萨格有权充分行使自卫权。」"
  },
  Stage_58988_Name = {Text = "校规"},
  Stage_59049_Desc = {
    Text = "节拍。旋律。弦乐柔和的泛音充盈你们的脑海。\n观众沉默的目光里，指挥家站上属于他的舞台。"
  },
