  },
  Stage_59502_Desc = {
    Text = "面对你们最原初的绝望。面对你们最原初的恐惧。\n站在看不见的彼此身边，然后战胜祂。"
  },
  Stage_59502_Name = {
    Text = "决胜：原初之影"
  },
  Stage_59503_Desc = {
    Text = "铭记是你的誓言，遗忘是你的祭礼。"
  },
  Stage_59503_Name = {Text = "祭礼"},
  Stage_59503_StageInitStateText = {Text = "原初"},
  Stage_59504_Desc = {
    Text = "站在梦境的神殿，支撑起坍塌的残垣。\n守护你身下，那粒承载你所有顾惜与挂念的尘埃。"
  },
  Stage_59504_Name = {
    Text = "梦的崩析"
  },
  Stage_59504_StageInitStateText = {Text = "原初"},
  Stage_59505_Desc = {
    Text = "「生存，还是毁灭？」"
  },
  Stage_59505_Name = {Text = "引路人"},
  Stage_59505_StageInitStateText = {Text = "原初"},
  Stage_59506_Desc = {
    Text = "铭记是你的誓言，遗忘是你的祭礼。"
  },
  Stage_59506_Name = {Text = "祭礼"},
  Stage_59506_StageInitStateText = {Text = "原初"},
