  Stage_59509_Name = {Text = "引路人"},
  Stage_59509_StageInitStateText = {Text = "原初"},
  Stage_59510_Desc = {
    Text = "站在梦境的神殿，支撑起坍塌的残垣。\n守护你身下，那粒承载你所有顾惜与挂念的尘埃。"
