  },
  Stage_59511_Desc = {
    Text = "铭记是你的誓言，遗忘是你的祭礼。"
  },
  Stage_59511_Name = {Text = "祭礼"},
  Stage_62348_Desc = {
    Text = "这是群星的高潮。这是寰宇的落幕。\n在这阒寂之中，认真聆听——\n那真正的音符，你听到了吗？"
  },
  Stage_62348_Name = {Text = "终曲"},
  Stage_66016_Desc = {
    Text = "祂是无上的意志，宇宙的造物主，万物的终结者。\n在祂的面前悲泣吧。为你们孱弱的勇气，为祂无尽的权柄。"
  },
  Stage_66016_Name = {
    Text = "济贫院·悲泣之视"
  },
  Stage_66016_StageInitStateText = {Text = "原初"},
  Stage_66017_Desc = {
    Text = "祂是无上的意志，宇宙的造物主，万物的终结者。\n在祂的面前悲泣吧。为你们孱弱的勇气，为祂无尽的权柄。"
  },
  Stage_66017_Name = {
    Text = "济贫院·悲泣之视"
  },
  Stage_66017_StageInitStateText = {Text = "原初"},
  Stage_66018_Desc = {
    Text = "祂是无上的意志，宇宙的造物主，万物的终结者。\n在祂的面前悲泣吧。为你们孱弱的勇气，为祂无尽的权柄。"
  },
  Stage_66018_Name = {
    Text = "济贫院·悲泣之视"
  },
  Stage_66381_Desc = {
    Text = "无须担心，恐惧是生物最原始的本能。\n神明从不为难任何一只蝼蚁。祂以苏醒为你们赐福。"
  },
  Stage_66381_Name = {
    Text = "蜡像馆·恐惧之视"
  },
  Stage_66381_StageInitStateText = {Text = "原初"},
  Stage_66382_Desc = {
    Text = "歌咏吧，伟大的造物主！\n在祂入梦时，生民繁荣兴盛。\n在祂睁眼时，万物化为尘埃。"
  },
  Stage_66382_Name = {
    Text = "布里尔珀特·邪信之视"
  },
  Stage_66382_StageInitStateText = {Text = "原初"},
  Stage_66383_Desc = {
    Text = "感受疼痛吧，感受无上意志最原始的馈赠。\n在疼痛中，窥见造物主的威仪。"
  },
  Stage_66383_Name = {
    Text = "拉伊·刺骨之视"
  },
  Stage_66383_StageInitStateText = {Text = "原初"},
  Stage_66384_Desc = {
    Text = "不必挣扎。不必抗争。不必尝试理解不可理解之物。\n在无上意志的目光中，迎接梦境的终结。"
  },
  Stage_66384_Name = {
    Text = "疗养院·诡谲之视"
  },
  Stage_66384_StageInitStateText = {Text = "原初"},
  Stage_66385_Desc = {
    Text = "祂是无上的意志，宇宙的造物主，万物的终结者。\n在祂的面前悲泣吧。为你们孱弱的勇气，为祂无尽的权柄。"
  },
  Stage_66385_Name = {
    Text = "济贫院·悲泣之视"
  },
  Stage_66385_StageInitStateText = {Text = "原初"},
  Stage_67123_Desc = {
    Text = "那宏伟的文明，那人间的悲欢，那环绕你远离你的无数的人，从未存在过。梦境的消解，终将诞临。\n忘却吧，守密人们。忘却是最隆重的苦难。\n忘却是至福的解药。"
  },
  Stage_67123_Name = {
    Text = "勒姆瓦希·诞临之视"
  },
  Stage_67123_StageInitStateText = {Text = "原初"},
  Stage_67124_Desc = {
    Text = "盲目痴愚的洪流上，秩序的楼阁轰然坍塌。\n理性从未存在过，唯有疯狂是你们的归宿。"
  },
  Stage_67124_Name = {
    Text = "索纳尼尔号·疯狂之视"
  },
  Stage_67124_StageInitStateText = {Text = "原初"},
