  Stage_67907_StageInitStateText = {Text = "原初"},
  Stage_67908_Desc = {
    Text = "不必挣扎。不必抗争。不必尝试理解不可理解之物。\n在无上意志的目光中，迎接梦境的终结。"
  },
  Stage_67908_Name = {
    Text = "疗养院·诡谲之视"
  },
  Stage_67908_StageInitStateText = {Text = "原初"},
  Stage_67909_Desc = {
    Text = "不必挣扎。不必抗争。不必尝试理解不可理解之物。\n在无上意志的目光中，迎接梦境的终结。"
  },
  Stage_67909_Name = {
    Text = "疗养院·诡谲之视"
  },
  Stage_67909_StageInitStateText = {Text = "原初"},
  Stage_67910_Desc = {
    Text = "无须担心，恐惧是生物最原始的本能。\n神明从不为难任何一只蝼蚁。祂以苏醒为你们赐福。"
  },
  Stage_67910_Name = {
    Text = "蜡像馆·恐惧之视"
  },
  Stage_67910_StageInitStateText = {Text = "原初"},
  Stage_67911_Desc = {
    Text = "盲目痴愚的洪流上，秩序的楼阁轰然坍塌。\n理性从未存在过，唯有疯狂是你们的归宿。"
  },
  Stage_67911_Name = {
    Text = "索纳尼尔号·疯狂之视"
  },
  Stage_67911_StageInitStateText = {Text = "原初"},
  Stage_67912_Desc = {
    Text = "那宏伟的文明，那人间的悲欢，那环绕你远离你的无数的人，从未存在过。梦境的消解，终将诞临。\n忘却吧，守密人们。忘却是最隆重的苦难。\n忘却是至福的解药。"
  },
  Stage_67912_Name = {
    Text = "勒姆瓦希·诞临之视"
  },
  Stage_67912_StageInitStateText = {Text = "原初"},
  Stage_67913_Desc = {
    Text = "对蚍蜉而言，生存与毁灭从不是问题。\n它们生来便是要面对巨树的。"
  },
  Stage_67913_Name = {Text = "蚍蜉"},
  Stage_67913_StageInitStateText = {Text = "原初"},
  Stage_67914_Desc = {
    Text = "%hisorher%名字与功绩将无人知晓。%heorshe%来自遗忘，归于遗忘。只有墓碑上的箴言与世长存。\n银钥曾指引%hisorher%前路。未来的道路，亦愿银钥指引你我。"
  },
  Stage_67914_Name = {
    Text = "告别：K-0617"
  },
