  Stage_70107_StageInitStateText = {Text = "繁育"},
  Stage_70108_Desc = {
    Text = "再生花是永恒的循环。\n生命鼎盛之时，勿要忘记：昼夜的秘密和季节的耳语都将随着花落凋敝。\n以死亡为终局，便是以诞生为伊始。"
  },
  Stage_70108_Name = {
    Text = "再生花·呓语之六"
