  Stage_70109_StageInitStateText = {Text = "繁育"},
  Stage_70110_Desc = {
    Text = "授粉是遥远的邂逅。\n花枝摇曳邀约共舞的使者，邀约它撷取花粉，流连花丛，在自然的律动中将新生命的源泉送入另一个等待的怀抱。"
