  Stage_70924_Desc = {
    Text = "亲爱的，让我们去看看末日。\n与其在绝望中日益衰朽，不如趁着命运尚未降临，亲手建树终末的伟业。"
  },
  Stage_70924_Name = {
    Text = "未选择的路"
  },
  Stage_70925_Desc = {
    Text = "数字从来并非名称，只是符号。\n凡庸的生命不愿割舍自身虚构的独特性，故而抗拒以数字作为自己的代称。\n她从不在意。"
  },
  Stage_70925_Name = {Text = "B-68"},
  Stage_70926_Desc = {
    Text = "可能性不等同于好的结局，但蜃景亦是前行者的饵料。"
  },
  Stage_70926_Name = {
    Text = "可能性的答案"
  },
  Stage_70927_Desc = {
    Text = "咕噜，咕噜，咕噜。器官发出迫切渴求的悲呼。\n不是肚中饥鸣，它的空虚源自大脑。"
  },
  Stage_70927_Name = {
    Text = "人间食粮"
  },
  Stage_70928_Desc = {
    Text = "雨。绵延不绝的雨。"
  },
  Stage_70928_Name = {
    Text = "雨幕之中"
  },
  Stage_70929_Desc = {
    Text = "一阶一阶一阶，祂的触肢探向深梦的底层。"
  },
  Stage_70929_Name = {Text = "深梦"},
  Stage_70930_Desc = {
    Text = "眼睛，我不敢在梦中相遇\n在死亡的梦幻国土"
  },
  Stage_70930_Name = {Text = "空心人"},
  Stage_70931_Desc = {
    Text = "人类将唯一定义为真相。\n你所得见的即为世界的真实面貌。"
  },
  Stage_70931_Name = {Text = "真相"},
  Stage_70932_Desc = {
    Text = "你看呐，那圆润光泽的苹果多么诱人。\n轻轻咬上一口，摆脱一切烦恼吧。"
  },
  Stage_70932_Name = {
    Text = "有毒的苹果"
  },
  Stage_70933_Desc = {
    Text = "全部都和回忆里一样。"
  },
  Stage_70933_Name = {
    Text = "亲切的与勇敢的"
  },
  Stage_70934_Desc = {
    Text = "逝去的不会再回来。\n除非，是在另一个世界。"
  },
  Stage_70934_Name = {
    Text = "我们已经失去"
  },
  Stage_70935_Desc = {
    Text = "反拍，反拍，音符游走在预期的旋律节奏之外。"
  },
  Stage_70935_Name = {
    Text = "迷奏的音符"
  },
  Stage_70936_Desc = {
    Text = "逃脱一处陷阱，进入另一个更大的牢笼。"
  },
  Stage_70936_Name = {Text = "逃脱"},
  Stage_70937_Desc = {
    Text = "缸中之脑会梦见机械义体吗？"
  },
  Stage_70937_Name = {
    Text = "缸中之梦"
  },
  Stage_71748_Desc = {
    Text = "「嘘……你猜，我透过你的眼睛看见了什么？」\n在奥瑞塔被守密人吓哭以后，守密人房间的第四面墙差点被萝坦推倒，因为奥瑞塔哭得实在是太让人心慌了。"
  },
  Stage_71748_Name = {
    Text = "戏剧的第四壁·之七"
  },
  Stage_71748_StageInitStateText = {Text = "原初"},
  Stage_71749_Desc = {
    Text = "不要每时每刻都用内容轰炸观众的脑子，要给他们留下思考空间，最好是完全静止的——真希望朵尔在上课时能熟练运用这种技巧，守密人这么呢喃着，得到了所有人的认同。"
  },
  Stage_71749_Name = {
    Text = "静场时刻·之七"
  },
  Stage_71749_StageInitStateText = {Text = "原初"},
  Stage_71750_Desc = {
    Text = "在故事的结尾，需要体现角色的发展或者变化。可是在生活中，弧光往往会连成一个圆。"
  },
  Stage_71750_Name = {
    Text = "弧光理论·之七"
  },
  Stage_71750_StageInitStateText = {Text = "原初"},
  Stage_71751_Desc = {
    Text = "一个提前设定好的场景，几个互相熟识的演员。剩下的，就交给灵感与碰撞。"
  },
  Stage_71751_Name = {
    Text = "假面喜剧·之七"
  },
  Stage_71751_StageInitStateText = {Text = "原初"},
  Stage_71752_Desc = {
    Text = "这是一个连拉蒙娜都没有听过的词，在某些年迈唤醒体的帮助下，大家才终于明白：有时候，大哭一场才是处理坏情绪的唯一方法。"
  },
  Stage_71752_Name = {
    Text = "卡塔西斯·之七"
  },
  Stage_71752_StageInitStateText = {Text = "原初"},
  Stage_71753_Desc = {
    Text = "「不要让观众全身心沉浸在剧情中，要让他们分析、批判舞台上正在发生的事情。」\n对这条理论，奥瑞塔如此评价：奥瑞塔不想要被任何人骂！奥瑞塔只想和大家成为好朋友！"
  },
  Stage_71753_Name = {
    Text = "陌生化效果·之七"
  },
  Stage_71753_StageInitStateText = {Text = "原初"},
  Stage_71754_Desc = {
    Text = "急转直下，突发情节，故事突变——守密人感觉，这似乎在描述有时的自己。"
  },
  Stage_71754_Name = {
    Text = "情节轮转·之七"
  },
  Stage_71754_StageInitStateText = {Text = "原初"},
  Stage_71755_Desc = {
    Text = "卡茜亚找到的理论书中如此写道：故事发生的时间不能超过一天，舞台也不能超过一处……\n守密人听到这里时，就放弃了继续读下去。毕竟，一天的时间，有时还不够守密人完成一次「融蚀与灾厄处理」的课后作业论文。"
  },
  Stage_71755_Name = {
    Text = "三一律·之七"
  },
  Stage_71755_StageInitStateText = {Text = "原初"},
  Stage_71756_Desc = {
    Text = "在卡茜亚找到的理论书中写道：金字塔模型往往着眼于一场危机的解决。\n但是很可惜，不是每场危机都能在现实中得到解决。它们被和平假象所隐瞒、掩盖，在暗中滋生，最后爆发为新的「金字塔」。"
  },
  Stage_71756_Name = {
    Text = "剧作金字塔·之七"
  },
  Stage_71756_StageInitStateText = {Text = "原初"},
  Stage_71810_Desc = {
    Text = "她有很多身份：名媛、商人、掮客、收藏家……\n唯独没有她自己——很遗憾，蔷薇夫人从不为此失落。\n对她而言，原始的、未经雕琢的事物不值一提，复杂与浑浊才是最顶级的审美。"
  },
  Stage_71810_Name = {
    Text = "脸·之七"
  },
  Stage_71810_StageInitStateText = {Text = "繁育"},
  Stage_71811_Desc = {
    Text = "她的长腿叔叔和旁人不同：他是由雾做成的。\n鉴于女孩早已丢失对人类的信任，雾或者金子、符号做成的人都没有什么区别。\n当然，她终将为自己的错误判断付出代价——但那已经是很久以后的故事了。"
  },
  Stage_71811_Name = {
    Text = "长腿叔叔·之七"
  },
  Stage_71811_StageInitStateText = {Text = "繁育"},
  Stage_71812_Desc = {
    Text = "临行前，传记作家回望这栋蔷薇盛开的美丽宅邸，它远抵不上主人光芒的万分之一。\n有关索蕾尔夫人的传说还在继续，就在此刻的当下发生，我们都将成为见证。"
  },
  Stage_71812_Name = {
    Text = "终曲·之七"
  },
  Stage_71812_StageInitStateText = {Text = "繁育"},
  Stage_71813_Desc = {
    Text = "插花、刺绣、茶艺……她的生活由一串无意义的符号构成。\n「早安，索蕾尔小姐」「你真棒，索蕾尔小姐」……\n故作愉悦的声音就像厚厚的鱼缸，将她永远圈养。"
  },
  Stage_71813_Name = {
    Text = "釜底游鱼·之七"
  },
  Stage_71813_StageInitStateText = {Text = "繁育"},
  Stage_71814_Desc = {
    Text = "美貌是无形的线，轻松捆住人们的心。她随意地拨弄丝线，仿佛最漫不经心的天才。\n很快她便厌倦了这个游戏，因为透过他们丑陋的面容，她窥见自身。"
  },
  Stage_71814_Name = {
    Text = "傀儡游戏·之七"
  },
  Stage_71814_StageInitStateText = {Text = "繁育"},
  Stage_71815_Desc = {
    Text = "她在生日那天收到了一个礼物：一件精心缝制的白色罗裙。\n然后她被告知，自己将身着这件礼物，变成父母赠予他人的礼物。"
  },
  Stage_71815_Name = {
    Text = "礼物·之七"
  },
  Stage_71815_StageInitStateText = {Text = "繁育"},
  Stage_71816_Desc = {
    Text = "她像磁石一样紧紧吸引着周围人的目光。\n艳羡的、惊愕的、嫉恨的、贪婪的……唯独没有平静，一如她今后的命运。"
  },
  Stage_71816_Name = {
    Text = "目光·之七"
  },
  Stage_71816_StageInitStateText = {Text = "繁育"},
  Stage_71817_Desc = {
    Text = "那天晚上，她梦见了黑雾，梦见它有了生气，在颤动。\n不是虎和马的、难以形容的杂种，而兼有那两种动物的性质。\n同时又是一只黑猫、一朵蔷薇、一场暴风雨。"
  },
  Stage_71817_Name = {
    Text = "蔷薇角·之七"
  },
  Stage_71817_StageInitStateText = {Text = "繁育"},
  Stage_71818_Desc = {
    Text = "她将按照剧本的指示，演完一场场剧目，掀起无尽的混乱。\n而她，便是在风暴眼中翩翩起飞的舞者。\n她一向都是最敬业的演员。"
  },
  Stage_71818_Name = {
    Text = "未完的剧本·之七"
  },
  Stage_71818_StageInitStateText = {Text = "繁育"},
  Stage_71852_Desc = {
    Text = "他端坐于高高的青石王座，独享着永恒的崇高与孤独。"
  },
  Stage_71852_Name = {Text = "王座"},
  Stage_71853_Desc = {
    Text = "我将亲手为我戴上，那无限的力量与荣光。"
  },
  Stage_71853_Name = {Text = "加冕"},
  Stage_71854_Desc = {
    Text = "除了祈祷神明带来奇迹，渺小的人类别无选择。"
  },
  Stage_71854_Name = {Text = "天灾"},
  Stage_71855_Desc = {
    Text = "那顶王冠的重量，早早地便压在了那群孩子们的身上。"
  },
  Stage_71855_Name = {Text = "童年"},
  Stage_71923_Desc = {
    Text = "黑暗自深渊涌现，闯入者于紧攥心脏的恐惧中挣扎，在被黑暗吞没之前。"
  },
  Stage_71923_Name = {
    Text = "融灾禁区·第2波·V级警报"
  },
  Stage_71924_Desc = {
    Text = "黑暗自深渊涌现，闯入者于紧攥心脏的恐惧中挣扎，在被黑暗吞没之前。"
