  },
  Stage_71931_Desc = {
    Text = "黑暗自深渊涌现，闯入者于紧攥心脏的恐惧中挣扎，在被黑暗吞没之前。"
  },
  Stage_71931_Name = {
    Text = "融灾禁区·第3波·V级警报"
  },
  Stage_71932_Desc = {
    Text = "黑暗自深渊涌现，闯入者于紧攥心脏的恐惧中挣扎，在被黑暗吞没之前。"
  },
  Stage_71932_Name = {
    Text = "融灾禁区·第2波·V级警报"
  },
  Stage_72063_Desc = {
    Text = "眼睛，我不敢在梦中相遇\n在死亡的梦幻国土"
  },
  Stage_72063_Name = {Text = "空心人"},
  Stage_72064_Desc = {
    Text = "人类将唯一定义为真相。\n你所得见的即为世界的真实面貌。"
  },
  Stage_72064_Name = {Text = "真相"},
  Stage_72065_Desc = {
    Text = "你看呐，那圆润光泽的苹果多么诱人。\n轻轻咬上一口，摆脱一切烦恼吧。"
  },
  Stage_72065_Name = {
    Text = "有毒的苹果"
  },
  Stage_72066_Desc = {
    Text = "全部都和回忆里一样。"
  },
  Stage_72066_Name = {
    Text = "亲切的与勇敢的"
  },
  Stage_72067_Desc = {
    Text = "逝去的不会再回来。\n除非，是在另一个世界。"
  },
  Stage_72067_Name = {
    Text = "我们已经失去"
  },
  Stage_72068_Desc = {
    Text = "反拍，反拍，音符游走在预期的旋律节奏之外。"
  },
  Stage_72068_Name = {
    Text = "迷奏的音符"
  },
  Stage_72069_Desc = {
    Text = "逃脱一处陷阱，进入另一个更大的牢笼。"
  },
  Stage_72069_Name = {Text = "逃脱"},
  Stage_72070_Desc = {
    Text = "亲爱的，让我们去看看末日。\n与其在绝望中日益衰朽，不如趁着命运尚未降临，亲手建树终末的伟业。"
  },
  Stage_72070_Name = {
    Text = "未选择的路"
  },
  Stage_72071_Desc = {
    Text = "数字从来并非名称，只是符号。\n凡庸的生命不愿割舍自身虚构的独特性，故而抗拒以数字作为自己的代称。\n她从不在意。"
  },
  Stage_72071_Name = {Text = "B-68"},
  Stage_72072_Desc = {
    Text = "咕噜，咕噜，咕噜。器官发出迫切渴求的悲呼。\n不是肚中饥鸣，它的空虚源自大脑。"
  },
  Stage_72072_Name = {
    Text = "人间食粮"
  },
  Stage_74229_Desc = {
    Text = "你与那一抹飞扬的裙摆不期而遇，那旋转的舞裙多么像天鹅翻飞的翅膀，又多么像一朵燃烧的火焰。"
  },
  Stage_74229_Name = {
    Text = "不期而遇的火焰"
  },
  Stage_74230_Desc = {
    Text = "这里不该是艺术的殿堂吗？否则怎会有那许多令人目眩的优雅舞姿。\n但这里真是艺术的殿堂吗？不然又为何充满那样多冰冷油腻的视线？"
  },
  Stage_74230_Name = {
    Text = "燃烧的坚冰"
  },
  Stage_74231_Desc = {
    Text = "梦中的天鹅高高飞起，又于猎人的捕网中狠狠摔落在地。"
  },
  Stage_74231_Name = {
    Text = "仲夏夜之梦"
  },
  Stage_74232_Desc = {
    Text = "青色的舞者在舞台上起舞。\n青色的烈焰在火焰中燃烧。\n为慨然赴死的天鹅，敬献最后的挽歌。"
  },
  Stage_74232_Name = {
    Text = "天鹅挽歌"
  },
  Stage_74242_Desc = {
    Text = "青色的舞者在舞台上起舞。\n青色的烈焰在火焰中燃烧。\n为慨然赴死的天鹅，敬献最后的挽歌。"
  },
  Stage_74242_Name = {
    Text = "天鹅挽歌"
  },
  Stage_74243_Desc = {
    Text = "青色的舞者在舞台上起舞。\n青色的烈焰在火焰中燃烧。\n为慨然赴死的天鹅，敬献最后的挽歌。"
  },
  Stage_74243_Name = {
    Text = "天鹅挽歌"
  },
  Stage_74328_Desc = {
    Text = "条件已经就绪，热血正在沸腾，现在，决斗开始。"
  },
  Stage_74328_Name = {
    Text = "贯彻意志的决斗"
  },
  Stage_74329_Desc = {
    Text = "即使身处绝境，也不要放弃希望。因为每个瞬间，都有可能成为逆转一切的开始。"
  },
  Stage_74329_Name = {
    Text = "逆转万象的瞬间"
  },
  Stage_74330_Desc = {
    Text = "一场意外让相位对弈空间迎来了一位特殊来客。为了夺回对弈空间，你踏上了成为最强卡牌大师的旅途。"
  },
  Stage_74330_Name = {
    Text = "来自异界的客人"
  },
  Stage_74975_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_74975_Name = {
    Text = "幻梦深潜Ⅵ"
  },
  Stage_74976_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_74976_Name = {
    Text = "幻梦深潜·癫狂"
  },
  Stage_74977_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_74977_Name = {
    Text = "幻梦深潜·癫狂"
  },
  Stage_74978_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_74978_Name = {
    Text = "幻梦深潜·癫狂"
  },
  Stage_74979_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_74979_Name = {
    Text = "幻梦深潜Ⅱ"
  },
  Stage_74980_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_74980_Name = {
    Text = "幻梦深潜Ⅱ"
  },
  Stage_74981_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_74981_Name = {
    Text = "幻梦深潜Ⅶ"
  },
  Stage_74982_Desc = {
    Text = "此处埋葬着一所大学，千疮百孔，疲惫不堪\n它曾为人类存续奉献了一点希望与勇气\n至于结果如何，你现在都看到了"
  },
  Stage_74982_Name = {
    Text = "幻梦深潜·癫狂"
  },
  Stage_74983_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
