  },
  Stage_74984_Name = {
    Text = "幻梦深潜·癫狂"
  },
  Stage_74985_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_74985_Name = {
    Text = "幻梦深潜Ⅳ"
  },
  Stage_74986_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_74986_Name = {
    Text = "幻梦深潜·癫狂"
