    Text = "幻梦深潜·癫狂"
  },
  Stage_75050_Desc = {
    Text = "此处埋葬着一所大学，千疮百孔，疲惫不堪\n它曾为人类存续奉献了一点希望与勇气\n至于结果如何，你现在都看到了"
  },
  Stage_75050_Name = {
    Text = "幻梦深潜Ⅴ"
  },
  Stage_75051_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_75051_Name = {
    Text = "幻梦深潜·癫狂"
  },
  Stage_75052_Desc = {
    Text = "「每把钥匙都有唯一的编号，只对应唯一的调查员。」\n「因此，每把钥匙的陨落也对应着唯一的调查员之死。」\n「真好啊。就连死亡都是独一无二的。」"
  },
  Stage_75052_Name = {
    Text = "幻梦深潜·癫狂"
  },
  Stage_75053_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
