  Stage_75762_Name = {
    Text = "沼泽恶鬼·之二"
  },
  Stage_75763_Desc = {
    Text = "它早已忘记了自己的名字，连与她初次相逢那天的记忆都已开始模糊。\n唯有那双手，那双轻轻牵起它的手，始终温暖着它野蛮而孤独的灵魂。\n于是它从她的手中接过那美丽的头颅，自愿套上那永恒的面具与枷锁。"
  },
  Stage_75763_Name = {
    Text = "它与她·之六"
  },
