  Stage_75777_Name = {
    Text = "归于灰海·之四"
  },
  Stage_7635_Desc = {
    Text = "它们像捉摸不定的魔法师，游走在时空的夹缝里。\n没有仇恨，没有恐惧，也没有怜悯。"
  },
  Stage_7635_Name = {
    Text = "维度残像Ⅱ"
  },
  Stage_7636_Desc = {
    Text = "她以己身承纳圣骸，以教义训导眷众，以毒牙布散信仰。"
  },
  Stage_7636_Name = {
    Text = "虔诚之握Ⅲ"
  },
  Stage_7637_Desc = {
    Text = "早在群星诞生之前，它们便存在于此。\n它们既是虚无，也是一切。"
  },
  Stage_7637_Name = {
    Text = "浑浊残像Ⅴ"
  },
  Stage_7638_Desc = {
    Text = "它们无言地守护着海洋的秘密，灵魂和宇宙一样深沉。"
  },
  Stage_7638_Name = {
    Text = "海渊残像Ⅴ"
  },
  Stage_76399_Desc = {
    Text = "黑暗自深渊涌现，闯入者于紧攥心脏的恐惧中挣扎，在被黑暗吞没之前。"
  },
  Stage_76399_Name = {
    Text = "融灾禁区·第4波·V级警报"
  },
  Stage_7639_Desc = {
    Text = "它们在黑暗中扭曲、融合，然后被小心翼翼地保管在造像里。\n这是一次蓄谋已久的重逢。"
  },
