  Stage_7647_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_7647_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_7648_Desc = {
    Text = "它一刻不停地追逐那些打破规则的僭越者。\n至于何为「规则」，何为「打破」？\n猎犬从不思考——那只会阻碍它奔袭的速度。"
  },
  Stage_7648_Name = {
    Text = "界外之影Ⅲ"
  },
  Stage_7649_Desc = {
    Text = "伦蒂尼恩以灿烂的工业文明，以及笼罩市区的铅灰色浓雾闻名。\n雾气无处不在，对路人来说是更像是一种偶然、无意义的不便。"
  },
  Stage_7649_Name = {
    Text = "怪雾之都Ⅱ"
  },
  Stage_7650_Desc = {
    Text = "来历不明的造像在黑暗中游荡、战栗。\n它们踏着古老的节拍，循着来自远方的笛声起舞。"
  },
  Stage_7650_Name = {
    Text = "血肉之沼·间隙Ⅶ"
  },
  Stage_7651_Desc = {
    Text = "一堆粗鲁的、未消化的物质。人们称其为排泄物，或是混沌。 \n世界从排泄物中诞生。"
  },
  Stage_7651_Name = {
    Text = "混沌集群Ⅴ"
  },
  Stage_7652_Desc = {
    Text = "蠕动着、流淌着……原生质的肿泡正从枷锁的缝隙中溜走。\n这是她为「自由」付出的代价。"
  },
  Stage_7652_Name = {
    Text = "漆黑之链Ⅲ"
  },
  Stage_7653_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7653_Name = {
    Text = "超维之旅·轮转间隙Ⅰ"
  },
  Stage_7654_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7654_Name = {
    Text = "超维之旅·轮转间隙Ⅰ"
  },
  Stage_7655_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7655_Name = {
    Text = "超维之旅·轮转间隙Ⅰ"
  },
  Stage_7656_Desc = {
    Text = "它以乖巧的姿态靠在床沿，暗淡的纽扣眼睛望着虚空。\n小小的身躯承受了主人的全部眼泪，却无法出言安慰。"
  },
  Stage_7656_Name = {
    Text = "玩偶之泪Ⅴ"
  },
  Stage_7657_Desc = {
    Text = "它们原本是悲伤、扭曲和懵懂组成的无意识集合，\n却被打扮成幸福的小孩、大人和宠物。\n因着从未品尝过幸福的滋味，它们成了最糟糕的演员。"
  },
  Stage_7657_Name = {
    Text = "蜡像之秘Ⅴ"
  },
  Stage_7658_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_7658_Name = {
    Text = "混沌之域·间隙Ⅳ"
  },
  Stage_7659_Desc = {
    Text = "风雨仍在酝酿，一切尚未终结。"
  },
  Stage_7659_Name = {
    Text = "现实重启"
  },
  Stage_7660_Desc = {
    Text = "没有华丽的布景，也没有动人的女主角。\n——这是一场由三个男人演出的乏味剧目。"
  },
  Stage_7660_Name = {
    Text = "向导，巫师和奴隶"
  },
  Stage_7661_Desc = {
    Text = "迎着风与黄沙，战士义无反顾地奔向太阳。"
  },
  Stage_7661_Name = {
    Text = "太阳远征"
  },
  Stage_7662_Desc = {
    Text = "朋友们，停下打闹和纷争吧。\n祭祀的火焰已经升起，请享受这死亡前最后的宁静……"
  },
  Stage_7662_Name = {Text = "红祭礼"},
  Stage_7663_Desc = {
    Text = "严格意义来讲，这并非一出悲剧。\n战士的字典里没有「悲剧」。"
  },
  Stage_7663_Name = {
    Text = "悲剧的谢幕"
  },
  Stage_7664_Desc = {
    Text = "驶向陆地，驶向一线生机。"
  },
  Stage_7664_Name = {
    Text = "悲剧的起航"
  },
  Stage_7665_Desc = {
    Text = "潜藏在宇宙深处的弯曲视界。 \n它能带你从黑暗抵达另一处黑暗。"
  },
  Stage_7665_Name = {
    Text = "史瓦西喉Ⅲ"
  },
  Stage_7666_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7666_Name = {
    Text = "深海之遗·间隙Ⅲ"
  },
  Stage_7667_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_7667_Name = {
    Text = "幻梦深潜Ⅵ"
  },
  Stage_7668_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_7668_Name = {
    Text = "幻梦深潜Ⅶ"
  },
