  },
  Stage_7672_Name = {
    Text = "幻梦深潜Ⅲ"
  },
  Stage_7673_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_7673_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_7674_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_7674_Name = {
    Text = "幻梦深潜Ⅲ"
  },
  Stage_7675_Desc = {
    Text = "位于北约克郡的海边小镇——斯卡伯勒。这里拥有高耸的悬崖与金色的海湾，是一处优雅迷人的度假胜地。"
  },
  Stage_7675_Name = {
    Text = "斯卡伯勒之夏"
  },
  Stage_7676_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_7676_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_7677_Desc = {
    Text = "一只小老鼠，一只小老鼠。\n跑啊，跑啊，她用切肉刀割掉它的尾巴。"
  },
  Stage_7677_Name = {
    Text = "布朗出击"
  },
  Stage_7678_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_7678_Name = {
    Text = "幻梦深潜Ⅶ"
  },
  Stage_7679_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_7679_Name = {
    Text = "幻梦深潜Ⅵ"
  },
  Stage_7680_Desc = {
    Text = "噢，手臂，恼人的手臂！它们总是揪着我的头发不放。"
  },
  Stage_7680_Name = {Text = "二十四"},
  Stage_7681_Desc = {
    Text = "吧唧咕叽，裂开了。\n吧唧咕叽，断掉了。"
  },
  Stage_7681_Name = {Text = "娃娃馆"},
  Stage_7682_Desc = {
    Text = "没错，宝贝。尽情地哭吧，把你的痛苦当作绝世名作一样装裱起来。"
  },
  Stage_7682_Name = {
    Text = "少女和眼泪"
  },
  Stage_7683_Desc = {
    Text = "是的，是的。眼睛是心灵的牢笼，灵魂是禁锢肉身的枷锁。"
  },
  Stage_7683_Name = {
    Text = "解剖的忧郁"
  },
  Stage_7684_Desc = {
    Text = "甜蜜的，香醇的，孩子们的挚爱。\n高雅的，超脱的，成年人的向往。"
  },
  Stage_7684_Name = {
    Text = "甜蜜的艺术"
  },
  Stage_76854_Desc = {
    Text = "不可见的灾难复苏，物理世界的历史与存在正在坠入深渊。"
  },
  Stage_76854_Name = {
    Text = "融灾禁区·第1波·Ⅳ级警报"
  },
  Stage_76855_Desc = {
