    Text = "不可见的灾难复苏，物理世界的历史与存在正在坠入深渊。"
  },
  Stage_77088_Name = {
    Text = "融灾禁区·第2波·Ⅳ级警报"
  },
  Stage_77089_Desc = {
    Text = "漆黑的潮水漫过警戒界限，轻微的波动亦昭示着足以吞噬掉以轻心者的险恶。"
  },
  Stage_77089_Name = {
    Text = "融灾禁区·第2波·Ⅰ级警报"
  },
  Stage_7708_Desc = {
    Text = "不要回头！多么贵重的叮嘱，别再步俄耳甫斯的后尘。"
  },
  Stage_7708_Name = {
    Text = "不要回头"
  },
