  },
  Stage_7709_Desc = {
    Text = "皑皑雪原，百合繁盛。"
  },
  Stage_7709_Name = {Text = "28天"},
  Stage_77100_Desc = {
    Text = "黑暗自深渊涌现，闯入者于紧攥心脏的恐惧中挣扎，在被黑暗吞没之前。"
  },
  Stage_77100_Name = {
