  },
  Stage_77101_Desc = {
    Text = "黑暗自深渊涌现，闯入者于紧攥心脏的恐惧中挣扎，在被黑暗吞没之前。"
  },
  Stage_77101_Name = {
    Text = "融灾禁区·第4波·V级警报"
  },
  Stage_77102_Desc = {
    Text = "旧日灾厄于此刻苏生，跨越现世的界碑，引燃堕落的汪洋。"
  },
  Stage_77102_Name = {
    Text = "融灾禁区·第4波·Ⅲ级警报"
  },
  Stage_77103_Desc = {
    Text = "旧日灾厄于此刻苏生，跨越现世的界碑，引燃堕落的汪洋。"
  },
  Stage_77103_Name = {
    Text = "融灾禁区·第5波·Ⅲ级警报"
  },
  Stage_7710_Desc = {
    Text = "日记是记忆的碎片。\n调查中总是会发现日记的。"
  },
  Stage_7710_Name = {
    Text = "记忆碎片"
  },
  Stage_7711_Desc = {
    Text = "这是一方为她开辟的天地，是伟大的爱意与可怖的囚笼。"
  },
  Stage_7711_Name = {
    Text = "精神病院"
  },
  Stage_7712_Desc = {
    Text = "当勋贵们痛失权柄，当豪富们倾家荡产，他们寸步难行，就像你现在这样。"
  },
  Stage_7712_Name = {
    Text = "飞越疯人院"
  },
  Stage_7713_Desc = {
    Text = "世间的交锋不止于兵刃相接的战场，有时也存在于疯人之口。"
  },
  Stage_7713_Name = {
    Text = "疯人之口"
  },
  Stage_7714_Desc = {
    Text = "缠绕在迷雾中的轨迹，无数脚步在其上徘徊，每一个踏点都是对命运的追问。"
  },
  Stage_7714_Name = {
    Text = "前路迷途"
  },
  Stage_7715_Desc = {
    Text = "寂静燃烧的火焰，向旅人许下虚妄的诺言。"
  },
  Stage_7715_Name = {
    Text = "诱蛾之火"
  },
  Stage_7716_Desc = {
    Text = "献上血肉铸就的现实吧，它们是永不餍足的深渊。"
  },
  Stage_7716_Name = {
    Text = "器质残像Ⅴ"
  },
  Stage_7717_Desc = {
    Text = "风雨仍在酝酿，一切尚未终结。"
  },
  Stage_7717_Name = {
    Text = "现实重启"
  },
  Stage_7718_Desc = {
    Text = "驶向陆地，驶向一线生机。"
  },
  Stage_7718_Name = {
    Text = "悲剧的起航"
  },
  Stage_7719_Desc = {
    Text = "那绝非受到期待的生命，只是污浊的寄生虫罢了。"
  },
  Stage_7719_Name = {Text = "寄生物"},
  Stage_7720_Desc = {
    Text = "在无尽夜幕的漆黑中追逐着那诱人的光明，犹如一只逐火之蛾，不顾一切地向着命运的焰火翱翔。"
  },
  Stage_7720_Name = {
    Text = "逐火之蛾"
  },
  Stage_7721_Desc = {
    Text = "夜色被暗流侵蚀，星辰失声。潜藏着转折与风雨的危机之月，静默映照着未知的未来。"
  },
  Stage_7721_Name = {
    Text = "危机之月"
  },
  Stage_7722_Desc = {
    Text = "在命运的狂风中颤抖、挣扎，但它不会真正地飘零。"
  },
  Stage_7722_Name = {
    Text = "摇摇欲坠"
  },
  Stage_7723_Desc = {
    Text = "在过往岁月中飘摇的友谊，结下了新的希望。"
  },
  Stage_7723_Name = {
    Text = "旧友新朋"
  },
  Stage_7724_Desc = {
    Text = "祂的国度是宇宙躯壳，祂的欲望无边无际。"
  },
  Stage_7724_Name = {
    Text = "蠕虫之所Ⅲ"
  },
  Stage_7725_Desc = {
    Text = "献上血肉铸就的现实吧，它们是永不餍足的深渊。"
  },
  Stage_7725_Name = {
    Text = "器质残像Ⅱ"
  },
  Stage_7726_Desc = {
    Text = "它们原本是悲伤、扭曲和懵懂组成的无意识集合，\n却被打扮成幸福的小孩、大人和宠物。\n因着从未品尝过幸福的滋味，它们成了最糟糕的演员。"
  },
  Stage_7726_Name = {
    Text = "蜡像之秘Ⅰ"
  },
  Stage_7727_Desc = {
    Text = "它以乖巧的姿态靠在床沿，暗淡的纽扣眼睛望着虚空。\n小小的身躯承受了主人的全部眼泪，却无法出言安慰。"
  },
  Stage_7727_Name = {
    Text = "玩偶之泪Ⅰ"
  },
  Stage_7728_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_7728_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_7729_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
