  },
  Stage_7740_Name = {
    Text = "幻梦深潜Ⅳ"
  },
  Stage_7741_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_7741_Name = {
    Text = "幻梦深潜Ⅴ"
  },
  Stage_7742_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_7742_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_7743_Desc = {
    Text = "早在群星诞生之前，它们便存在于此。\n它们既是虚无，也是一切。"
  },
  Stage_7743_Name = {
    Text = "浑浊残像Ⅰ"
  },
  Stage_7744_Desc = {
    Text = "它们在黑暗中扭曲、融合，然后被小心翼翼地保管在造像里。\n这是一次蓄谋已久的重逢。"
  },
  Stage_7744_Name = {
    Text = "深海之遗·间隙Ⅰ"
  },
  Stage_7745_Desc = {
    Text = "她以己身承纳圣骸，以教义训导眷众，以毒牙布散信仰。"
  },
  Stage_7745_Name = {
    Text = "虔诚之握Ⅰ"
  },
  Stage_7746_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_7746_Name = {
    Text = "深海之遗·间隙Ⅳ"
  },
  Stage_7747_Desc = {
    Text = "拉伊小镇位于伦蒂尼恩东北部，隐没在绵延的山脉中。\n沉默的乡民、无处不在的视线……当心，这里的一切都不太寻常。"
  },
  Stage_7747_Name = {
    Text = "错乱异镇Ⅰ"
  },
  Stage_7748_Desc = {
    Text = "哦，地下水道！你是城市的良心，你是城市的收容所。"
  },
  Stage_7748_Name = {
    Text = "地下水道"
  },
  Stage_7749_Desc = {
    Text = "是的，是的。眼睛是心灵的牢笼，灵魂是禁锢肉身的枷锁。"
  },
  Stage_7749_Name = {
    Text = "解剖的忧郁"
  },
  Stage_7750_Desc = {
    Text = "虚无乃吾等之源头，亦为吾等之归宿。"
  },
  Stage_7750_Name = {
    Text = "不朽的低语"
  },
  Stage_7751_Desc = {
    Text = "没错，宝贝。尽情地哭吧，把你的痛苦当作绝世名作一样装裱起来。"
  },
  Stage_7751_Name = {
    Text = "少女和眼泪"
  },
  Stage_7752_Desc = {
    Text = "它一刻不停地追逐那些打破规则的僭越者。\n至于何为「规则」，何为「打破」？\n猎犬从不思考——那只会阻碍它奔袭的速度。"
  },
  Stage_7752_Name = {
    Text = "界外之影Ⅱ"
  },
  Stage_7753_Desc = {
    Text = "真实，这残酷的真实。"
  },
  Stage_7753_Name = {
    Text = "面纱之下"
  },
  Stage_7754_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7754_Name = {
    Text = "血肉之沼·轮转间隙Ⅱ"
  },
  Stage_7755_Desc = {
    Text = "后来，勇士回到故乡，娶了公主为妻，过上了幸福平静的生活。\n真的吗？假的。"
  },
  Stage_7755_Name = {Text = "后记"},
  Stage_7756_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7756_Name = {
    Text = "血肉之沼·轮转间隙Ⅰ"
  },
  Stage_7757_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7757_Name = {
    Text = "血肉之沼·轮转间隙Ⅰ"
  },
  Stage_7758_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7758_Name = {
    Text = "血肉之沼·轮转间隙Ⅰ"
  },
  Stage_7759_Desc = {
    Text = "当雨幕落下，鲜血涌出，我们迎来再度相聚的时刻。\n好久不见，守密人。"
  },
  Stage_7759_Name = {
    Text = "不期而遇"
  },
  Stage_7760_Desc = {
    Text = "荒芜的铁路桥下，庞大臃肿的怪物发出古怪的低吼。要抵达拉伊疯人院，就必须跨过这里。"
  },
  Stage_7760_Name = {
    Text = "船到桥头自然直"
  },
  Stage_7761_Desc = {
    Text = "成为天才药理师的第一步。"
  },
  Stage_7761_Name = {
    Text = "制剂淬炼Ⅳ"
  },
  Stage_7762_Desc = {
    Text = "成为天才药理师的第一步。"
  },
  Stage_7762_Name = {
    Text = "制剂淬炼Ⅴ"
  },
  Stage_7763_Desc = {
    Text = "成为天才药理师的第一步。"
  },
  Stage_7763_Name = {
    Text = "制剂淬炼Ⅱ"
  },
  Stage_7764_Desc = {
    Text = "成为天才药理师的第一步。"
  },
  Stage_7764_Name = {
