  },
  Stage_7765_Desc = {
    Text = "成为天才药理师的第一步。"
  },
  Stage_7765_Name = {
    Text = "制剂淬炼Ⅰ"
  },
  Stage_7766_Desc = {Text = "随机2"},
  Stage_7766_Name = {
    Text = "月沼之镜Ⅱ"
  },
