    Text = "阿拉克涅试玩关卡"
  },
  Stage_7798_Desc = {
    Text = "它以乖巧的姿态靠在床沿，暗淡的纽扣眼睛望着虚空。\n小小的身躯承受了主人的全部眼泪，却无法出言安慰。"
