  },
  Stage_77999_Name = {
    Text = "卡拉布试玩关卡"
  },
  Stage_7799_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
