  Stage_7813_Name = {
    Text = "幻梦深潜Ⅵ"
  },
  Stage_7814_Desc = {
    Text = "那是意图斩破海洋之人的巨刃，是意图踏平诸海之人的野心。"
  },
  Stage_7814_Name = {
    Text = "狂徒与巨刃"
  },
  Stage_7815_Desc = {
    Text = "现实埋下了祸种，命运却指引着相遇。"
  },
  Stage_7815_Name = {
    Text = "命运的种子"
  },
  Stage_7816_Desc = {
    Text = "跨越诸海之使徒。"
  },
  Stage_7816_Name = {Text = "使徒"},
  Stage_7817_Desc = {
    Text = "在一艘船上，除了船长，还有谁是值得相信的呢？"
  },
  Stage_7817_Name = {Text = "船员"},
  Stage_7818_Desc = {
    Text = "退无可退之时，训练有素的伙伴往往是破局的关键——拉蒙娜再次教会了你这点。"
  },
  Stage_7818_Name = {
    Text = "无路可逃"
  },
  Stage_7819_Desc = {
    Text = "踏破诸海而过的，除了敌人，或许还有希望的微光。"
  },
  Stage_7819_Name = {
    Text = "沉溺之徒"
  },
  Stage_7820_Desc = {
    Text = "夜晚的港口，淳朴的居民，热情的款待。"
  },
  Stage_7820_Name = {
    Text = "十面埋伏"
  },
  Stage_7821_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7821_Name = {
    Text = "深海之遗·轮转间隙Ⅱ"
  },
  Stage_7822_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7822_Name = {
    Text = "深海之遗·轮转间隙Ⅱ"
  },
  Stage_7823_Desc = {
