  },
  Stage_7823_Name = {
    Text = "深海之遗·轮转间隙Ⅱ"
  },
  Stage_7824_Desc = {
    Text = "第二颗心脏在墨菲体内跳动着，阻止「降生仪式」迫在眉睫。"
  },
  Stage_7824_Name = {
    Text = "另一个奇迹"
  },
  Stage_7825_Desc = {
    Text = "突出重围永远不简单，但好在，这一次守密人找到了最亮的恒星。"
  },
  Stage_7825_Name = {
    Text = "追逐繁星"
  },
  Stage_7826_Desc = {
    Text = "罗杰斯蜡像馆坐落在南华克街的最深处，靠近泰姆河的支流。\n它毫不起眼，却有众多先锋艺术爱好者慕名而来。"
  },
  Stage_7826_Name = {
    Text = "狂躁蜡馆Ⅰ"
  },
  Stage_7827_Desc = {
    Text = "他不会是祂，祂不可能是他。\n没错……没错，只有我的神明，才是真正的他。"
  },
  Stage_7827_Name = {
    Text = "失落之光"
  },
