  },
  Stage_7830_Name = {
    Text = "幻梦深潜Ⅴ"
  },
  Stage_7831_Desc = {
    Text = "此处埋葬着一所大学，千疮百孔，疲惫不堪\n它曾为人类存续奉献了一点希望与勇气\n至于结果如何，你现在都看到了"
  },
  Stage_7831_Name = {
    Text = "幻梦深潜Ⅱ"
  },
  Stage_7832_Desc = {
    Text = "此处埋葬着一所大学，千疮百孔，疲惫不堪\n它曾为人类存续奉献了一点希望与勇气\n至于结果如何，你现在都看到了"
  },
  Stage_7832_Name = {
    Text = "幻梦深潜Ⅲ"
  },
  Stage_7833_Desc = {
    Text = "此处埋葬着一所大学，千疮百孔，疲惫不堪\n它曾为人类存续奉献了一点希望与勇气\n至于结果如何，你现在都看到了"
  },
  Stage_7833_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_7834_Desc = {
    Text = "这里肆虐的并非普通疾病。"
  },
  Stage_7834_Name = {Text = "病"},
  Stage_7835_Desc = {
    Text = "在笼罩济贫院的浓厚迷雾之中，触碰切割、消失与死亡。"
  },
  Stage_7835_Name = {
    Text = "谁杀死了知更鸟"
  },
  Stage_7836_Desc = {
    Text = "祂的国度是宇宙躯壳，祂的欲望无边无际。"
  },
  Stage_7836_Name = {
    Text = "蠕虫之所Ⅴ"
  },
  Stage_7837_Desc = {
    Text = "你与拉蒙娜前往伦蒂尼恩东区的莉莉安济贫院，展开你作为新晋守密人的第一次调查。\n一切都会很顺利，对吧？"
  },
  Stage_7837_Name = {
    Text = "人不可貌相"
  },
  Stage_7838_Desc = {
    Text = "甜蜜的，香醇的，孩子们的挚爱。\n高雅的，超脱的，成年人的向往。"
  },
  Stage_7838_Name = {
    Text = "甜蜜的艺术"
  },
  Stage_7839_Desc = {
    Text = "良心的负重，和誓言等同。"
  },
  Stage_7839_Name = {
    Text = "良心之重"
  },
  Stage_7840_Desc = {
    Text = "危险来自内部。"
  },
  Stage_7840_Name = {
    Text = "内在的危险"
  },
  Stage_7841_Desc = {
    Text = "我多想永远不用长大，每一天都和你这样看星星。\n我多想快一点快一点长大，就能保护你们所有人。"
  },
  Stage_7841_Name = {
    Text = "我们的秘密"
  },
  Stage_7842_Desc = {
    Text = "剪断木偶身上的细线，她就再也不会舞蹈。"
  },
  Stage_7842_Name = {
    Text = "飞鸟不在的夜"
  },
  Stage_7843_Desc = {
    Text = "你想要知道的一切，就在你的眼前，只是你从未发现。"
  },
  Stage_7843_Name = {
    Text = "藏于帽檐下"
  },
  Stage_7844_Desc = {
    Text = "拉蒙娜回归了队伍。弥萨格调查员的旅程继续。"
  },
  Stage_7844_Name = {
    Text = "昨日重现"
  },
  Stage_7845_Desc = {
    Text = "人类的腿脚无法胜过敏捷的四足野生生物，但头脑可以。只是，在捕获“地狱犬”之后，等待着你们的又是什么呢？"
  },
  Stage_7845_Name = {
    Text = "袖中王牌"
  },
  Stage_7846_Desc = {
    Text = "祝您旅途愉快。"
  },
  Stage_7846_Name = {
    Text = "旅途愉快"
  },
  Stage_7847_Desc = {
    Text = "在地铁内，你们遭到了神秘刺客的袭击……"
  },
  Stage_7847_Name = {
    Text = "人生无友"
  },
  Stage_7848_Desc = {
    Text = "与达芙黛尔夫人的往来，永远是由交易构成的。达芙黛尔出现，向你们提出了交易，而神秘的袭击者是否会认可这一交易呢？"
  },
  Stage_7848_Name = {
    Text = "公平交易"
  },
  Stage_7849_Desc = {
    Text = "追溯地狱犬“刻耳柏洛斯”的流言，弥萨格的调查员们来到伦蒂尼恩远郊的小镇拉伊，探寻失踪案背后的隐秘……"
  },
  Stage_7849_Name = {
    Text = "三思而后行"
  },
  Stage_7850_Desc = {
    Text = "一个好消息，一个坏消息。消失的线索不会重现，但新的案件已在暗中酝酿。相信吧，调查员不会再两手空空。"
  },
  Stage_7850_Name = {
    Text = "好消息，坏消息"
  },
  Stage_7851_Desc = {
    Text = "癫狂的语调，浓烈的腥气，这就是来自拉伊的欢迎仪式。"
  },
  Stage_7851_Name = {
    Text = "欢迎来到拉伊"
  },
  Stage_7852_Desc = {
    Text = "它以乖巧的姿态靠在床沿，暗淡的纽扣眼睛望着虚空。\n小小的身躯承受了主人的全部眼泪，却无法出言安慰。"
  },
  Stage_7852_Name = {
    Text = "玩偶之泪Ⅲ"
  },
  Stage_7855_Desc = {
    Text = "他不会是祂，祂不可能是他。\n没错……没错，只有我的神明，才是真正的他。"
  },
  Stage_7855_Name = {
    Text = "失落之光"
  },
  Stage_7856_Desc = {
    Text = "早在群星诞生之前，它们便存在于此。\n它们既是虚无，也是一切。"
  },
  Stage_7856_Name = {
    Text = "浑浊残像Ⅳ"
  },
  Stage_7857_Desc = {
    Text = "它们无言地守护着海洋的秘密，灵魂和宇宙一样深沉。"
  },
  Stage_7857_Name = {
    Text = "海渊残像Ⅱ"
  },
  Stage_7858_Desc = {
    Text = "怎会有永恒不落的夕阳？"
  },
  Stage_7858_Name = {Text = "日落"},
  Stage_7859_Desc = {
    Text = "当雨幕落下，鲜血涌出，我们迎来再度相聚的时刻。\n好久不见，守密人。"
  },
  Stage_7859_Name = {
    Text = "不期而遇"
  },
  Stage_7860_Desc = {
    Text = "它们像捉摸不定的魔法师，游走在时空的夹缝里。\n没有仇恨，没有恐惧，也没有怜悯。"
  },
  Stage_7860_Name = {
    Text = "维度残像Ⅰ"
  },
  Stage_7861_Desc = {
    Text = "它一刻不停地追逐那些打破规则的僭越者。\n至于何为「规则」，何为「打破」？\n猎犬从不思考——那只会阻碍它奔袭的速度。"
  },
  Stage_7861_Name = {
    Text = "界外之影Ⅳ"
  },
  Stage_7862_Desc = {
    Text = "它们无言地守护着海洋的秘密，灵魂和宇宙一样深沉。"
  },
  Stage_7862_Name = {
    Text = "海渊残像Ⅲ"
  },
  Stage_7863_Desc = {
    Text = "它们无言地守护着海洋的秘密，灵魂和宇宙一样深沉。"
  },
  Stage_7863_Name = {
    Text = "海渊残像Ⅰ"
  },
  Stage_7864_Desc = {
    Text = "伦蒂尼恩以灿烂的工业文明，以及笼罩市区的铅灰色浓雾闻名。\n雾气无处不在，对路人来说是更像是一种偶然、无意义的不便。"
  },
  Stage_7864_Name = {
    Text = "怪雾之都Ⅰ"
  },
  Stage_7865_Desc = {
    Text = "是什么蒙蔽了她的双眼？\n是爱、怜悯、正义和过分的感恩吗？"
  },
  Stage_7865_Name = {Text = "超脱"},
  Stage_7866_Desc = {
    Text = "孩子向母亲伸出双手，祈求一个充满疼痛的拥抱。\n即使注射针刺破纤嫩表皮，手术刀划开洁白肌肤，束缚带捆扎柔弱关节。\n蔓延的无边疼痛依然无法阻止她们相拥。\n因为，这是最温暖的拥抱。自胚胎脱出母体，生出嫌隙，磨出锋锐，相互伤害，最终回归亲密，融为一体。"
  },
  Stage_7866_Name = {Text = "她"},
  Stage_7867_Desc = {
    Text = "你沉睡在夜晚的寂静之中，\n没有剩下任何的疑惑或争端，\n就像拥有永恒的拥抱，\n我们躺在平静的安定之中。"
  },
  Stage_7867_Name = {Text = "房间"},
  Stage_7868_Desc = {
    Text = "皑皑雪原，百合繁盛。"
  },
  Stage_7868_Name = {Text = "神秘河"},
  Stage_7869_Desc = {
    Text = "黎明总会到来，太阳照常升起。"
  },
  Stage_7869_Name = {Text = "尾声"},
  Stage_7870_Desc = {
    Text = "她以己身承纳圣骸，以教义训导眷众，以毒牙布散信仰。"
  },
  Stage_7870_Name = {
    Text = "虔诚之握Ⅱ"
  },
  Stage_7871_Desc = {
    Text = "锋锐的利刺打破绝对的圆弧，并非“刻耳柏洛斯”之物自裂隙生出。"
  },
  Stage_7871_Name = {
    Text = "壳中裂缝"
  },
  Stage_7872_Desc = {
    Text = "现实埋下了祸种，命运却指引着相遇。"
  },
  Stage_7872_Name = {
    Text = "命运的种子"
  },
  Stage_78738_Name = {
    Text = "本源沉睡之主试玩关卡"
  },
  Stage_7873_Desc = {
    Text = "它们在黑暗中扭曲、融合，然后被小心翼翼地保管在造像里。\n这是一次蓄谋已久的重逢。"
  },
  Stage_7873_Name = {
    Text = "深海之遗·间隙Ⅴ"
  },
  Stage_7874_Desc = {
    Text = "在一艘船上，除了船长，还有谁是值得相信的呢？"
  },
  Stage_7874_Name = {Text = "船员"},
  Stage_7875_Desc = {
    Text = "跨越诸海之使徒。"
  },
  Stage_7875_Name = {Text = "使徒"},
  Stage_7876_Desc = {
    Text = "踏破诸海而过的，除了敌人，或许还有希望的微光。"
  },
  Stage_7876_Name = {
    Text = "沉溺之徒"
  },
  Stage_78773_Name = {
    Text = "本源深海淑女试玩关卡"
  },
  Stage_7877_Desc = {
    Text = "它们原本是悲伤、扭曲和懵懂组成的无意识集合，\n却被打扮成幸福的小孩、大人和宠物。\n因着从未品尝过幸福的滋味，它们成了最糟糕的演员。"
  },
  Stage_7877_Name = {
    Text = "蜡像之秘Ⅱ"
  },
  Stage_7878_Desc = {
    Text = "夜晚的港口，淳朴的居民，热情的款待。"
  },
  Stage_7878_Name = {
    Text = "十面埋伏"
  },
  Stage_7879_Desc = {
    Text = "来历不明的造像在黑暗中游荡、战栗。\n它们踏着古老的节拍，循着来自远方的笛声起舞。"
  },
  Stage_7879_Name = {
    Text = "血肉之沼·间隙Ⅷ"
  },
  Stage_7880_Desc = {
    Text = "突出重围永远不简单，但好在，这一次守密人找到了最亮的恒星。"
  },
  Stage_7880_Name = {
    Text = "追逐繁星"
  },
  Stage_7881_Desc = {
    Text = "第二颗心脏在墨菲体内跳动着，阻止「降生仪式」迫在眉睫。"
  },
  Stage_7881_Name = {
    Text = "另一个奇迹"
  },
  Stage_7882_Desc = {
    Text = "来历不明的造像在黑暗中游荡、战栗。\n它们踏着古老的节拍，循着来自远方的笛声起舞。"
  },
  Stage_7882_Name = {
    Text = "混沌之域·间隙Ⅶ"
  },
  Stage_7883_Desc = {
    Text = "真实，这残酷的真实。"
  },
  Stage_7883_Name = {
    Text = "面纱之下"
  },
  Stage_7884_Desc = {
    Text = "寂静燃烧的火焰，向旅人许下虚妄的诺言。"
  },
  Stage_7884_Name = {
    Text = "诱蛾之火"
  },
  Stage_7885_Desc = {
    Text = "在命运的狂风中颤抖、挣扎，但它不会真正地飘零。"
  },
  Stage_7885_Name = {
    Text = "摇摇欲坠"
  },
  Stage_7886_Desc = {
    Text = "缠绕在迷雾中的轨迹，无数脚步在其上徘徊，每一个踏点都是对命运的追问。"
  },
  Stage_7886_Name = {
    Text = "前路迷途"
  },
  Stage_7887_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_7887_Name = {
    Text = "幻梦深潜Ⅳ"
  },
  Stage_7888_Desc = {
    Text = "一堆粗鲁的、未消化的物质。人们称其为排泄物，或是混沌。 \n世界从排泄物中诞生。"
  },
  Stage_7888_Name = {
    Text = "混沌集群Ⅰ"
  },
  Stage_7889_Desc = {
    Text = "当离去的被人遗忘，一切都将回归常态。\n但那些消散的记忆，总会有人记得。"
  },
  Stage_7889_Name = {
    Text = "一切如常"
  },
  Stage_7890_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_7890_Name = {
    Text = "幻梦深潜Ⅴ"
  },
  Stage_7891_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_7891_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_7892_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_7892_Name = {
    Text = "幻梦深潜Ⅱ"
  },
