    Text = "人类的腿脚无法胜过敏捷的四足野生生物，但头脑可以。只是，在捕获“地狱犬”之后，等待着你们的又是什么呢？"
  },
  Stage_7912_Name = {
    Text = "袖中王牌"
  },
  Stage_7913_Desc = {
    Text = "与达芙黛尔夫人的往来，永远是由交易构成的。达芙黛尔出现，向你们提出了交易，而神秘的袭击者是否会认可这一交易呢？"
  },
  Stage_7913_Name = {
    Text = "公平交易"
  },
  Stage_7914_Desc = {
    Text = "在地铁内，你们遭到了神秘刺客的袭击……"
  },
  Stage_7914_Name = {
    Text = "人生无友"
  },
  Stage_7915_Desc = {
    Text = "追溯地狱犬“刻耳柏洛斯”的流言，弥萨格的调查员们来到伦蒂尼恩远郊的小镇拉伊，探寻失踪案背后的隐秘……"
  },
  Stage_7915_Name = {
    Text = "三思而后行"
  },
  Stage_7916_Desc = {
    Text = "癫狂的语调，浓烈的腥气，这就是来自拉伊的欢迎仪式。"
  },
  Stage_7916_Name = {
    Text = "欢迎来到拉伊"
  },
  Stage_7917_Desc = {
    Text = "一个好消息，一个坏消息。消失的线索不会重现，但新的案件已在暗中酝酿。相信吧，调查员不会再两手空空。"
  },
  Stage_7917_Name = {
    Text = "好消息，坏消息"
  },
  Stage_7918_Desc = {
    Text = "这里沉睡着一座古老城市的废墟。\n它和它的主人一样嗜睡。"
  },
  Stage_7918_Name = {
    Text = "波纳佩之墟Ⅳ"
  },
  Stage_7919_Desc = {
    Text = "艾尔沃斯位于卡达斯的极点，终年被不融的冰雪覆盖，\n厚实而坚硬的冰壳下，隐约潜藏着生命的搏动。"
  },
  Stage_7919_Name = {
    Text = "失序山脉Ⅲ"
  },
  Stage_7920_Desc = {
    Text = "此处埋葬着一所大学，千疮百孔，疲惫不堪\n它曾为人类存续奉献了一点希望与勇气\n至于结果如何，你现在都看到了"
  },
  Stage_7920_Name = {
    Text = "幻梦深潜Ⅶ"
  },
  Stage_7921_Desc = {
    Text = "它们在黑暗中扭曲、融合，然后被小心翼翼地保管在造像里。\n这是一次蓄谋已久的重逢。"
  },
  Stage_7921_Name = {
    Text = "血肉之沼·间隙Ⅰ"
  },
  Stage_7922_Desc = {
    Text = "献上血肉铸就的现实吧，它们是永不餍足的深渊。"
  },
  Stage_7922_Name = {
    Text = "器质残像Ⅳ"
  },
  Stage_7923_Desc = {
    Text = "罗杰斯蜡像馆坐落在南华克街的最深处，靠近泰姆河的支流。\n它毫不起眼，却有众多先锋艺术爱好者慕名而来。"
  },
  Stage_7923_Name = {
    Text = "狂躁蜡馆Ⅳ"
  },
  Stage_7924_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_7924_Name = {
    Text = "幻梦深潜Ⅱ"
  },
