  },
  Stage_7930_Name = {
    Text = "幻梦深潜Ⅴ"
  },
  Stage_7931_Desc = {
    Text = "祂的国度是宇宙躯壳，祂的欲望无边无际。"
  },
  Stage_7931_Name = {
    Text = "蠕虫之所Ⅱ"
  },
  Stage_7932_Desc = {
    Text = "这里沉睡着一座古老城市的废墟。\n它和它的主人一样嗜睡。"
  },
  Stage_7932_Name = {
    Text = "波纳佩之墟Ⅱ"
  },
  Stage_7933_Desc = {
    Text = "真实，这残酷的真实。"
  },
  Stage_7933_Name = {
    Text = "面纱之下"
  },
  Stage_7934_Desc = {
    Text = "虚无乃吾等之源头，亦为吾等之归宿。"
  },
  Stage_7934_Name = {
    Text = "不朽的低语"
  },
  Stage_7935_Desc = {
    Text = "来历不明的造像在黑暗中游荡、战栗。\n它们踏着古老的节拍，循着来自远方的笛声起舞。"
  },
  Stage_7935_Name = {
    Text = "深海之遗·间隙Ⅷ"
  },
  Stage_7936_Desc = {
    Text = "拉伊小镇位于伦蒂尼恩东北部，隐没在绵延的山脉中。\n沉默的乡民、无处不在的视线……当心，这里的一切都不太寻常。"
  },
  Stage_7936_Name = {
    Text = "错乱异镇Ⅱ"
  },
  Stage_7937_Desc = {
    Text = "「每把钥匙都有唯一的编号，只对应唯一的调查员。」\n「因此，每把钥匙的陨落也对应着唯一的调查员之死。」\n「真好啊。就连死亡都是独一无二的。」"
  },
  Stage_7937_Name = {
    Text = "幻梦深潜Ⅴ"
  },
  Stage_7938_Desc = {
    Text = "「每把钥匙都有唯一的编号，只对应唯一的调查员。」\n「因此，每把钥匙的陨落也对应着唯一的调查员之死。」\n「真好啊。就连死亡都是独一无二的。」"
