  },
  Stage_7940_Name = {
    Text = "幻梦深潜Ⅵ"
  },
  Stage_7941_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_7941_Name = {
    Text = "血肉之沼·轮转间隙Ⅲ"
  },
  Stage_7942_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_7942_Name = {
    Text = "血肉之沼·轮转间隙Ⅲ"
  },
  Stage_7943_Desc = {
