  },
  Stage_7944_Desc = {
    Text = "「每把钥匙都有唯一的编号，只对应唯一的调查员。」\n「因此，每把钥匙的陨落也对应着唯一的调查员之死。」\n「真好啊。就连死亡都是独一无二的。」"
  },
  Stage_7944_Name = {
    Text = "幻梦深潜Ⅱ"
  },
  Stage_7945_Desc = {
    Text = "她是梦境与现实交错的界限，是每个仰望夜空的灵魂内心深处的反射。"
  },
  Stage_7945_Name = {
    Text = "倒错的群星"
  },
  Stage_7945_StageInitStateText = {Text = "海魇"},
  Stage_7946_Desc = {
    Text = "潜藏在宇宙深处的弯曲视界。 \n它能带你从黑暗抵达另一处黑暗。"
  },
  Stage_7946_Name = {
    Text = "史瓦西喉Ⅰ"
  },
  Stage_7947_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_7947_Name = {
    Text = "混沌之域·间隙Ⅲ"
  },
  Stage_7948_Desc = {
    Text = "这里沉睡着一座古老城市的废墟。\n它和它的主人一样嗜睡。"
  },
  Stage_7948_Name = {
    Text = "波纳佩之墟Ⅴ"
  },
  Stage_7949_Desc = {
    Text = "它以乖巧的姿态靠在床沿，暗淡的纽扣眼睛望着虚空。\n小小的身躯承受了主人的全部眼泪，却无法出言安慰。"
  },
  Stage_7949_Name = {
    Text = "玩偶之泪Ⅱ"
  },
  Stage_7950_Desc = {
    Text = "为了您的生命健康，远离尼古丁。"
  },
  Stage_7950_Name = {
    Text = "烟与紫罗兰"
  },
  Stage_7951_Desc = {
    Text = "来历不明的造像在黑暗中游荡、战栗。\n它们踏着古老的节拍，循着来自远方的笛声起舞。"
  },
  Stage_7951_Name = {
    Text = "血肉之沼·间隙Ⅱ"
  },
  Stage_7952_Desc = {
    Text = "献上血肉铸就的现实吧，它们是永不餍足的深渊。"
  },
  Stage_7952_Name = {
    Text = "器质残像Ⅲ"
  },
  Stage_7953_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_7953_Name = {
    Text = "幻梦深潜Ⅱ"
  },
  Stage_7954_Desc = {
    Text = "然后她消失了，回到黑暗中。\n人们仰望高处，竖起眼睛，注视着她掠过的天空。"
  },
  Stage_7954_Name = {Text = "雪松木"},
  Stage_7955_Desc = {
    Text = "在她美貌的祭坛上，我愿供奉我的眼泪，我的叹息以及我的赤心。"
  },
  Stage_7955_Name = {
    Text = "伽拉忒亚"
  },
  Stage_7956_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_7956_Name = {
    Text = "幻梦深潜Ⅴ"
  },
  Stage_79574_Desc = {
    Text = "露出的心脏，古旧的标本，暗淡的银钥……\n正如飞蛾扑火，她所期待的，是由你为她带来的告别。"
  },
  Stage_79574_Name = {
    Text = "逐火之蛾·之四"
  },
  Stage_79575_Desc = {
    Text = "悠久的银光赐予少女第三次生命。\n最后的泪水不再流淌，永恒的痛苦就此开始。\n第一滴眼泪开始落下，崭新的人生开启新章。\n赴死之人重新启程，去寻找真正的自己。"
  },
