  },
  Stage_79594_Desc = {
    Text = "现在开始，请对我知无不言，将你的记忆展露于我。\n现在开始，请对我令无不从，将你的心灵交付于我。\n我将把你塑造为，源自记忆深处，最真实的你。"
  },
  Stage_79594_Name = {
    Text = "记忆诊所·之五"
  },
  Stage_79595_Desc = {
    Text = "无形之火以万千生灵为薪，焚烧世间万象。\n不容哀嚎，不容驻足，不容一丝一毫痕迹留存。\n其怒无穷无尽，无声咆哮永不停歇。\n因总有抗逆命运之人，妄图赎下注定化为灰烬的柴薪。"
  },
  Stage_79595_Name = {
    Text = "燃烧的世界·癫狂"
  },
  Stage_79596_Desc = {
    Text = "无形之火以万千生灵为薪，焚烧世间万象。\n不容哀嚎，不容驻足，不容一丝一毫痕迹留存。\n其怒无穷无尽，无声咆哮永不停歇。\n因总有抗逆命运之人，妄图赎下注定化为灰烬的柴薪。"
  },
