  Stage_79599_Name = {
    Text = "燃烧的世界·之三"
  },
  Stage_7959_Desc = {
    Text = "不要回头！多么贵重的叮嘱，别再步俄耳甫斯的后尘。"
  },
  Stage_7959_Name = {
    Text = "不要回头"
  },
  Stage_79600_Desc = {
    Text = "无形之火以万千生灵为薪，焚烧世间万象。\n不容哀嚎，不容驻足，不容一丝一毫痕迹留存。\n其怒无穷无尽，无声咆哮永不停歇。\n因总有抗逆命运之人，妄图赎下注定化为灰烬的柴薪。"
  },
  Stage_79600_Name = {
    Text = "燃烧的世界·之二"
  },
  Stage_79601_Desc = {
    Text = "无形之火以万千生灵为薪，焚烧世间万象。\n不容哀嚎，不容驻足，不容一丝一毫痕迹留存。\n其怒无穷无尽，无声咆哮永不停歇。\n因总有抗逆命运之人，妄图赎下注定化为灰烬的柴薪。"
  },
  Stage_79601_Name = {
    Text = "燃烧的世界·之一"
  },
  Stage_79602_Desc = {
    Text = "跟着灵摆摇晃的节奏，聆听四周悦耳的虫鸣，放松劳累紧绷的神经，克莱门汀医生将带你入梦。\n欢迎来到心灵的殿堂。"
  },
  Stage_79602_Name = {
    Text = "侵梦之时·之五"
  },
  Stage_79603_Desc = {
    Text = "跟着灵摆摇晃的节奏，聆听四周悦耳的虫鸣，放松劳累紧绷的神经，克莱门汀医生将带你入梦。\n欢迎来到心灵的殿堂。"
