  },
  Stage_79606_Name = {
    Text = "侵梦之时·之一"
  },
  Stage_79607_Desc = {
    Text = "跟着灵摆摇晃的节奏，聆听四周悦耳的虫鸣，放松劳累紧绷的神经，克莱门汀医生将带你入梦。\n欢迎来到心灵的殿堂。"
  },
  Stage_79607_Name = {
    Text = "侵梦之时·之三"
  },
  Stage_79608_Desc = {
    Text = "跟着灵摆摇晃的节奏，聆听四周悦耳的虫鸣，放松劳累紧绷的神经，克莱门汀医生将带你入梦。\n欢迎来到心灵的殿堂。"
  },
  Stage_79608_Name = {
    Text = "侵梦之时·之二"
  },
  Stage_7960_Desc = {
    Text = "多么幸福的沉睡，它让我的天使回到我身边。"
  },
  Stage_7960_Name = {Text = "秘窗"},
  Stage_7961_Desc = {
    Text = "日记是记忆的碎片。\n调查中总是会发现日记的。"
  },
  Stage_7961_Name = {
    Text = "记忆碎片"
  },
  Stage_7962_Desc = {
    Text = "皑皑雪原，百合繁盛。"
  },
  Stage_7962_Name = {Text = "28天"},
  Stage_7963_Desc = {
    Text = "当勋贵们痛失权柄，当豪富们倾家荡产，他们寸步难行，就像你现在这样。"
  },
  Stage_7963_Name = {
    Text = "飞越疯人院"
  },
  Stage_7964_Desc = {
    Text = "这是一方为她开辟的天地，是伟大的爱意与可怖的囚笼。"
  },
  Stage_7964_Name = {
    Text = "精神病院"
  },
  Stage_7965_Desc = {
    Text = "世间的交锋不止于兵刃相接的战场，有时也存在于疯人之口。"
  },
  Stage_7965_Name = {
    Text = "疯人之口"
  },
  Stage_7966_Desc = {
    Text = "寂静燃烧的火焰，向旅人许下虚妄的诺言。"
  },
  Stage_7966_Name = {
    Text = "诱蛾之火"
  },
  Stage_7967_Desc = {
    Text = "缠绕在迷雾中的轨迹，无数脚步在其上徘徊，每一个踏点都是对命运的追问。"
  },
  Stage_7967_Name = {
    Text = "前路迷途"
  },
  Stage_7968_Desc = {
    Text = "它一刻不停地追逐那些打破规则的僭越者。\n至于何为「规则」，何为「打破」？\n猎犬从不思考——那只会阻碍它奔袭的速度。"
  },
  Stage_7968_Name = {
    Text = "界外之影Ⅰ"
  },
  Stage_7969_Desc = {
    Text = "她以己身承纳圣骸，以教义训导眷众，以毒牙布散信仰。"
  },
  Stage_7969_Name = {
    Text = "虔诚之握Ⅰ"
  },
  Stage_7970_Desc = {
    Text = "风雨仍在酝酿，一切尚未终结。"
  },
  Stage_7970_Name = {
    Text = "现实重启"
  },
  Stage_7971_Desc = {
    Text = "那绝非受到期待的生命，只是污浊的寄生虫罢了。"
  },
  Stage_7971_Name = {Text = "寄生物"},
  Stage_7972_Desc = {
    Text = "驶向陆地，驶向一线生机。"
  },
  Stage_7972_Name = {
    Text = "悲剧的起航"
  },
  Stage_7973_Desc = {
    Text = "夜色被暗流侵蚀，星辰失声。潜藏着转折与风雨的危机之月，静默映照着未知的未来。"
  },
  Stage_7973_Name = {
    Text = "危机之月"
  },
  Stage_7974_Desc = {
    Text = "在无尽夜幕的漆黑中追逐着那诱人的光明，犹如一只逐火之蛾，不顾一切地向着命运的焰火翱翔。"
  },
  Stage_7974_Name = {
    Text = "逐火之蛾"
  },
  Stage_7975_Desc = {
    Text = "在过往岁月中飘摇的友谊，结下了新的希望。"
  },
  Stage_7975_Name = {
    Text = "旧友新朋"
  },
  Stage_7976_Desc = {
    Text = "在命运的狂风中颤抖、挣扎，但它不会真正地飘零。"
  },
  Stage_7976_Name = {
    Text = "摇摇欲坠"
  },
  Stage_7977_Desc = {
    Text = "迎着风与黄沙，战士义无反顾地奔向太阳。"
  },
  Stage_7977_Name = {
    Text = "太阳远征"
  },
  Stage_7978_Desc = {
    Text = "蠕动着、流淌着……原生质的肿泡正从枷锁的缝隙中溜走。\n这是她为「自由」付出的代价。"
  },
  Stage_7978_Name = {
    Text = "漆黑之链Ⅴ"
  },
  Stage_7979_Desc = {
    Text = "一堆粗鲁的、未消化的物质。人们称其为排泄物，或是混沌。 \n世界从排泄物中诞生。"
  },
  Stage_7979_Name = {
    Text = "混沌集群Ⅲ"
  },
  Stage_7980_Desc = {
    Text = "来历不明的造像在黑暗中游荡、战栗。\n它们踏着古老的节拍，循着来自远方的笛声起舞。"
  },
  Stage_7980_Name = {
    Text = "超维之旅·间隙Ⅷ"
  },
  Stage_7981_Desc = {
    Text = "它们在黑暗中扭曲、融合，然后被小心翼翼地保管在造像里。\n这是一次蓄谋已久的重逢。"
  },
  Stage_7981_Name = {
    Text = "血肉之沼·间隙Ⅴ"
  },
  Stage_7982_Desc = {
    Text = "然后她消失了，回到黑暗中。\n人们仰望高处，竖起眼睛，注视着她掠过的天空。"
  },
  Stage_7982_Name = {Text = "雪松木"},
  Stage_7983_Desc = {
    Text = "一只小老鼠，一只小老鼠。\n跑啊，跑啊，她用切肉刀割掉它的尾巴。"
  },
  Stage_7983_Name = {
    Text = "布朗出击"
  },
  Stage_7984_Desc = {
    Text = "你沉睡在夜晚的寂静之中，\n没有剩下任何的疑惑或争端，\n就像拥有永恒的拥抱，\n我们躺在平静的安定之中。"
  },
  Stage_7984_Name = {Text = "房间"},
  Stage_7985_Desc = {
    Text = "伦蒂尼恩以灿烂的工业文明，以及笼罩市区的铅灰色浓雾闻名。\n雾气无处不在，对路人来说是更像是一种偶然、无意义的不便。"
  },
  Stage_7985_Name = {
    Text = "怪雾之都Ⅲ"
  },
  Stage_7986_Desc = {
    Text = "在她美貌的祭坛上，我愿供奉我的眼泪，我的叹息以及我的赤心。"
  },
  Stage_7986_Name = {
    Text = "伽拉忒亚"
  },
  Stage_7987_Desc = {
    Text = "吧唧咕叽，裂开了。\n吧唧咕叽，断掉了。"
  },
  Stage_7987_Name = {Text = "娃娃馆"},
  Stage_7988_Desc = {
    Text = "规则，不就是用来打破的吗？"
  },
  Stage_7988_Name = {
    Text = "三条规则"
  },
  Stage_7989_Desc = {
    Text = "位于北约克郡的海边小镇——斯卡伯勒。这里拥有高耸的悬崖与金色的海湾，是一处优雅迷人的度假胜地。"
  },
  Stage_7989_Name = {
    Text = "斯卡伯勒之夏"
  },
  Stage_7990_Desc = {
    Text = "噢，手臂，恼人的手臂！它们总是揪着我的头发不放。"
  },
  Stage_7990_Name = {Text = "二十四"},
  Stage_7991_Desc = {
    Text = "她从人类的眼泪与排泄物中学到不少实用心理学知识——比所有书籍中学到的还要多。"
  },
  Stage_7991_Name = {
    Text = "诊疗手册"
  },
  Stage_7992_Desc = {
    Text = "为了您的生命健康，远离尼古丁。"
  },
  Stage_7992_Name = {
    Text = "烟与紫罗兰"
  },
  Stage_7993_Desc = {
    Text = "位于北约克郡的海边小镇——斯卡伯勒。这里拥有高耸的悬崖与金色的海湾，是一处优雅迷人的度假胜地。"
  },
  Stage_7993_Name = {
    Text = "斯卡伯勒之夏"
  },
  Stage_7994_Desc = {
    Text = "为了您的生命健康，远离尼古丁。"
  },
  Stage_7994_Name = {
    Text = "烟与紫罗兰"
  },
  Stage_7995_Desc = {
    Text = "一只小老鼠，一只小老鼠。\n跑啊，跑啊，她用切肉刀割掉它的尾巴。"
  },
  Stage_7995_Name = {
    Text = "布朗出击"
  },
  Stage_7996_Desc = {
    Text = "然后她消失了，回到黑暗中。\n人们仰望高处，竖起眼睛，注视着她掠过的天空。"
  },
  Stage_7996_Name = {Text = "雪松木"},
  Stage_7997_Desc = {
    Text = "在她美貌的祭坛上，我愿供奉我的眼泪，我的叹息以及我的赤心。"
  },
  Stage_7997_Name = {
    Text = "伽拉忒亚"
  },
  Stage_7998_Name = {Text = " 【序】"},
  Stage_7999_Desc = {
    Text = "噢，手臂，恼人的手臂！它们总是揪着我的头发不放。"
  },
  Stage_7999_Name = {Text = "二十四"},
  Stage_8000_Desc = {
    Text = "是的，是的。眼睛是心灵的牢笼，灵魂是禁锢肉身的枷锁。"
  },
  Stage_8000_Name = {
    Text = "解剖的忧郁"
  },
  Stage_8001_Desc = {
    Text = "没错，宝贝。尽情地哭吧，把你的痛苦当作绝世名作一样装裱起来。"
  },
  Stage_8001_Name = {
    Text = "少女和眼泪"
  },
  Stage_8002_Desc = {
    Text = "「手」掀开夜的帷幕，悄悄来到这个世界。"
  },
  Stage_8002_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_8003_Desc = {
    Text = "「手」掀开夜的帷幕，悄悄来到这个世界。"
  },
  Stage_8003_Name = {
    Text = "幻梦深潜Ⅲ"
  },
  Stage_8004_Desc = {
    Text = "「手」掀开夜的帷幕，悄悄来到这个世界。"
  },
  Stage_8004_Name = {
    Text = "幻梦深潜Ⅱ"
  },
  Stage_8005_Desc = {
    Text = "「手」掀开夜的帷幕，悄悄来到这个世界。"
  },
  Stage_8005_Name = {
    Text = "幻梦深潜Ⅴ"
  },
  Stage_8006_Desc = {
    Text = "「手」掀开夜的帷幕，悄悄来到这个世界。"
  },
  Stage_8006_Name = {
    Text = "幻梦深潜Ⅳ"
  },
  Stage_8007_Desc = {
    Text = "「手」掀开夜的帷幕，悄悄来到这个世界。"
  },
  Stage_8007_Name = {
    Text = "幻梦深潜Ⅶ"
  },
  Stage_8008_Desc = {
    Text = "「手」掀开夜的帷幕，悄悄来到这个世界。"
  },
  Stage_8008_Name = {
    Text = "幻梦深潜Ⅵ"
  },
  Stage_8009_Desc = {
    Text = "这里沉睡着一座古老城市的废墟。\n它和它的主人一样嗜睡。"
  },
  Stage_8009_Name = {
    Text = "波纳佩之墟Ⅰ"
  },
  Stage_8010_Desc = {
    Text = "我们还会不断相遇，在不同的时间与空间维度里"
  },
  Stage_8010_Name = {
    Text = "后会有期"
  },
  Stage_8011_Desc = {
    Text = "潜藏在宇宙深处的弯曲视界。 \n它能带你从黑暗抵达另一处黑暗。"
  },
  Stage_8011_Name = {
    Text = "史瓦西喉Ⅱ"
  },
  Stage_8012_Desc = {
    Text = "潜藏在宇宙深处的弯曲视界。 \n它能带你从黑暗抵达另一处黑暗。"
  },
  Stage_8012_Name = {
    Text = "史瓦西喉Ⅴ"
  },
  Stage_8013_Desc = {
    Text = "没有人能摘下神王赐下的冠冕，没有人。"
  },
  Stage_8013_Name = {
    Text = "利莫里亚的「荣光」"
  },
  Stage_8014_Desc = {
    Text = "在过往岁月中飘摇的友谊，结下了新的希望。"
  },
  Stage_8014_Name = {
    Text = "旧友新朋"
  },
  Stage_8015_Desc = {
    Text = "夜色被暗流侵蚀，星辰失声。潜藏着转折与风雨的危机之月，静默映照着未知的未来。"
  },
  Stage_8015_Name = {
    Text = "危机之月"
  },
  Stage_8016_Desc = {
    Text = "是的，贪婪是他的原罪，他会因此忏悔。"
  },
  Stage_8016_Name = {Text = "湮灭"},
  Stage_8017_Desc = {
    Text = "缄默的守护者发出了新声。"
  },
  Stage_8017_Name = {
    Text = "过载保护"
  },
  Stage_8018_Desc = {
    Text = "在无尽夜幕的漆黑中追逐着那诱人的光明，犹如一只逐火之蛾，不顾一切地向着命运的焰火翱翔。"
  },
  Stage_8018_Name = {
    Text = "逐火之蛾"
  },
  Stage_8019_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_8019_Name = {
    Text = "混沌之域·轮转间隙Ⅲ"
  },
  Stage_8020_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_8020_Name = {
    Text = "混沌之域·轮转间隙Ⅲ"
  },
  Stage_8021_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_8021_Name = {
    Text = "混沌之域·轮转间隙Ⅲ"
  },
  Stage_8022_Desc = {
    Text = "那绝非受到期待的生命，只是污浊的寄生虫罢了。"
  },
  Stage_8022_Name = {Text = "寄生物"},
  Stage_8023_Desc = {
    Text = "多么幸福的沉睡，它让我的天使回到我身边。"
  },
  Stage_8023_Name = {Text = "秘窗"},
  Stage_80242_Desc = {
    Text = "故事最后，世界仍在燃烧，我已做好告别的准备。\n但我们终将重逢。"
  },
  Stage_80242_Name = {
    Text = "燃烧的世界，再见"
  },
  Stage_80243_Desc = {
    Text = "人是一种社会性动物，他们受到社会的影响，又影响着社会。\n所以，告诉我，你被生活和环境塑造成了什么样的自己？"
  },
  Stage_80243_Name = {
    Text = "认知重构实验"
  },
  Stage_80244_Desc = {
    Text = "原谅我没有什么礼物赠送给你。\n这一枚小小的虫蛹，是我对你最深重的祝福：陷入绝境时，请你一定要破茧重生。"
  },
  Stage_80244_Name = {
    Text = "友谊的虫蛹"
  },
  Stage_80245_Desc = {
    Text = "火焰，带来光明，也带来疼痛与伤害。\n当整个世界都在燃烧，我愿将生命化为一滴泪水，汇聚成痛苦的海洋。"
  },
  Stage_80245_Name = {
    Text = "你好，燃烧的世界"
  },
  Stage_80246_Desc = {
    Text = "勇者是孤独的，人类无法真正走进他，龙也无法真正理解他。\n究竟是屠龙，还是化身为龙，这是一个问题。"
  },
  Stage_80246_Name = {
    Text = "孤独的勇者"
  },
  Stage_80247_Desc = {
    Text = "我对世界满怀梦想，希望鲜花一直盛开，希望微笑永恒长存。\n但生命只给了我一个梦。"
  },
  Stage_80247_Name = {
    Text = "我有许多梦想"
  },
  Stage_80248_Desc = {
    Text = "群体是流动的琥珀，每个灵魂都在折射他人的光芒，又在透明牢笼里看见自己的倒影。"
  },
  Stage_80248_Name = {
    Text = "社会性动物"
  },
  Stage_80249_Desc = {
    Text = "我是我的朋友，也是我的敌人。\n这场合作与厮杀不会停止，直到场上只留下一人。"
  },
  Stage_80249_Name = {Text = "二重身"},
  Stage_8024_Desc = {
    Text = "无论金属躯壳多么沉重，灵魂只占21克。"
  },
  Stage_8024_Name = {Text = "21克"},
  Stage_80250_Desc = {
    Text = "小小的蝴蝶，穿过梦境，飞向现实。\n或许它太过愚蠢，但蝴蝶的选择，与人不同。"
  },
  Stage_80250_Name = {Text = "蝴蝶飞"},
  Stage_80251_Desc = {
    Text = "让我来看看，看看是什么样的成分与结构，组成了“你”与“我”。"
  },
  Stage_80251_Name = {Text = "眼睛"},
  Stage_80252_Desc = {
    Text = "哦，朋友，我们都会做梦。\n只是有的人会让梦成为现实，而有的人的现实，就像梦一样荒诞无经。"
  },
  Stage_80252_Name = {
    Text = "不受控的梦"
  },
  Stage_80253_Desc = {
    Text = "我要在失落的记忆里起舞，忘记爱我的人和我爱的人，只和自己永恒地起舞，舞到时间的尽头。"
  },
  Stage_80253_Name = {
    Text = "失落的记忆"
  },
  Stage_80254_Desc = {
    Text = "逃，逃，小狗狗快逃。\n用你的惊慌失措与痛苦无助，为我们表演一场滑稽戏。"
  },
  Stage_80254_Name = {Text = "追捕"},
  Stage_80255_Desc = {
    Text = "在看着你，我在看着你。\n每时每刻，无时无刻，就那样看着你。"
  },
  Stage_80255_Name = {
    Text = "他者的凝视"
  },
  Stage_80256_Desc = {
    Text = "回忆并不可靠，因为随着我在其中的翻找，它开始损毁和褪色。究竟用什么办法才可以让你的身影永恒固定？\n如果回忆不牢固，那就刻在生命里。"
  },
  Stage_80256_Name = {
    Text = "相似的身影"
  },
  Stage_80257_Desc = {
    Text = "前三枪只是预奏。\n最后的两枪里，一枪带走他的生命，一枪带走他的灵魂。"
  },
  Stage_80257_Name = {
    Text = "五声枪响"
  },
  Stage_80258_Desc = {
    Text = "“好奇”向你抛出了一个问题，哪怕明知答案满是荆棘，会让你焚毁殆尽，你也无法拒绝。\n你终究是那只无法拒绝“好奇”的猫。"
  },
  Stage_80258_Name = {
    Text = "好奇心害死猫"
  },
  Stage_80259_Desc = {
    Text = "世界是个大型的疗养院，每个人都在发疯，或者隐藏自己的疯狂。\n所以，要来一场心理咨询吗？"
  },
  Stage_80259_Name = {
    Text = "咨询邀请"
  },
  Stage_8025_Desc = {
    Text = "这是一方为她开辟的天地，是伟大的爱意与可怖的囚笼。"
  },
  Stage_8025_Name = {
    Text = "精神病院"
  },
  Stage_80260_Desc = {
    Text = "哦，朋友，我们都会做梦。\n只是有的人会让梦成为现实，而有的人的现实，就像梦一样荒诞无经。"
  },
  Stage_80260_Name = {
    Text = "不受控的梦"
  },
