  },
  Stage_80268_Desc = {
    Text = "人是一种社会性动物，他们受到社会的影响，又影响着社会。\n所以，告诉我，你被生活和环境塑造成了什么样的自己？"
  },
  Stage_80268_Name = {
    Text = "认知重构实验"
  },
  Stage_80269_Desc = {
    Text = "我对世界满怀梦想，希望鲜花一直盛开，希望微笑永恒长存。\n但生命只给了我一个梦。"
  },
  Stage_80269_Name = {
    Text = "我有许多梦想"
  },
  Stage_8026_Desc = {
    Text = "当勋贵们痛失权柄，当豪富们倾家荡产，他们寸步难行，就像你现在这样。"
  },
  Stage_8026_Name = {
    Text = "飞越疯人院"
  },
  Stage_80270_Desc = {
    Text = "我是我的朋友，也是我的敌人。\n这场合作与厮杀不会停止，直到场上只留下一人。"
  },
  Stage_80270_Name = {Text = "二重身"},
  Stage_80271_Desc = {
    Text = "小小的蝴蝶，穿过梦境，飞向现实。\n或许它太过愚蠢，但蝴蝶的选择，与人不同。"
  },
  Stage_80271_Name = {Text = "蝴蝶飞"},
  Stage_8027_Desc = {
    Text = "世间的交锋不止于兵刃相接的战场，有时也存在于疯人之口。"
  },
  Stage_8027_Name = {
    Text = "疯人之口"
  },
  Stage_8028_Desc = {
    Text = "剪断木偶身上的细线，她就再也不会舞蹈。"
  },
  Stage_8028_Name = {
    Text = "飞鸟不在的夜"
  },
  Stage_8029_Desc = {
    Text = "不要回头！多么贵重的叮嘱，别再步俄耳甫斯的后尘。"
  },
  Stage_8029_Name = {
    Text = "不要回头"
  },
  Stage_8030_Desc = {
    Text = "谁能诠释“春天”的含义？\n蛰伏于静寂虚空中的死亡与遗忘，融入朦胧的春日蜃景。"
  },
  Stage_8030_Name = {
    Text = "波提切利之春"
  },
  Stage_8031_Desc = {
    Text = "日记是记忆的碎片。\n调查中总是会发现日记的。"
  },
  Stage_8031_Name = {
    Text = "记忆碎片"
  },
  Stage_8032_Desc = {
    Text = "初次见面，我的主人。"
  },
  Stage_8032_Name = {Text = "第六感"},
  Stage_8033_Desc = {
    Text = "它们在黑暗中扭曲、融合，然后被小心翼翼地保管在造像里。\n这是一次蓄谋已久的重逢。"
  },
  Stage_8033_Name = {
    Text = "血肉之沼·间隙Ⅵ"
  },
  Stage_8034_Desc = {
    Text = "早在群星诞生之前，它们便存在于此。\n它们既是虚无，也是一切。"
  },
  Stage_8034_Name = {
    Text = "浑浊残像Ⅲ"
  },
  Stage_8035_Desc = {Text = "随机4"},
  Stage_8035_Name = {
    Text = "月沼之镜Ⅳ"
  },
  Stage_8036_Desc = {Text = "随机5"},
  Stage_8036_Name = {
    Text = "月沼之镜Ⅴ"
  },
  Stage_8037_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_8037_Name = {
    Text = "混沌之域·轮转间隙Ⅰ"
  },
  Stage_8038_Desc = {Text = "随机1"},
  Stage_8038_Name = {
    Text = "月沼之镜Ⅰ"
  },
  Stage_8039_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_8039_Name = {
    Text = "混沌之域·轮转间隙Ⅰ"
  },
  Stage_8040_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_8040_Name = {
    Text = "混沌之域·轮转间隙Ⅰ"
  },
  Stage_8041_Desc = {
    Text = "拉蒙娜回归了队伍。弥萨格调查员的旅程继续。"
  },
  Stage_8041_Name = {
    Text = "昨日重现"
  },
  Stage_8042_Desc = {
    Text = "荒芜的铁路桥下，庞大臃肿的怪物发出古怪的低吼。要抵达拉伊疯人院，就必须跨过这里。"
  },
  Stage_8042_Name = {
    Text = "船到桥头自然直"
  },
  Stage_8043_Desc = {
    Text = "你想要知道的一切，就在你的眼前，只是你从未发现。"
  },
  Stage_8043_Name = {
    Text = "藏于帽檐下"
  },
  Stage_8044_Desc = {
    Text = "人生就像一个螺旋，曾经逃脱过的梦魇，总是会在午夜再一次袭来。"
  },
  Stage_8044_Name = {
    Text = "回到出发点"
  },
  Stage_8045_Desc = {
    Text = "拉蒙娜与萝坦的絮语声中，守密人陷入牢笼中的梦境。"
  },
  Stage_8045_Name = {
    Text = "不要修理未损之物"
  },
  Stage_8046_Desc = {
    Text = "神说，他们生来便该历经苦难，流尽鲜血。\n就像太阳本该升起，雨水本该坠落。\n一切都是最好的安排。"
  },
  Stage_8046_Name = {Text = "苦雨地"},
  Stage_8047_Desc = {
    Text = "罗杰斯蜡像馆坐落在南华克街的最深处，靠近泰姆河的支流。\n它毫不起眼，却有众多先锋艺术爱好者慕名而来。"
  },
  Stage_8047_Name = {
    Text = "狂躁蜡馆Ⅱ"
  },
  Stage_8048_Desc = {
    Text = "它是这里唯一的活物，它所见的一切由它统治。\n——它是至高无上的国王。"
  },
  Stage_8048_Name = {
    Text = "野兽王国"
  },
  Stage_8049_Desc = {
    Text = "祂的国度是宇宙躯壳，祂的欲望无边无际。"
  },
  Stage_8049_Name = {
    Text = "蠕虫之所Ⅰ"
  },
  Stage_8050_Desc = {
    Text = "「手」掀开夜的帷幕，悄悄来到这个世界。"
  },
  Stage_8050_Name = {
    Text = "幻梦深潜Ⅴ"
  },
  Stage_8051_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_8051_Name = {
    Text = "幻梦深潜Ⅱ"
  },
  Stage_8052_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_8052_Name = {
    Text = "幻梦深潜Ⅲ"
  },
  Stage_8053_Desc = {
    Text = "这是一部没有结尾的电影，她已在幕间沉睡多年。\n她梦见夏日午后的玫瑰，也梦见灰烬和风……"
  },
  Stage_8053_Name = {
    Text = "菲林诗社"
  },
  Stage_8054_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_8054_Name = {
    Text = "幻梦深潜Ⅵ"
  },
  Stage_8055_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_8055_Name = {
    Text = "幻梦深潜Ⅶ"
  },
  Stage_8056_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_8056_Name = {
    Text = "幻梦深潜Ⅳ"
  },
  Stage_8057_Desc = {
    Text = "坍塌的偶像注视着自己的子民。\n看他们生存、繁衍、互相争斗，然后将自己彻底遗忘。\n坍塌的偶像怀念着自己的子民。"
  },
  Stage_8057_Name = {
    Text = "幻梦深潜Ⅴ"
  },
  Stage_8058_Desc = {
    Text = "当雨幕落下，鲜血涌出，我们迎来再度相聚的时刻。\n好久不见，守密人。"
  },
  Stage_8058_Name = {
    Text = "不期而遇"
  },
  Stage_8060_Desc = {
    Text = "当影子潜入黑夜，水滴汇入雨水。\n属于猎杀的时刻即将来临……"
  },
  Stage_8060_Name = {
    Text = "暴雨将至"
  },
  Stage_8062_Desc = {
    Text = "我们是虫豸、骨头与眼泪的集合。\n今夜我们在此相聚，只为一见那流淌着无数彩虹的河流。"
  },
  Stage_8062_Name = {
    Text = "猎颅集会"
  },
  Stage_8063_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_8063_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_8064_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_8064_Name = {
    Text = "幻梦深潜Ⅲ"
  },
  Stage_8065_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_8065_Name = {
    Text = "幻梦深潜Ⅱ"
  },
  Stage_8066_Desc = {
