  Stage_8069_Name = {
    Text = "幻梦深潜Ⅵ"
  },
  Stage_8070_Desc = {
    Text = "它们在黑暗中扭曲、融合，然后被小心翼翼地保管在造像里。\n这是一次蓄谋已久的重逢。"
  },
  Stage_8070_Name = {
    Text = "深海之遗·间隙Ⅵ"
  },
  Stage_8071_Desc = {
    Text = "它们原本是悲伤、扭曲和懵懂组成的无意识集合，\n却被打扮成幸福的小孩、大人和宠物。\n因着从未品尝过幸福的滋味，它们成了最糟糕的演员。"
  },
  Stage_8071_Name = {
    Text = "蜡像之秘Ⅲ"
  },
  Stage_8072_Desc = {
    Text = "它一刻不停地追逐那些打破规则的僭越者。\n至于何为「规则」，何为「打破」？\n猎犬从不思考——那只会阻碍它奔袭的速度。"
  },
  Stage_8072_Name = {
    Text = "界外之影Ⅰ"
  },
  Stage_8073_Desc = {
    Text = "它们像捉摸不定的魔法师，游走在时空的夹缝里。\n没有仇恨，没有恐惧，也没有怜悯。"
  },
  Stage_8073_Name = {
    Text = "维度残像Ⅴ"
  },
  Stage_8074_Desc = {
    Text = "蠕动着、流淌着……原生质的肿泡正从枷锁的缝隙中溜走。\n这是她为「自由」付出的代价。"
  },
  Stage_8074_Name = {
    Text = "漆黑之链Ⅰ"
