  },
  Stage_8097_Name = {
    Text = "维度残像Ⅲ"
  },
  Stage_80984_Name = {
    Text = "催眠妖虫试玩关卡"
  },
  Stage_8098_Desc = {
    Text = "她以己身承纳圣骸，以教义训导眷众，以毒牙布散信仰。"
  },
  Stage_8098_Name = {
    Text = "虔诚之握Ⅳ"
  },
  Stage_8099_Desc = {
    Text = "早在群星诞生之前，它们便存在于此。\n它们既是虚无，也是一切。"
  },
  Stage_8099_Name = {
    Text = "浑浊残像Ⅱ"
  },
  Stage_8100_Desc = {
    Text = "它们无言地守护着海洋的秘密，灵魂和宇宙一样深沉。"
  },
  Stage_8100_Name = {
    Text = "海渊残像Ⅳ"
  },
  Stage_8101_Desc = {
    Text = "它们在黑暗中扭曲、融合，然后被小心翼翼地保管在造像里。\n这是一次蓄谋已久的重逢。"
  },
  Stage_8101_Name = {
    Text = "超维之旅·间隙Ⅵ"
  },
  Stage_8102_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_8102_Name = {
    Text = "深海之遗·轮转间隙Ⅰ"
  },
  Stage_8103_Name = {
    Text = "海之使徒试玩关卡"
  },
  Stage_8104_Desc = {
    Text = "罗杰斯蜡像馆坐落在南华克街的最深处，靠近泰姆河的支流。\n它毫不起眼，却有众多先锋艺术爱好者慕名而来。"
  },
  Stage_8104_Name = {
    Text = "狂躁蜡馆Ⅲ"
  },
  Stage_8105_Desc = {
    Text = "怎会有永恒不落的夕阳？"
  },
  Stage_8105_Name = {Text = "日落"},
  Stage_8106_Desc = {
    Text = "锋锐的利刺打破绝对的圆弧，并非“刻耳柏洛斯”之物自裂隙生出。"
  },
  Stage_8106_Name = {
    Text = "壳中裂缝"
  },
  Stage_8107_Desc = {
    Text = "是什么蒙蔽了她的双眼？\n是爱、怜悯、正义和过分的感恩吗？"
  },
  Stage_8107_Name = {Text = "超脱"},
  Stage_8108_Desc = {
    Text = "它们像捉摸不定的魔法师，游走在时空的夹缝里。\n没有仇恨，没有恐惧，也没有怜悯。"
  },
  Stage_8108_Name = {
    Text = "维度残像Ⅳ"
  },
  Stage_8109_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_8109_Name = {
    Text = "深海之遗·轮转间隙Ⅰ"
  },
  Stage_8110_Desc = {
    Text = "追溯地狱犬“刻耳柏洛斯”的流言，弥萨格的调查员们来到伦蒂尼恩远郊的小镇拉伊，探寻失踪案背后的隐秘……"
  },
  Stage_8110_Name = {
    Text = "三思而后行"
  },
  Stage_8111_Desc = {
    Text = "一个好消息，一个坏消息。消失的线索不会重现，但新的案件已在暗中酝酿。相信吧，调查员不会再两手空空。"
  },
  Stage_8111_Name = {
    Text = "好消息，坏消息"
  },
  Stage_8112_Desc = {
    Text = "谜一般的水仙夫人。"
  },
  Stage_8112_Name = {
    Text = "你好，达芙黛尔夫人"
  },
  Stage_8113_Desc = {
    Text = "癫狂的语调，浓烈的腥气，这就是来自拉伊的欢迎仪式。"
  },
  Stage_8113_Name = {
    Text = "欢迎来到拉伊"
  },
  Stage_8114_Desc = {
    Text = "人类的腿脚无法胜过敏捷的四足野生生物，但头脑可以。只是，在捕获“地狱犬”之后，等待着你们的又是什么呢？"
  },
  Stage_8114_Name = {
    Text = "袖中王牌"
  },
  Stage_8115_Desc = {
    Text = "达芙黛尔请来了你们的“答案”，新的棋子迈入棋盘，带来关于风雪的梦境。"
  },
  Stage_8115_Name = {
    Text = "芒刺在背"
  },
  Stage_8116_Desc = {
    Text = "祝您旅途愉快。"
  },
  Stage_8116_Name = {
    Text = "旅途愉快"
  },
  Stage_8117_Desc = {
    Text = "在地铁内，你们遭到了神秘刺客的袭击……"
  },
  Stage_8117_Name = {
    Text = "人生无友"
  },
  Stage_81181_Desc = {
    Text = "人们打造出无数凡俗的铜与铁，用于丈量星辰的轨迹。\n在空无一物的大海上，星辰永远是最正确的明灯。"
  },
