  },
  Stage_8125_Name = {Text = "病"},
  Stage_8126_Desc = {
    Text = "你与拉蒙娜前往伦蒂尼恩东区的莉莉安济贫院，展开你作为新晋守密人的第一次调查。\n一切都会很顺利，对吧？"
