    Text = "人不可貌相"
  },
  Stage_8127_Desc = {
    Text = "幽灵藏于幽暗之处——地底或是人心。"
  },
  Stage_8127_Name = {
    Text = "地下的幽灵"
  },
  Stage_8128_Desc = {
    Text = "没有供给呼吸的氧气，没有火柴般微弱的光亮，这里是绝对的漆黑之梦。"
  },
  Stage_8128_Name = {
    Text = "漆黑之梦"
  },
