  },
  Stage_8138_Desc = {
    Text = "一堆粗鲁的、未消化的物质。人们称其为排泄物，或是混沌。 \n世界从排泄物中诞生。"
  },
  Stage_8138_Name = {
    Text = "混沌集群Ⅱ"
  },
  Stage_8139_Desc = {
    Text = "蠕动着、流淌着……原生质的肿泡正从枷锁的缝隙中溜走。\n这是她为「自由」付出的代价。"
  },
  Stage_8139_Name = {
    Text = "漆黑之链Ⅳ"
  },
  Stage_8140_Desc = {
    Text = "它们在黑暗中扭曲、融合，然后被小心翼翼地保管在造像里。\n这是一次蓄谋已久的重逢。"
  },
  Stage_8140_Name = {
    Text = "混沌之域·间隙Ⅴ"
  },
  Stage_8141_Desc = {
    Text = "这里沉睡着一座古老城市的废墟。\n它和它的主人一样嗜睡。"
  },
  Stage_8141_Name = {
    Text = "波纳佩之墟Ⅲ"
  },
  Stage_8142_Desc = {
    Text = "是什么蒙蔽了她的双眼？\n是爱、怜悯、正义和过分的感恩吗？"
  },
  Stage_8142_Name = {Text = "超脱"},
  Stage_8143_Desc = {
    Text = "锋锐的利刺打破绝对的圆弧，并非“刻耳柏洛斯”之物自裂隙生出。"
  },
  Stage_8143_Name = {
    Text = "壳中裂缝"
  },
  Stage_8144_Desc = {
    Text = "怎会有永恒不落的夕阳？"
  },
  Stage_8144_Name = {Text = "日落"},
  Stage_8145_Desc = {
    Text = "「手」掀开夜的帷幕，悄悄来到这个世界。"
  },
  Stage_8145_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_8146_Desc = {
    Text = "来历不明的造像在黑暗中游荡、战栗。\n它们踏着古老的节拍，循着来自远方的笛声起舞。"
  },
  Stage_8146_Name = {
    Text = "深海之遗·间隙Ⅱ"
  },
  Stage_8147_Desc = {
    Text = "吧唧咕叽，裂开了。\n吧唧咕叽，断掉了。"
  },
  Stage_8147_Name = {Text = "娃娃馆"},
  Stage_8148_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_8148_Name = {
    Text = "混沌之域·轮转间隙Ⅳ"
  },
  Stage_8149_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_8149_Name = {
    Text = "混沌之域·轮转间隙Ⅳ"
  },
  Stage_8150_Desc = {
    Text = "「门」已被开启，幻梦即将清醒。\n嘘……不可注视，不可谛听。"
  },
  Stage_8150_Name = {
    Text = "混沌之域·轮转间隙Ⅳ"
  },
  Stage_8151_Desc = {
    Text = "既视感与现实正在将守密人撕成两半，一半留给记忆，一半留在眼前。"
  },
  Stage_8151_Name = {Text = "匕首"},
  Stage_8152_Desc = {
    Text = "夜晚的港口，淳朴的居民，热情的款待。"
  },
  Stage_8152_Name = {
    Text = "十面埋伏"
  },
  Stage_8153_Desc = {
    Text = "老套的开局：落单的失忆守密人。\n不同的是，这次是在孤独的大海上醒来。"
  },
  Stage_8153_Name = {Text = "风暴眼"},
  Stage_8154_Desc = {
    Text = "跨越诸海之使徒。"
  },
  Stage_8154_Name = {Text = "使徒"},
  Stage_8155_Desc = {
    Text = "在一艘船上，除了船长，还有谁是值得相信的呢？"
  },
  Stage_8155_Name = {Text = "船员"},
  Stage_8156_Desc = {
    Text = "退无可退之时，训练有素的伙伴往往是破局的关键——拉蒙娜再次教会了你这点。"
  },
  Stage_8156_Name = {
    Text = "无路可逃"
  },
  Stage_8157_Desc = {
    Text = "踏破诸海而过的，除了敌人，或许还有希望的微光。"
  },
  Stage_8157_Name = {
    Text = "沉溺之徒"
  },
  Stage_8158_Desc = {
    Text = "那是意图斩破海洋之人的巨刃，是意图踏平诸海之人的野心。"
  },
  Stage_8158_Name = {
    Text = "狂徒与巨刃"
  },
  Stage_8159_Desc = {
    Text = "那是她萦绕不散的一场噩梦，也是纠缠她一生的扭曲现实。"
  },
  Stage_8159_Name = {
    Text = "扭曲的现实"
  },
  Stage_8160_Desc = {
    Text = "它们在黑暗中扭曲、融合，然后被小心翼翼地保管在造像里。\n这是一次蓄谋已久的重逢。"
  },
  Stage_8160_Name = {
    Text = "超维之旅·间隙Ⅴ"
  },
  Stage_8161_Desc = {
    Text = "伦蒂尼恩以灿烂的工业文明，以及笼罩市区的铅灰色浓雾闻名。\n雾气无处不在，对路人来说是更像是一种偶然、无意义的不便。"
  },
  Stage_8161_Name = {
    Text = "怪雾之都Ⅳ"
  },
  Stage_8162_Desc = {
    Text = "潜藏在宇宙深处的弯曲视界。 \n它能带你从黑暗抵达另一处黑暗。"
  },
  Stage_8162_Name = {
    Text = "史瓦西喉Ⅳ"
  },
  Stage_8163_Desc = {
    Text = "虚无乃吾等之源头，亦为吾等之归宿。"
  },
  Stage_8163_Name = {
    Text = "不朽的低语"
  },
  Stage_8164_Desc = {
    Text = "荒芜的铁路桥下，庞大臃肿的怪物发出古怪的低吼。要抵达拉伊疯人院，就必须跨过这里。"
  },
  Stage_8164_Name = {
    Text = "船到桥头自然直"
  },
  Stage_8165_Desc = {
    Text = "艾尔沃斯位于卡达斯的极点，终年被不融的冰雪覆盖，\n厚实而坚硬的冰壳下，隐约潜藏着生命的搏动。"
  },
  Stage_8165_Name = {
    Text = "失序山脉Ⅰ"
  },
  Stage_8166_Desc = {
    Text = "来历不明的造像在黑暗中游荡、战栗。\n它们踏着古老的节拍，循着来自远方的笛声起舞。"
  },
  Stage_8166_Name = {
    Text = "混沌之域·间隙Ⅷ"
  },
  Stage_8167_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_8167_Name = {
    Text = "幻梦深潜Ⅳ"
  },
  Stage_8168_Desc = {
    Text = "「门」即将开启，你从中窥见一部分真理。\n不是黑色，也不是白色——真理是彩色的，也是浑浊的。"
  },
  Stage_8168_Name = {
    Text = "血肉之沼·间隙Ⅲ"
  },
  Stage_8169_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_8169_Name = {
    Text = "幻梦深潜Ⅵ"
  },
  Stage_8170_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_8170_Name = {
    Text = "幻梦深潜Ⅶ"
  },
  Stage_8171_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_8171_Name = {
    Text = "幻梦深潜Ⅰ"
  },
  Stage_8172_Desc = {
    Text = "「它是唯一，它是全部，它是开启真相之门的希望。」\n无数钥匙围成了一个圈。它们自天空中坠落，带给人们沉甸甸的希望。\n也带来沉甸甸的坟墓。"
  },
  Stage_8172_Name = {
    Text = "幻梦深潜Ⅱ"
  },
  Stage_8173_Desc = {
    Text = "来历不明的造像在黑暗中游荡、战栗。\n它们踏着古老的节拍，循着来自远方的笛声起舞。"
  },
  Stage_8173_Name = {
    Text = "超维之旅·间隙Ⅱ"
  },
  Stage_8174_Desc = {
    Text = "他不会是祂，祂不可能是他。\n没错……没错，只有我的神明，才是真正的他。"
  },
  Stage_8174_Name = {
    Text = "失落之光"
  },
  Stage_81757_Desc = {
    Text = "光辉的神国逐渐显现于你裂开的眼瞳里。\n在那里，你将获得应许，拥有一切。"
  },
  Stage_81757_Name = {
    Text = "神国的低喃"
  },
  Stage_81758_Desc = {
    Text = "通过那象牙的雕塑，祂的目光降落人世间。\n从此， 你我都沉沦于祂的意志中。"
  },
  Stage_81758_Name = {
    Text = "圣象的注视"
  },
  Stage_81759_Desc = {
    Text = "无垠的宇宙在你的体内汇聚，犹如群星奔向正位之刻。\n响应这来自虚空的召唤吧！祂的子嗣。祂的傀儡。"
  },
  Stage_81759_Name = {
    Text = "虚空的召唤"
  },
  Stage_8175_Desc = {
    Text = "现实埋下了祸种，命运却指引着相遇。"
  },
  Stage_8175_Name = {
    Text = "命运的种子"
  },
  Stage_81760_Desc = {
    Text = "虚幻与现实的罅隙，祭礼已经开始。\n欢呼吧，呐喊吧，你的喜悦与痛苦将穿越维度，成为神国降临的颂乐。"
  },
  Stage_81760_Name = {
    Text = "祭礼的回应"
  },
  Stage_81761_Desc = {
    Text = "一切的狂喜已经过去。\n你拖着分裂的身躯，伸出触手，对世界发出觉醒后的第一声恐怖而亵渎的嘶吼。\n\n「神国终将降临。」"
  },
  Stage_81761_Name = {
    Text = "无妄的皈依"
  },
  Stage_81762_Desc = {
    Text = "啊，倾听这混沌的声音，倾听这无尽的幻乐。\n神已经降下了圣谕，而你作为祂的子嗣与傀儡，将忠诚执行到底。"
  },
  Stage_81762_Name = {
    Text = "神王的圣谕"
  },
  Stage_81763_Desc = {
    Text = "加速的心跳只是血肉悸动的前兆。\n不必恐慌，那只是你的血脉在觉醒的声音。"
  },
  Stage_81763_Name = {
    Text = "躯壳的悸动"
  },
  Stage_8176_Desc = {
    Text = "第二颗心脏在墨菲体内跳动着，阻止「降生仪式」迫在眉睫。"
  },
  Stage_8176_Name = {
    Text = "另一个奇迹"
  },
  Stage_8177_Desc = {
    Text = "突出重围永远不简单，但好在，这一次守密人找到了最亮的恒星。"
  },
  Stage_8177_Name = {
    Text = "追逐繁星"
  },
  Stage_81781_Desc = {
    Text = "不可见的灾难复苏，物理世界的历史与存在正在坠入深渊。"
  },
  Stage_81781_Name = {
    Text = "融灾禁区·第3波·癫狂"
  },
  Stage_81782_Desc = {
    Text = "不可见的灾难复苏，物理世界的历史与存在正在坠入深渊。"
  },
  Stage_81782_Name = {
    Text = "融灾禁区·第2波·癫狂"
  },
  Stage_81783_Desc = {
    Text = "不可见的灾难复苏，物理世界的历史与存在正在坠入深渊。"
  },
  Stage_81783_Name = {
    Text = "融灾禁区·第1波·癫狂"
  },
  Stage_81784_Desc = {
    Text = "不可见的灾难复苏，物理世界的历史与存在正在坠入深渊。"
  },
  Stage_81784_Name = {
    Text = "融灾禁区·第5波·癫狂"
  },
  Stage_81785_Desc = {
    Text = "不可见的灾难复苏，物理世界的历史与存在正在坠入深渊。"
  },
  Stage_81785_Name = {
    Text = "融灾禁区·第4波·癫狂"
  },
  Stage_81786_Desc = {
    Text = "漆黑的潮水漫过警戒界限，轻微的波动亦昭示着足以吞噬掉以轻心者的险恶。"
  },
  Stage_81786_Name = {
    Text = "融灾禁区·第4波·Ⅰ级警报"
  },
  Stage_81787_Desc = {
    Text = "不可见的灾难复苏，物理世界的历史与存在正在坠入深渊。"
  },
  Stage_81787_Name = {
