  },
  Stage_81788_Name = {
    Text = "融灾禁区·第2波·Ⅰ级警报"
  },
  Stage_81789_Desc = {
    Text = "不可见的灾难复苏，物理世界的历史与存在正在坠入深渊。"
  },
  Stage_81789_Name = {
    Text = "融灾禁区·第3波·癫狂"
  },
  Stage_8178_Desc = {
    Text = "人以自身意志改造世界，也以此意志改变自身。"
  },
  Stage_8178_Name = {Text = "决意"},
  Stage_81790_Desc = {
    Text = "黑潮漩涡翻涌，密境险象丛生，深沉的黑暗化为前行者的牢笼。"
  },
  Stage_81790_Name = {
