    Text = "黑潮漩涡翻涌，密境险象丛生，深沉的黑暗化为前行者的牢笼。"
  },
  Stage_83247_Name = {
    Text = "融灾禁区·第4波·困难"
  },
  Stage_83248_Desc = {
    Text = "黑潮漩涡翻涌，密境险象丛生，深沉的黑暗化为前行者的牢笼。"
  },
  Stage_83248_Name = {
    Text = "融灾禁区·第5波·困难"
  },
  Stage_83249_Desc = {
    Text = "漆黑的潮水漫过警戒界限，轻微的波动亦昭示着足以吞噬掉以轻心者的险恶。"
  },
  Stage_83249_Name = {
    Text = "融灾禁区·第5波·普通"
  },
  Stage_83250_Desc = {
    Text = "漆黑的潮水漫过警戒界限，轻微的波动亦昭示着足以吞噬掉以轻心者的险恶。"
  },
  Stage_83250_Name = {
    Text = "融灾禁区·第4波·普通"
  },
  Stage_88880_Desc = {
    Text = "我持着你曾点燃的火。\n你曾引领我的，我将作你的眼，带你重见光明。\n你所行的路，我将替你前进，所有锈蚀的栅栏都将在这火前走向坍塌。"
  },
  Stage_88880_Name = {
    Text = "传烛者·之三"
  },
  Stage_88881_Desc = {
    Text = "一座定格的城，固化了一片文明的标本。"
  },
  Stage_88881_Name = {Text = "标本"},
  Stage_88882_Desc = {
    Text = "他生来便愚笨、迟钝，囿于简单的生活中，盲目又执拗。\n但谁说愚者不能走出一条全新的路？所有禁锢不过是未孵化的风暴，即便他一无所知，仍会用翅膀无畏地飞向未知的天空。"
  },
  Stage_88882_Name = {
    Text = "愚者·癫狂"
  },
  Stage_88883_Desc = {
    Text = "我梦到了久远的旧日。\n那时你指着书中如铺洒在蓝丝绒布上的、深邃的群星，说以后要挑选一个晴朗的夜晚，一同在月亮身旁飞翔，看看天空之上到底有怎样的景象。"
  },
  Stage_88883_Name = {
    Text = "昨日之梦·之六"
  },
  Stage_88884_Desc = {
    Text = "他一直拥有两道影子，如今他将另一道弄丢了。\n他孤单地走在寂静的夜空下，唱起儿时与他一同编撰的歌谣。\n飞鸟，飞鸟，你在哪……\n影子，影子，快回家……"
  },
  Stage_88884_Name = {
    Text = "孤独之旅·之五"
  },
  Stage_88885_Desc = {
    Text = "我持着你曾点燃的火。\n你曾引领我的，我将作你的眼，带你重见光明。\n你所行的路，我将替你前进，所有锈蚀的栅栏都将在这火前走向坍塌。"
  },
  Stage_88885_Name = {
    Text = "传烛者·之四"
  },
  Stage_88886_Desc = {
    Text = "我持着你曾点燃的火。\n你曾引领我的，我将作你的眼，带你重见光明。\n你所行的路，我将替你前进，所有锈蚀的栅栏都将在这火前走向坍塌。"
  },
  Stage_88886_Name = {
    Text = "传烛者·之二"
  },
  Stage_88887_Desc = {
    Text = "若生于笼中，可该天生受缚？\n若深埋地底，偏要破土重生。"
  },
  Stage_88887_Name = {
    Text = "破开囚笼·之五"
  },
  Stage_88888_Desc = {
    Text = "若生于笼中，可该天生受缚？\n若深埋地底，偏要破土重生。"
  },
