  },
  Stage_88891_Desc = {
    Text = "那沙如海，风息时，波涛低伏；风骤时，生灵尽灭。\n他于无尽沙海中，若海燕般不屈地飞翔。"
  },
  Stage_88891_Name = {
    Text = "无尽沙·之一"
  },
  Stage_88892_Desc = {
    Text = "那沙如海，风息时，波涛低伏；风骤时，生灵尽灭。\n他于无尽沙海中，若海燕般不屈地飞翔。"
  },
  Stage_88892_Name = {
    Text = "无尽沙·之六"
  },
  Stage_88893_Desc = {
    Text = "从他睁开了眼，那眼就无法再闭上。\n从他见过了天，那天就始终在心中。\n若那自由需用死亡换取，他便将毫不犹豫地献出自己的生命。"
  },
