  },
  Stage_88901_Desc = {
    Text = "他熟练地解开身上的镣铐，向着牢笼之外不断奔跑。他记得每一次转弯、每一个暗哨，为此他已经准备了太久太久，毕竟，这已不是他的第一次出逃。"
  },
  Stage_88901_Name = {Text = "奔逃"},
  Stage_88902_Desc = {
    Text = "从他睁开了眼，那眼就无法再闭上。\n从他见过了天，那天就始终在心中。\n若那自由需用死亡换取，他便将毫不犹豫地献出自己的生命。"
  },
  Stage_88902_Name = {
    Text = "自由与死亡·之四"
  },
  Stage_88903_Desc = {
    Text = "你可以关住一只鸟，但无法关住一颗自由的心。"
  },
  Stage_88903_Name = {
    Text = "飞鸟之心"
  },
