  },
  Stage_88932_Name = {
    Text = "愚者·之五"
  },
  Stage_89731_Desc = {
    Text = "那滴缓缓坠下的泪啊，晶莹如纯洁的冰花。"
  },
  Stage_89731_Name = {Text = "一滴泪"},
  Stage_89732_Desc = {
    Text = "奔跑、躲藏、追踪、拉扯，猎人已举起了黑洞洞的枪口。"
  },
  Stage_89732_Name = {Text = "围猎"},
  Stage_90490_Desc = {
    Text = "于混沌中诞生的唤醒体与你站在一起，你的银钥发出亢奋的颤鸣。\n与他们一起战斗，掌握激发银钥潜能的方法。"
  },
  Stage_90490_Name = {
    Text = "混沌之念"
  },
  Stage_90662_Desc = {
    Text = "当墓园的钟声奏响，弥漫的黑雾将于梦境中消散。\n推开沉重的棺木吧，那宏伟的王城，已降临你身前。"
  },
  Stage_90662_Name = {
    Text = "梦境之下"
  },
  Stage_90663_Desc = {
    Text = "聆听吧，这海洋的恸哭。\n信徒们虔诚地恳求。恳求主回应他们的祷告，恳求主恩赏他们的血。"
  },
  Stage_90663_Name = {Text = "血祭"},
  Stage_90664_Desc = {
    Text = "「沉眠于此地的尸骨，游荡于夜空的魂灵啊——\n以食尸鬼之王、葬骸城之主的名，我将邀请你们，重新回到你们眷恋的土地。\n我将邀请你们与我一同，享用这敌人赠予的餍飨！」"
  },
  Stage_90664_Name = {
    Text = "万灵之舞"
  },
  Stage_90665_Desc = {
    Text = "长相厮守的誓言，早在竭诚尽忠之前。"
  },
  Stage_90665_Name = {Text = "誓言"},
  Stage_90666_Desc = {
    Text = "罪孽？阴谋？死亡？\n画家无暇关心这些。他的眼里，只有尸体们所构成的宏伟图景。"
  },
  Stage_90666_Name = {Text = "画家"},
  Stage_90667_Desc = {
    Text = "长相厮守的誓言，早在竭诚尽忠之前。"
  },
  Stage_90667_Name = {Text = "誓言"},
  Stage_90670_Desc = {
    Text = "在葬骸城君主的所有品质中，对美食的品味至关重要。"
  },
  Stage_90670_Name = {
    Text = "王与尸体烹饪艺术"
  },
  Stage_90671_Desc = {
    Text = "一位血亲的记忆。一个城邦王室的故事。一段沉重恢弘的历史。\n一位平民的记忆。一个平凡家族的故事。一条可有可无的注脚。\n对于葬骸城的王来说，它们不应、也不会有任何区别。"
  },
  Stage_90671_Name = {
    Text = "卑微的注脚"
  },
  Stage_90672_Desc = {
    Text = "「弦乐已升上中天，一切繁文缛节都已随雾色消散。\n我亲爱的臣民们，欢呼吧。撕开裹尸布下的伪善，露出那原始的饥渴之相。\n今夜，诗人的喉管将为我们吟诵。\n今夜，母亲的双臂将拥我们入怀。」"
  },
  Stage_90672_Name = {
    Text = "月光、骸骨与舞"
  },
  Stage_90674_Desc = {
    Text = "他是葬骸城的君王。他是这场宴会的主人。\n他向所有宾客张开双臂，邀请他们离开舞池。\n墓园遍地的尸骸上，他与深渊共舞。"
  },
  Stage_90674_Name = {
    Text = "葬骸之主"
  },
  Stage_90676_Desc = {
    Text = "当墓园的钟声奏响，弥漫的黑雾将于梦境中消散。\n推开沉重的棺木吧，那宏伟的王城，已降临你身前。"
  },
  Stage_90676_Name = {
    Text = "梦境之下"
  },
  Stage_90679_Desc = {
    Text = "在葬骸城君主的所有品质中，对美食的品味至关重要。"
  },
  Stage_90679_Name = {
    Text = "王与尸体烹饪艺术"
  },
  Stage_90680_Desc = {
    Text = "梦里的声音，湮没的文明，故友的踪迹……\n你想知晓的一切，在远海之上等待着你。"
  },
  Stage_90680_Name = {
    Text = "远海之上"
  },
  Stage_90681_Desc = {
    Text = "聆听吧，这海洋的恸哭。\n信徒们虔诚地恳求。恳求主回应他们的祷告，恳求主恩赏他们的血。"
  },
  Stage_90681_Name = {Text = "血祭"},
  Stage_90684_Desc = {
    Text = "眼前这个苍老的食尸鬼是谁？他为何衣衫破烂？他为何泪流满面？\n他为何痛哭着，用最温和、最嘶哑的声音，呼唤着那个叫做伊莱娜的名字？\n她什么也想不起来。\n月光落在她的尸体上，美得如同婚礼那天，她身上随风翕动的纱幔。"
  },
  Stage_90684_Name = {
    Text = "婚纱与葬礼"
  },
  Stage_90685_Desc = {
    Text = "眼前这个苍老的食尸鬼是谁？他为何衣衫破烂？他为何泪流满面？\n他为何痛哭着，用最温和、最嘶哑的声音，呼唤着那个叫做伊莱娜的名字？\n她什么也想不起来。\n月光落在她的尸体上，美得如同婚礼那天，她身上随风翕动的纱幔。"
  },
  Stage_90685_Name = {
    Text = "婚纱与葬礼"
  },
  Stage_90686_Desc = {
    Text = "一位血亲的记忆。一个城邦王室的故事。一段沉重恢弘的历史。\n一位平民的记忆。一个平凡家族的故事。一条可有可无的注脚。\n对于葬骸城的王来说，它们不应、也不会有任何区别。"
  },
  Stage_90686_Name = {
    Text = "卑微的注脚"
  },
  Stage_90687_Desc = {
    Text = "他是葬骸城的君王。他是这场宴会的主人。\n他向所有宾客张开双臂，邀请他们离开舞池。\n墓园遍地的尸骸上，他与深渊共舞。"
  },
  Stage_90687_Name = {
    Text = "葬骸之主"
  },
  Stage_90689_Desc = {
