  },
  Stage_90690_Name = {
    Text = "万灵之舞"
  },
  Stage_90691_Desc = {
    Text = "「弦乐已升上中天，一切繁文缛节都已随雾色消散。\n我亲爱的臣民们，欢呼吧。撕开裹尸布下的伪善，露出那原始的饥渴之相。\n今夜，诗人的喉管将为我们吟诵。\n今夜，母亲的双臂将拥我们入怀。」"
  },
  Stage_90691_Name = {
    Text = "月光、骸骨与舞"
  },
  Stage_90985_Desc = {
    Text = "所有阻拦者将恐惧匍匐，所有光辉尽归于罗马。\n那洁白的花冠与月桂叶，将戴在最勇猛的战士头上。"
  },
  Stage_90985_Name = {
    Text = "勇士桂冠·之五"
  },
  Stage_90986_Desc = {
    Text = "欢呼声与鲜花、美酒与盛宴、黄金与珍宝。\n享受吧，大笑吧，这是勇士应得的荣耀！"
  },
  Stage_90986_Name = {
    Text = "荣耀凯旋·之五"
  },
  Stage_90987_Desc = {
    Text = "所有阻拦者将恐惧匍匐，所有光辉尽归于罗马。\n那洁白的花冠与月桂叶，将戴在最勇猛的战士头上。"
  },
  Stage_90987_Name = {
    Text = "勇士桂冠·之二"
  },
  Stage_90988_Desc = {
    Text = "无论猎物藏在何处，专业的猎手都将嗅到那甘美的香味。"
  },
  Stage_90988_Name = {
    Text = "凶猛猎手·癫狂"
  },
  Stage_90989_Desc = {
    Text = "征服的号角吹响，战士们已踏上征程。\n我们前进，我们不可抵挡，我们必将胜利。"
  },
  Stage_90989_Name = {
    Text = "远征号角·之二"
  },
  Stage_90990_Desc = {
    Text = "征服的号角吹响，战士们已踏上征程。\n我们前进，我们不可抵挡，我们必将胜利。"
  },
  Stage_90990_Name = {
    Text = "远征号角·之四"
  },
  Stage_90991_Desc = {
    Text = "我承认我们过去有些嫌隙，但这并不妨碍我们暂时共同将矛头指向这个可恶的、可恨的、卑鄙的现代科技。"
  },
  Stage_90991_Name = {
    Text = "合作智慧·之五"
  },
