  Stage_91018_Name = {
    Text = "勇士桂冠·之六"
  },
  Stage_91019_Desc = {
    Text = "欢呼声与鲜花、美酒与盛宴、黄金与珍宝。\n享受吧，大笑吧，这是勇士应得的荣耀！"
  },
  Stage_91019_Name = {
    Text = "荣耀凯旋·之六"
  },
  Stage_91088_Desc = {
    Text = "他们是主仆、是凶手与死者、是同一片废墟的遗物。\n循着血脉的饥渴，他们在同一扇门前不期而遇。"
  },
  Stage_91088_Name = {
    Text = "奴隶与奴隶主"
  },
  Stage_91091_Desc = {
    Text = "谁说旧日的荣光不可归来？\n看着吧，可恶的现代科技，罗马的力量终将战胜一切！"
  },
  Stage_91091_Name = {
    Text = "罗马的力量"
  },
  Stage_94464_Desc = {
    Text = "来自深海的唤醒体，带着潜藏于海底的伟力来到你面前。\n与他们一起战斗，掌握使用触腕力量的方法。"
  },
  Stage_94464_Name = {
    Text = "深海之触"
  },
  Stage_94465_Desc = {
    Text = "血肉是生命的本初，亦是生命的终结。死即为生，由纯粹血肉所构筑的唤醒体们最清楚这一点。\n与他们一起战斗，掌握驾驭血肉之力的方法。"
  },
  Stage_94465_Name = {
    Text = "血肉之殖"
  },
  Stage_94466_Desc = {
    Text = "于超维中穿行的唤醒体们并不完全了解这片空间的秘密，在你解开它们的那一天，你将窥见令你惊异的力量。\n与他们一起战斗，掌握利用超维空间进行战斗的方法。"
  },
  Stage_94466_Name = {
    Text = "超维之域"
  },
  Stage_94806_Desc = {
    Text = "美好的假日怎么能被粗鲁和暴力所破坏，要打，就在排球场上一决胜负吧！"
  },
  Stage_94806_Name = {
    Text = "文明决斗"
  },
  Stage_94808_Desc = {
    Text = "既然作为冠军，总该有一些小小的特权。"
  },
  Stage_94808_Name = {
    Text = "冠军与大乱斗"
  },
  Stage_94811_Desc = {
    Text = "要拿下第一名的人，怎么会在同一个地方跌倒两次！"
  },
  Stage_94811_Name = {
    Text = "决胜一球"
  },
  Stage_94817_Desc = {
    Text = "人们习惯用规则控制不可避免的熵增。事实上每一个人都有自己的原则，而当几十个原则碰撞在一起，这里最终的原则就会变成——没有原则！"
  },
  Stage_94817_Name = {
    Text = "配对原则"
  },
  Stage_94824_Desc = {
    Text = "静谧的夜晚，柔和的海风，在群星温柔的照耀下，总是适合吐露一些秘密的心事。"
  },
  Stage_94824_Name = {
    Text = "只有夜风知道"
  },
  Stage_94832_Desc = {
    Text = "她的心中清楚地知晓：一腔孤勇不能换来无可匹敌的胜利，过去如此，现在依然。"
  },
  Stage_94832_Name = {Text = "险胜"},
  Stage_94837_Desc = {
    Text = "如果这一刻的欢乐能够定格，我希望那份记忆的期限是永远。"
  },
  Stage_94837_Name = {
    Text = "一张照片"
  },
  Stage_94841_Desc = {
    Text = "海滨即是假日的标准答案，酷暑之下，谁能拒绝踩着清凉的浪花，于遮阳伞下躲避烈日的炙烤呢？等等……为什么太阳会掉下来啊？！"
  },
  Stage_94841_Name = {
    Text = "高温预警"
  },
  Stage_94843_Desc = {
    Text = "在激昂的赛场上，每位选手都将一展自己的风采……导播，把那些无法播出的风采统统掐掉。"
  },
  Stage_94843_Name = {
    Text = "开始吧！半决赛！"
  },
  Stage_95332_Desc = {
