  Stage_95379_Name = {
    Text = "覆世之光·之五"
  },
  Stage_95380_Desc = {
    Text = "祂没有带走声音，因为祂想聆听负罪者置身于炼狱中的哀嚎。\n亿万光点于极昼中起舞、共鸣，它们的声音伴随着那哀嚎，于炼狱中交织成完美的歌。"
  },
  Stage_95380_Name = {
    Text = "炼狱之歌·之五"
  },
  Stage_95706_Desc = {
    Text = "那些的凄苦的、美丽的、承载了太多记忆的灵魂，正是每道食材独一无二的缘由。\n让每个层次，与你的舌尖对抗、厮杀，然后你们融为一体。\n——每个亡者终其一生所等待的，是被吞食的这一刻。"
  },
  Stage_95706_Name = {
    Text = "灵龛盛筵·之六"
  },
  Stage_95707_Desc = {
    Text = "0.5英寸的深度，和经络的方向垂直。\n沿着脖脊与扇骨，将骨与肉分离。\n身躯，即是烹饪者的棋盘。"
  },
  Stage_95707_Name = {
    Text = "骨血剥离·之六"
  },
  Stage_95708_Desc = {
    Text = "闻到了么？橡木、雪松与香根草带来的清香。\n它的主人在这美丽的棺木里躺了三百年。\n由此，它获得了成为这场宴席主菜的殊荣。"
  },
  Stage_95708_Name = {
    Text = "沉棺开启·之六"
  },
  Stage_95709_Desc = {
    Text = "闻到了么？橡木、雪松与香根草带来的清香。\n它的主人在这美丽的棺木里躺了三百年。\n由此，它获得了成为这场宴席主菜的殊荣。"
  },
  Stage_95709_Name = {
    Text = "沉棺开启·之二"
  },
  Stage_95710_Desc = {
    Text = "盐粒。欧芹。香茅。橄榄。迷迭香。\n一个忠告：无论再好的食材，也永远不要轻视香料。\n在这棋盘之上，香料便是烹饪者的棋子。"
  },
  Stage_95710_Name = {
    Text = "腐殖调香·之三"
  },
  Stage_95711_Desc = {
    Text = "我们歌颂品味与永恒，火焰则是是它们的反义词。\n可这世上最隽永、最美妙的风味，又偏偏来自于火焰。\n一种绝妙的讽刺，不是吗？"
  },
  Stage_95711_Name = {
    Text = "亡焰炙魂·之一"
  },
  Stage_95712_Desc = {
    Text = "0.5英寸的深度，和经络的方向垂直。\n沿着脖脊与扇骨，将骨与肉分离。\n身躯，即是烹饪者的棋盘。"
  },
