    Text = "0.5英寸的深度，和经络的方向垂直。\n沿着脖脊与扇骨，将骨与肉分离。\n身躯，即是烹饪者的棋盘。"
  },
  Stage_95722_Name = {
    Text = "骨血剥离·之四"
  },
  Stage_95723_Desc = {
    Text = "0.5英寸的深度，和经络的方向垂直。\n沿着脖脊与扇骨，将骨与肉分离。\n身躯，即是烹饪者的棋盘。"
  },
  Stage_95723_Name = {
    Text = "骨血剥离·之二"
  },
  Stage_95724_Desc = {
    Text = "我们歌颂品味与永恒，火焰则是是它们的反义词。\n可这世上最隽永、最美妙的风味，又偏偏来自于火焰。\n一种绝妙的讽刺，不是吗？"
  },
  Stage_95724_Name = {
    Text = "亡焰炙魂·之五"
  },
  Stage_95725_Desc = {
    Text = "那些的凄苦的、美丽的、承载了太多记忆的灵魂，正是每道食材独一无二的缘由。\n让每个层次，与你的舌尖对抗、厮杀，然后你们融为一体。\n——每个亡者终其一生所等待的，是被吞食的这一刻。"
  },
  Stage_95725_Name = {
    Text = "灵龛盛筵·之五"
  },
  Stage_95727_Desc = {
    Text = "闻到了么？橡木、雪松与香根草带来的清香。\n它的主人在这美丽的棺木里躺了三百年。\n由此，它获得了成为这场宴席主菜的殊荣。"
  },
  Stage_95727_Name = {
    Text = "沉棺开启·之五"
  },
  Stage_95728_Desc = {
    Text = "盐粒。欧芹。香茅。橄榄。迷迭香。\n一个忠告：无论再好的食材，也永远不要轻视香料。\n在这棋盘之上，香料便是烹饪者的棋子。"
  },
  Stage_95728_Name = {
    Text = "腐殖调香·之六"
  },
