  },
  Stage_95742_Name = {
    Text = "腐殖调香·之四"
  },
  Stage_97057_Desc = {
    Text = "狂热的舞者围绕着虚妄的偶像旋转，无人问津信仰的残骸，只有欢愉的漩涡在失控中越卷越紧。\n这一刻，所有羞耻与顾忌在狂热的旋转中化为乌有，众生只为幻影而狂舞。 \n皮克曼大笑着，邀请你加入这狂热的舞蹈。"
  },
  Stage_97057_Name = {
    Text = "金牛疯舞·之四"
  },
  Stage_97058_Desc = {
    Text = "灵感，是甘于平庸者的禁果。\n而在此画卷之上，夸张的构图昭示着艺术的真谛。\n灵感如疾风骤雨降临，无需邀请便闯入心房。\n那一刻，潜藏的不安与渴望悉数觉醒，像洞穿黑夜的火光，把内心照得通透又炽热。"
  },
  Stage_97058_Name = {
    Text = "灵感侵染·之三"
  },
  Stage_97059_Desc = {
    Text = "有谁见过如此疯狂的线条？\n每一道轨迹都挣脱了透视法则的锁链，像暴动的囚徒般在纸面狂奔。\n它们交错、厮杀、互相吞噬，用扭曲的舞蹈绘出皮克曼眼中的真实。"
  },
  Stage_97059_Name = {
    Text = "线魂肆虐·之三"
  },
  Stage_97060_Desc = {
    Text = "有谁见过如此疯狂的线条？\n每一道轨迹都挣脱了透视法则的锁链，像暴动的囚徒般在纸面狂奔。\n它们交错、厮杀、互相吞噬，用扭曲的舞蹈绘出皮克曼眼中的真实。"
  },
  Stage_97060_Name = {
    Text = "线魂肆虐·之五"
  },
  Stage_97061_Desc = {
    Text = "平凡的画家？不，不。\n鲜红的笔触翻涌而出，诡异的涡流迅速将苍白与清明淹没。\n明艳与阴郁交织的赤色蔓延开来，让整幅作品染上躁动与生命的气息。\n只有这血一般的色彩，才是世间最鲜活真实的存在！"
  },
  Stage_97061_Name = {
    Text = "血色蔓延·癫狂"
  },
  Stage_97062_Desc = {
    Text = "平凡的画家？不，不。\n鲜红的笔触翻涌而出，诡异的涡流迅速将苍白与清明淹没。\n明艳与阴郁交织的赤色蔓延开来，让整幅作品染上躁动与生命的气息。\n只有这血一般的色彩，才是世间最鲜活真实的存在！"
  },
  Stage_97062_Name = {
    Text = "血色蔓延·之二"
  },
  Stage_97063_Desc = {
    Text = "狂热的舞者围绕着虚妄的偶像旋转，无人问津信仰的残骸，只有欢愉的漩涡在失控中越卷越紧。\n这一刻，所有羞耻与顾忌在狂热的旋转中化为乌有，众生只为幻影而狂舞。 \n皮克曼大笑着，邀请你加入这狂热的舞蹈。"
  },
  Stage_97063_Name = {
    Text = "金牛疯舞·之五"
  },
  Stage_97064_Desc = {
    Text = "灵感，是甘于平庸者的禁果。\n而在此画卷之上，夸张的构图昭示着艺术的真谛。\n灵感如疾风骤雨降临，无需邀请便闯入心房。\n那一刻，潜藏的不安与渴望悉数觉醒，像洞穿黑夜的火光，把内心照得通透又炽热。"
  },
  Stage_97064_Name = {
    Text = "灵感侵染·之四"
  },
  Stage_97065_Desc = {
    Text = "未知的苦难在色彩深处咆哮。残酷的景象浮现，彼岸的烈焰、扭曲的影子拥挤着相互缠绕。\n此时的画布成了罪与罚的囚牢，每一寸都闪烁着炽烈的惩戒与痛苦。\n世界已然颠倒，一切良善覆没，在燃烧与苦难的地狱中揭示出灵魂的真相。\n看到了吗？这才是艺术之美。"
  },
  Stage_97065_Name = {
    Text = "地狱之变·之五"
  },
  Stage_97066_Desc = {
    Text = "灵魂在画布上熊熊燃烧，清透的光油缓慢流淌，血色定格为永恒的世界，疯癫才是真实的酒酿。\n唯有舍弃世俗的清醒，冲进混沌的极乐，才终于触及了艺术本身。\n啊，我愿永恒地沉沦在这终极的狂喜与绝望！ \n来吧，于这癫狂的盛宴后，迎来美丽的新世界。"
  },
  Stage_97066_Name = {
    Text = "狂欢定格·癫狂"
  },
  Stage_97067_Desc = {
    Text = "平凡的画家？不，不。\n鲜红的笔触翻涌而出，诡异的涡流迅速将苍白与清明淹没。\n明艳与阴郁交织的赤色蔓延开来，让整幅作品染上躁动与生命的气息。\n只有这血一般的色彩，才是世间最鲜活真实的存在！"
  },
  Stage_97067_Name = {
    Text = "血色蔓延·之三"
  },
  Stage_97068_Desc = {
    Text = "皮克曼狂躁的笔触翻搅油彩，画笔沾满血肉与灵魂的苦涩。\n乱神般的轨迹在画布上蜿蜒，梦魇与幻象悄然浮现于色彩的深渊。\n画中世界，在这场失控的迷离中逐渐扭曲、沉沦……"
  },
