  Stage_97104_Name = {
    Text = "梦魇堆垒·之六"
  },
  Stage_97105_Desc = {
    Text = "未知的苦难在色彩深处咆哮。残酷的景象浮现，彼岸的烈焰、扭曲的影子拥挤着相互缠绕。\n此时的画布成了罪与罚的囚牢，每一寸都闪烁着炽烈的惩戒与痛苦。\n世界已然颠倒，一切良善覆没，在燃烧与苦难的地狱中揭示出灵魂的真相。\n看到了吗？这才是艺术之美。"
  },
  Stage_97105_Name = {
    Text = "地狱之变·之四"
  },
  Stage_97227_Desc = {
    Text = "祭品已至，鲜血盈满，端坐于寰宇的至高之主啊！请接您的信者前往永恒的国！"
  },
  Stage_97227_Name = {Text = "血祭"},
  Stage_97228_Desc = {
    Text = "黑日降临了，不是么？"
  },
  Stage_97228_Name = {Text = "黑日"},
  Stage_97229_Desc = {
    Text = "背叛恰到好处的发生了，「遭人蛊惑」、「迫不得已」、「为了生存」，多么完美的背叛理由啊。\n可惜，它挑错了背叛的对象。"
  },
  Stage_97229_Name = {
    Text = "背叛之音"
  },
  Stage_97230_Desc = {
    Text = "谜底揭晓，你猜对了么？\n觉得很俗套？我觉得还蛮有趣的，毕竟……我也不在乎有不有趣~"
  },
  Stage_97230_Name = {
    Text = "幕后祸首"
  },
  Stage_97231_Desc = {
    Text = "我们不会忘记每一份恩情，也不会遗忘每一笔仇恨。这是我们生活在这个残酷世界，最后的奢靡。"
  },
  Stage_97231_Name = {
    Text = "永不遗忘"
  },
  Stage_97232_Desc = {
    Text = "抬起你宿醉的脑袋，端起你肮脏的酒杯。忘掉昨夜的一切，新的派对就要到来。\n我的朋友，欢迎来到这座表现主义的乐园。"
  },
  Stage_97232_Name = {
    Text = "野兽主义酒馆"
  },
  Stage_97233_Desc = {
    Text = "当最后一滴酒从杯中落下，埋葬一切的枪声应约响起。"
  },
  Stage_97233_Name = {
    Text = "干涸之酒"
  },
  Stage_97288_Desc = {
    Text = "模拟战斗"
  },
  Stage_97288_Name = {Text = "模拟战3"},
  Stage_97615_Desc = {
    Text = "神唤万物万事各行其道。\n虬结根茎埋入腐土，爪牙鳞羽撕咬爬行。繁花生于枯骨之上，羸弱吞于强大腹中。\n祂赐予众生相互纠缠厮杀的权利。"
  },
  Stage_97615_Name = {
    Text = "第五日·癫狂"
  },
  Stage_97616_Desc = {
    Text = "神将群星归于正位，使日月各司其职。\n光与暗的残骸以癫狂轨迹行路，指引给千万年迷茫的灵魂归途。\n祂赐予虔信者复得的权利。"
  },
  Stage_97616_Name = {
    Text = "第三日·癫狂"
  },
  Stage_97617_Desc = {
    Text = "神使无形的胚种生长在世间。\n有鳍者洄游在海，有翼者翱翔于天。\n祂赐予喃喃絮语伴祂们在深海呼吸，癫乱狂吟伴祂们在云层穿行。"
  },
  Stage_97617_Name = {
    Text = "第四日·之四"
  },
  Stage_97618_Desc = {
    Text = "神使无形的胚种生长在世间。\n有鳍者洄游在海，有翼者翱翔于天。\n祂赐予喃喃絮语伴祂们在深海呼吸，癫乱狂吟伴祂们在云层穿行。"
  },
  Stage_97618_Name = {
    Text = "第四日·之三"
  },
  Stage_97619_Desc = {
    Text = "神让天与地，地与海分离。\n苍穹悬垂下黏稠而搏动的帷幕，硫磺与海盐的气息在深渊中蒸腾升起。\n祂赐予海的子民行于各处的权利。"
  },
  Stage_97619_Name = {
    Text = "第二日·之三"
  },
  Stage_97620_Desc = {
    Text = "神唤万物万事各行其道。\n虬结根茎埋入腐土，爪牙鳞羽撕咬爬行。繁花生于枯骨之上，羸弱吞于强大腹中。\n祂赐予众生相互纠缠厮杀的权利。"
  },
  Stage_97620_Name = {
    Text = "第五日·之六"
  },
  Stage_97621_Desc = {
    Text = "神唤万物万事各行其道。\n虬结根茎埋入腐土，爪牙鳞羽撕咬爬行。繁花生于枯骨之上，羸弱吞于强大腹中。\n祂赐予众生相互纠缠厮杀的权利。"
  },
  Stage_97621_Name = {
    Text = "第五日·之四"
  },
  Stage_97622_Desc = {
    Text = "神让天与地，地与海分离。\n苍穹悬垂下黏稠而搏动的帷幕，硫磺与海盐的气息在深渊中蒸腾升起。\n祂赐予海的子民行于各处的权利。"
  },
  Stage_97622_Name = {
    Text = "第二日·之四"
  },
  Stage_97623_Desc = {
    Text = "神为什么在腐烂，神为什么滴下脓血。\n神明，请指引我，请醒来，救救我啊——无论什么都好！\n哦，神啊，神啊……\n不过是荒谬的错误与虚假的谎言。"
  },
  Stage_97623_Name = {
    Text = "第七日·之六"
  },
  Stage_97624_Desc = {
    Text = "神使无形的胚种生长在世间。\n有鳍者洄游在海，有翼者翱翔于天。\n祂赐予喃喃絮语伴祂们在深海呼吸，癫乱狂吟伴祂们在云层穿行。"
  },
  Stage_97624_Name = {
    Text = "第四日·之六"
  },
  Stage_97625_Desc = {
    Text = "神塑出无智无识的伪形。\n被裹挟来一同沉沦的祭品无法逃脱命运，神没有予以启示，神没有回应，无目无口的婴孩带来虚假的教义。\n祂赐清醒者以迷醉的权利。"
  },
  Stage_97625_Name = {
    Text = "第六日·之六"
  },
  Stage_97626_Desc = {
    Text = "神让天与地，地与海分离。\n苍穹悬垂下黏稠而搏动的帷幕，硫磺与海盐的气息在深渊中蒸腾升起。\n祂赐予海的子民行于各处的权利。"
  },
  Stage_97626_Name = {
    Text = "第二日·之五"
  },
  Stage_97627_Desc = {
    Text = "神为什么在腐烂，神为什么滴下脓血。\n神明，请指引我，请醒来，救救我啊——无论什么都好！\n哦，神啊，神啊……\n不过是荒谬的错误与虚假的谎言。"
  },
  Stage_97627_Name = {
    Text = "第七日·之一"
  },
  Stage_97628_Desc = {
    Text = "神让天与地，地与海分离。\n苍穹悬垂下黏稠而搏动的帷幕，硫磺与海盐的气息在深渊中蒸腾升起。\n祂赐予海的子民行于各处的权利。"
  },
  Stage_97628_Name = {
    Text = "第二日·癫狂"
  },
  Stage_97629_Desc = {
    Text = "神于混沌中以光分别昼夜。\n蠕动光斑将永暗撕裂，祂的子民不必再担心黑暗的威胁。\n祂赐予众人在夜晚安睡的权利。"
  },
  Stage_97629_Name = {
    Text = "第一日·之四"
  },
  Stage_97630_Desc = {
