  Stage_97630_Name = {
    Text = "第三日·之六"
  },
  Stage_97631_Desc = {
    Text = "神为什么在腐烂，神为什么滴下脓血。\n神明，请指引我，请醒来，救救我啊——无论什么都好！\n哦，神啊，神啊……\n不过是荒谬的错误与虚假的谎言。"
  },
  Stage_97631_Name = {
    Text = "第七日·之五"
  },
  Stage_97632_Desc = {
    Text = "神于混沌中以光分别昼夜。\n蠕动光斑将永暗撕裂，祂的子民不必再担心黑暗的威胁。\n祂赐予众人在夜晚安睡的权利。"
  },
