  },
  Stage_97807_Desc = {
    Text = "母亲，是一句人们从出生至死亡之时都会呢喃的咒语。\n没有孩子想要长大，没有孩子不渴望母亲充满爱的怀抱。\n你要扮演那残酷的命运，再一次将她从母亲的怀抱中扯去吗？"
  },
  Stage_97807_Name = {
    Text = "完美童话·癫狂"
  },
  Stage_97808_Desc = {
    Text = "美的文字往往诞生于痛苦。\n她察觉到那些美的时候，就已经知晓那些早已到来的、潜藏于生活影子中的悲剧。\n美啊，美就是短暂而破碎的一切。"
  },
  Stage_97808_Name = {
    Text = "诗意花园·之六"
  },
  Stage_97809_Desc = {
    Text = "如果这一刻的欢乐能够定格，我希望那份记忆的期限是永远。"
  },
  Stage_97809_Name = {
    Text = "一张照片"
  },
  Stage_97810_Desc = {
    Text = "美的文字往往诞生于痛苦。\n她察觉到那些美的时候，就已经知晓那些早已到来的、潜藏于生活影子中的悲剧。\n美啊，美就是短暂而破碎的一切。"
  },
  Stage_97810_Name = {
