    Text = "完美童话·之六"
  },
  Stage_97829_Desc = {
    Text = "太阳早已死去，留在天空的不过是一具风化的尸体。\n正如这个衰朽的世界，在那些厚重灰尘中遗留下的，究竟是生命，还是生命临死前活动的幻影？"
  },
  Stage_97829_Name = {
    Text = "直面黑阳·之三"
  },
  Stage_97830_Desc = {
    Text = "你漫步在熟悉又陌生的校园，看着热闹又平凡的一切，你会为此欣喜着迷吗？还是会悲伤于从来不曾拥有这些？"
  },
  Stage_97830_Name = {
    Text = "故地重游·之四"
  },
  Stage_97831_Desc = {
    Text = "太阳早已死去，留在天空的不过是一具风化的尸体。\n正如这个衰朽的世界，在那些厚重灰尘中遗留下的，究竟是生命，还是生命临死前活动的幻影？"
  },
  Stage_97831_Name = {
    Text = "直面黑阳·之五"
  },
  Stage_97832_Desc = {
    Text = "美的文字往往诞生于痛苦。\n她察觉到那些美的时候，就已经知晓那些早已到来的、潜藏于生活影子中的悲剧。\n美啊，美就是短暂而破碎的一切。"
  },
  Stage_97832_Name = {
    Text = "诗意花园·之三"
  },
  Stage_97833_Desc = {
    Text = "美的文字往往诞生于痛苦。\n她察觉到那些美的时候，就已经知晓那些早已到来的、潜藏于生活影子中的悲剧。\n美啊，美就是短暂而破碎的一切。"
  },
  Stage_97833_Name = {
    Text = "诗意花园·之四"
  },
  Stage_97834_Desc = {
    Text = "母亲，是一句人们从出生至死亡之时都会呢喃的咒语。\n没有孩子想要长大，没有孩子不渴望母亲充满爱的怀抱。\n你要扮演那残酷的命运，再一次将她从母亲的怀抱中扯去吗？"
  },
  Stage_97834_Name = {
    Text = "完美童话·之一"
  },
  Stage_97835_Desc = {
    Text = "她的心中清楚地知晓：一腔孤勇不能换来无可匹敌的胜利，过去如此，现在依然。"
  },
  Stage_97835_Name = {Text = "险胜"},
  Stage_97836_Desc = {
    Text = "太阳早已死去，留在天空的不过是一具风化的尸体。\n正如这个衰朽的世界，在那些厚重灰尘中遗留下的，究竟是生命，还是生命临死前活动的幻影？"
  },
  Stage_97836_Name = {
    Text = "直面黑阳·之一"
  },
  Stage_97837_Desc = {
    Text = "在激昂的赛场上，每位选手都将一展自己的风采……导播，把那些无法播出的风采统统掐掉。"
  },
  Stage_97837_Name = {
    Text = "开始吧！半决赛！"
  },
  Stage_97838_Desc = {
    Text = "母亲，是一句人们从出生至死亡之时都会呢喃的咒语。\n没有孩子想要长大，没有孩子不渴望母亲充满爱的怀抱。\n你要扮演那残酷的命运，再一次将她从母亲的怀抱中扯去吗？"
  },
  Stage_97838_Name = {
    Text = "完美童话·之五"
  },
  Stage_97839_Desc = {
    Text = "你漫步在熟悉又陌生的校园，看着热闹又平凡的一切，你会为此欣喜着迷吗？还是会悲伤于从来不曾拥有这些？"
  },
  Stage_97839_Name = {
    Text = "故地重游·癫狂"
  },
  Stage_97840_Desc = {
    Text = "她不曾忘记她的理想，哪怕是在失去灵魂之后。\n因科学而死的人，曾经也热烈地为科学而活。"
  },
  Stage_97840_Name = {
    Text = "机械之梦·之二"
  },
  Stage_97841_Desc = {
    Text = "太阳早已死去，留在天空的不过是一具风化的尸体。\n正如这个衰朽的世界，在那些厚重灰尘中遗留下的，究竟是生命，还是生命临死前活动的幻影？"
  },
  Stage_97841_Name = {
    Text = "直面黑阳·之二"
  },
  Stage_97842_Desc = {
    Text = "太阳早已死去，留在天空的不过是一具风化的尸体。\n正如这个衰朽的世界，在那些厚重灰尘中遗留下的，究竟是生命，还是生命临死前活动的幻影？"
  },
  Stage_97842_Name = {
    Text = "直面黑阳·之四"
  },
  Stage_97843_Desc = {
    Text = "她不曾忘记她的理想，哪怕是在失去灵魂之后。\n因科学而死的人，曾经也热烈地为科学而活。"
  },
  Stage_97843_Name = {
    Text = "机械之梦·之六"
  },
  Stage_97844_Desc = {
    Text = "你漫步在熟悉又陌生的校园，看着热闹又平凡的一切，你会为此欣喜着迷吗？还是会悲伤于从来不曾拥有这些？"
  },
  Stage_97844_Name = {
    Text = "故地重游·之六"
  },
  Stage_97845_Desc = {
    Text = "你漫步在熟悉又陌生的校园，看着热闹又平凡的一切，你会为此欣喜着迷吗？还是会悲伤于从来不曾拥有这些？"
  },
  Stage_97845_Name = {
    Text = "故地重游·之二"
  },
  Stage_97903_Desc = {
    Text = "回到久违的故乡时，你已成为了那个最格格不入的「异乡人」。"
  },
  Stage_97903_Name = {Text = "归乡"},
  Stage_97904_Desc = {
    Text = "如果要描摹你想要生活的地方，你会绘制怎样一座屋舍，怎样一片郁郁葱葱的树林，和一个怎样的自己？\n你画出的一切，究竟是无瑕的理想，还是深埋的创伤？"
  },
  Stage_97904_Name = {
    Text = "心灵摹写"
  },
  Stage_97905_Desc = {
    Text = "向希望前进的道路，需先亲手斩断希望。"
  },
  Stage_97905_Name = {Text = "清醒梦"},
  Stage_97906_Desc = {
    Text = "和他们告别吧，然后踏上与他们重逢的路。"
  },
  Stage_97906_Name = {Text = "你的梦"},
  Stage_97907_Desc = {
    Text = "最完美的结局亦是最虚假的结局，在所有幸福的笑容里，你必须选择清醒与真实。\n因为你，是那个唯一的守密人。"
  },
  Stage_97907_Name = {
    Text = "虚假结局"
  },
  Stage_97908_Desc = {
    Text = "那些落下的花瓣啊，像一场鲜红的火。"
  },
  Stage_97908_Name = {
    Text = "当花瓣落下"
  },
  Stage_97909_Desc = {
    Text = "如果命运不曾残忍，她们是否也会活成理想最初的模样。"
  },
  Stage_97909_Name = {
    Text = "最初的愿望"
  },
  Stage_97910_Desc = {
    Text = "白色的裙子、床铺、房间，和美梦。"
  },
  Stage_97910_Name = {
    Text = "纯白童话"
  },
  Stage_98000_Desc = {
    Text = "虚假终将破碎，在真正亘古不熄的伟大之物面前，任何阴谋与计算都显得无力且渺小。\n白昼将至，火从琥珀色的北落师门坠陨而下，给万物带来平等的毁灭和死亡。"
  },
  Stage_98000_Name = {
    Text = "亘古不熄的太阳"
  },
  Stage_98829_Desc = {
    Text = "痛苦啊，是催人清醒的良药。"
  },
  Stage_98829_Name = {
    Text = "沉默觉醒·之三"
  },
  Stage_98830_Desc = {
    Text = "传说，双生子的命运注定一生纠缠，无法分割。\n在那片孕育了无数生命的星空下，我们终将重逢。"
  },
  Stage_98830_Name = {
    Text = "双生羽翼·之二"
  },
  Stage_98831_Desc = {
    Text = "托住那双翅膀的风，正如他温柔的双手啊。"
  },
  Stage_98831_Name = {
    Text = "风的托举·癫狂"
  },
  Stage_98832_Desc = {
    Text = "英勇的骑士，热血的冒险，充满希望与挑战的旅途。\n如果故事止于书中的结局，该有多么美好。"
  },
  Stage_98832_Name = {
    Text = "冒险童话·之一"
  },
  Stage_98833_Desc = {
    Text = "忘却一切记忆后，你还是曾经那个你吗？"
  },
  Stage_98833_Name = {
    Text = "遗忘毒药·之五"
  },
  Stage_98834_Desc = {
    Text = "托住那双翅膀的风，正如他温柔的双手啊。"
  },
