  },
  Stage_99725_Desc = {
    Text = "批判不是艺术家的职责，创造才是。"
  },
  Stage_99725_Name = {
    Text = "淤泥上的沙龙"
  },
  Stage_99726_Desc = {
    Text = "我们一直都被困在同一架天平上互相倾轧，但亲爱的弟弟，哪怕不能毁去它，我们原本就可以选择从那座天平上跳下。"
  },
  Stage_99726_Name = {
    Text = "倾倒的天平"
  },
  Stage_99727_Desc = {
    Text = "一对互相依偎的鸟儿，生来就只能在笼中歌唱。"
  },
  Stage_99727_Name = {Text = "双生鸟"},
  Stage_99728_Desc = {
    Text = "目睹真实之人，应当如何忍受虚幻？"
  },
  Stage_99728_Name = {
    Text = "看，月亮"
  },
  Stage_99729_Desc = {
